import type { Schema } from '../../../schema';
import { markStatusBarLocalMutation } from '@util/common';
import { settle_time } from '../../../balance/timeAdvance';
import { syncAllWorkActivation } from './workQueue';
import { reconcile_completed_work_queue } from './workQueueProgress';
import { sync_tribal_affairs } from './tribalAffairsSync';
import {
  archive_completed_comprehensive_affairs,
  archive_settled_pending_affairs,
  backfill_affair_creation_dates,
} from './tribeLog';
import { decay_narrative_corrections, sync_survival_metrics } from './survivalMetricsSync';
import { syncFirepitWithFuel } from './campfire';
import { prune_tribal_affairs, finalize_affairs } from './affairPrune';
import { settle_npc_vitals_by_clock } from '../../../balance/npcVitals';
import { settle_completed_buildings, recompute_defense } from '../../../balance/buildingSettle';
import { quarantine_unapproved_npcs, apply_expelled_from_chat } from '../../../util/npcAdmission';

/**
 * 展示层收口：把结算后的数值反映到玩家看到的东西上。
 *
 * 生成后的同步走 `run_stat_sync_pipeline`；而**指挥模式推进**只走 `advance()`，
 * 不会自动跑这些，所以会出现"燃料 0 但火塘仍写燃烧中、栖居不降、事务不挂"的割裂。
 * 两条路都要调这个函数。
 */
/** 保证派生字段存在且是数字（额外模型常用 delta，字段缺失会直接报错） */
function backfill_derived_numbers(data: Schema): boolean {
  const metrics = data.营地?.生存指标 as unknown as Record<string, unknown> | undefined;
  if (!metrics) return false;
  let changed = false;
  for (const key of Object.keys(metrics)) {
    if (!/_基准$|_修正$/.test(key)) continue;
    const cur = metrics[key];
    if (typeof cur !== 'number' || !Number.isFinite(cur)) {
      metrics[key] = 0;
      changed = true;
    }
  }
  return changed;
}

export function refresh_after_settle(data: Schema): boolean {
  // 逐步隔离：任何一步抛错都不该挡住后面的收口（否则会出现"指标对了、火塘没刷"这种半截状态）
  let changed = false;
  const step = (name: string, fn: () => unknown) => {
    try {
      if (fn()) changed = true;
    } catch (error) {
      console.error('[收口] 步骤失败:', name, error);
    }
  };
  step('回填事务日期', () => backfill_affair_creation_dates(data));
  step('事务去重与上限', () => prune_tribal_affairs(data));
  step('事务同步', () => sync_tribal_affairs(data, null));
  step('归档已结算待办', () => archive_settled_pending_affairs(data));
  step('归档综合事物', () => archive_completed_comprehensive_affairs(data));
  step('建筑完工', () => settle_completed_buildings(data as never));
  step('防御重算', () => recompute_defense(data as never));
  step('派生字段补齐', () => backfill_derived_numbers(data));
  step('NPC生理结算', () => settle_npc_vitals_by_clock(data));
  step('驱逐指令', () => { apply_expelled_from_chat(data); return true; });
  step('入营审批', () => { quarantine_unapproved_npcs(data); return true; });
  step('指标收口', () => sync_survival_metrics(data));
  step('事务收尾与日志裁剪', () => finalize_affairs(data));
  step('队列激活', () => {
    syncAllWorkActivation(data);
    return false;
  });
  step('火塘状态', () => {
    syncFirepitWithFuel(data.营地.当前建筑, data.营地.篝火燃料);
    return false;
  });
  return changed;
}

/**
 * 统一时间 tick。
 *
 * Δt 只有一个来源：`balance/timeAdvance.settle_time`（水印 → 当前世界时间）。
 * 这里只负责「拿 Δt / 标记本地变更」，推进逻辑一律在 settle_subsystems 里：
 *   燃料 / 口粮 / 工作队列 / 探索编队 / 建筑 / 腐坏 / 临时仓 / 指标
 *
 * 历史教训（别再改回去）：
 *   1. 旧版本用模块级 `last_tick + getChatMessages(-2).variables` 猜 Δt —— 那个字段不存在，
 *      等于恒为 null，工作队列与编队按小时推进**一直静默失效**；
 *   2. 用模块级状态也意味着 reload 会重算，配合"每次结算都改数值"就会重复扣。水印放在
 *      stat_data 里（跟着存档走），所以 reload / 一次加载跑 1~3 遍都不会双扣。
 *
 * 仓储（口粮/腐坏/临时仓）在实时管线里由 `settlementSync` 的聊天记录回放拥有，
 * 所以这里传 `{ 仓储: false }`，避免两处都算一遍。
 */
export function sync_world_time_tick(data: Schema): boolean {
  let changed = reconcile_completed_work_queue(data);

  const settle = settle_time(data, { 仓储: false });
  if (settle.hours > 0) {
    changed = true;
    if (settle.day_rollovers > 0) {
      changed = decay_narrative_corrections(data, settle.day_rollovers) || changed;
    }
    console.info(
      `[时间] 结算 ${settle.hours.toFixed(2)}h（内含 ${settle.day_rollovers} 次跨日）`,
      settle.events.map(e => e.verb),
    );
  }

  changed = refresh_after_settle(data) || changed;

  if (!changed) {
    return false;
  }

  markStatusBarLocalMutation(10000);
  return changed;
}
