export type StatSyncModule = 'npc' | 'affairs' | 'vastLand' | 'camp' | 'warehouse';

export const DEFAULT_STAT_SYNC_MODULES: StatSyncModule[] = [
  'npc',
  'affairs',
  'vastLand',
  'camp',
  'warehouse',
];

export type StatSyncContext = {
  message_id: number;
  story?: string;
  messageText?: string;
  modules?: StatSyncModule[];
};

let syncing = false;
/** 锁开始时间：用于卡死超时接管 */
let syncing_since = 0;
/** 同步锁最长持有时间（超过就认为上一轮卡住了） */
const SYNC_LOCK_TIMEOUT_MS = 45_000;

function has_modules(ctx: StatSyncContext, module: StatSyncModule): boolean {
  return (ctx.modules ?? DEFAULT_STAT_SYNC_MODULES).includes(module);
}

/** 在已有 stat 上按模块顺序跑同步（不写 MVU） */
export function run_stat_sync_pipeline(stat: Schema, ctx: StatSyncContext): boolean {
  let changed = false;

  // 仓库容量系数：每座「已建成的储存类建筑」+25%（没有则维持基础容量）
  try {
    const buildings = (stat.营地 as unknown as {
      当前建筑?: Record<string, { 建筑阶段?: string; 功能标签?: string[] }>;
    }).当前建筑 ?? {};
    let storage_count = 0;
    for (const [name, b] of Object.entries(buildings)) {
      if (!b || b.建筑阶段 !== '已建成') continue;
      if (is_storage_building(name, b as { 功能标签?: string[]; 建筑阶段?: string })) storage_count += 1;
    }
    set_storage_bonus(1 + 0.25 * storage_count);
  } catch {
    set_storage_bonus(1);
  }

  // 见闻归档（方案 A）：活跃上限 20 条，超出部分把最旧的标记为已归档
  try {
    const JOURNAL_LIMIT = 20
    const journal = (stat.大地见闻 ?? {}) as Record<
      string,
      { 序号?: number; 归档?: boolean }
    >
    const entries = Object.entries(journal)
    if (entries.length > 0) {
      // ① 没编号的按当前键顺序补号（对象属性顺序即写入顺序）
      let next = entries.reduce((max, [, v]) => Math.max(max, Number(v?.序号 ?? -1)), -1) + 1
      for (const [, v] of entries) {
        if (!v) continue
        if (typeof v.序号 !== 'number' || !Number.isFinite(v.序号)) {
          v.序号 = next
          next += 1
        }
      }
      // ② 活跃条数超限 → 把序号最小的未归档条目归档
      const active = entries
        .filter(([, v]) => v && !v.归档)
        .sort((a, b) => Number(a[1].序号 ?? 0) - Number(b[1].序号 ?? 0))
      let overflow = active.length - JOURNAL_LIMIT
      for (const [, v] of active) {
        if (overflow <= 0) break
        v.归档 = true
        overflow -= 1
      }
    }
  } catch (e) {
    console.warn('[见闻归档] 失败（忽略）:', e)
  }

  // 区域数量硬校验 + 来源自动判定（探索系统 v3 审核 B-1 / B-3）
  // GLM 指出：上限 12 只写在世界书里，LLM 数数不可靠；来源字段靠 AI 写也容易漏。
  try {
    const PRESET_AREA_NAMES = new Set(['湖畔营地', '飞船残骸周边', '中央大陆林缘', '坠星盆地外围']);
    const AREA_LIMIT = 12;
    const areas = (stat.探索区域 ?? {}) as Record<
      string,
      { 来源?: string; 状态?: string; 累计采集次数?: number; 累计狩猎次数?: number }
    >;

  // 孤儿引用兜底（放弃区域功能配套）：编队的 目标区域 若指向已不存在的区域，清空。
  //
  // ⚠ 回溯审查（Claude）指出：原来这里还顺手 delete 了 squad.本次派遣，
  // 这是无条件删除 —— AI 只要把区域名写错一个字，正在进行的派遣状态就会凭空丢失
  // （队伍"消失又空手回来"）。派遣状态关系到人员、时长、资源，不能靠区域名推断。
  // 现在只清 目标区域（那是"想去哪"的意向），不动 本次派遣（那是"已发生的事实"）。
  for (const squad of Object.values((stat.探索编队 ?? {}) as Record<string, Record<string, unknown>>)) {
    if (!squad) continue;
    const target = String(squad.目标区域 ?? '');
    if (target && !areas[target]) {
      squad.目标区域 = '';
      console.info('[区域校验] 编队目标区域已不存在，清空:', target);
    }
  }

    // 旧档兼容：v3 之后新增了 区域简报 / 资源倾向，老存档里没有这几个字段，
    // 导致区域弹窗只显示一句描述（实机反馈：同一张图里有些区域详细、有些只有一句话）。
    // 这里按预设表确定性补齐，缺什么补什么，已有内容不动。
    for (const [name, area] of Object.entries(areas)) {
      const preset = (EXPLORATION_AREA_DEFAULTS as Record<string, Record<string, unknown>>)[name]
      if (!preset || !area) continue
      const target = area as Record<string, unknown>
      const brief = target.区域简报 as { 概述?: string; 动物?: string[] } | undefined
      if (!brief?.概述) {
        target.区域简报 = {
          概述: (preset.区域简报 as { 概述?: string })?.概述 ?? '',
          动物: Array.isArray((preset.区域简报 as { 动物?: string[] })?.动物)
            ? [...((preset.区域简报 as { 动物?: string[] }).动物 as string[])]
            : [],
        }
      }
      if (!Array.isArray(target.资源倾向) || (target.资源倾向 as string[]).length === 0) {
        target.资源倾向 = Array.isArray(preset.资源倾向) ? [...(preset.资源倾向 as string[])] : []
      }
      if (!target.特产 && typeof preset.特产 === 'string') target.特产 = preset.特产
      if (!target.距离 && typeof preset.距离 === 'string') target.距离 = preset.距离
    }

    // B-3：不在预设名单里的一律判为「玩家发现」，覆盖 AI 漏写
    for (const [name, area] of Object.entries(areas)) {
      if (!area) continue;
      area.来源 = PRESET_AREA_NAMES.has(name) ? '预设' : '玩家发现';
    }

    // B-1：超限时丢弃最近写入的玩家发现区域（保留预设），并写一条见闻
    const entries = Object.entries(areas);
    if (entries.length > AREA_LIMIT) {
      const discovered = entries.filter(([, a]) => a?.来源 === '玩家发现');
      let overflow = entries.length - AREA_LIMIT;
      while (overflow > 0 && discovered.length > 0) {
        const [name] = discovered.pop() as [string, unknown];
        delete areas[name];
        overflow -= 1;
        const journal = (stat.大地见闻 ?? {}) as Record<string, unknown>;
        journal[`区域失联·${name}`] = {
          内容: `那片地界再没走通过，图上留了个记号。`,
          来源: '探索记录',
          时间: String((stat.世界 as { 兽历?: string })?.兽历 ?? ''),
          已处理: true,
        };
        (stat as unknown as { 大地见闻?: unknown }).大地见闻 = journal;
      }
    }
  } catch (e) {
    console.warn('[区域校验] 失败（忽略）:', e);
  }


  // 补丁兜底（放在最前）：
  // ① delta-on-missing 补成 add，避免整条补丁被 MVU 拒绝
  // ② 整表 replace 后把「仍在进行中」的项还原回来
  try {
    const text = String(ctx.messageText ?? '');
    if (text) changed = repair_delta_on_missing(stat, text) || changed;
    const g = globalThis as unknown as {
      __zx_local_record_snapshot?: Record<string, Record<string, unknown>>;
    };
    changed = restore_local_records(stat, g.__zx_local_record_snapshot) || changed;
    g.__zx_local_record_snapshot = {
      工作队列: JSON.parse(JSON.stringify(stat.工作队列 ?? {})),
      探索编队: JSON.parse(JSON.stringify(stat.探索编队 ?? {})),
      综合事物: JSON.parse(JSON.stringify(stat.综合事物 ?? {})),
    };
  } catch (e) {
    console.warn('[补丁修复] 失败（忽略）:', e);
  }

  if (has_modules(ctx, 'npc')) {
    changed = purge_misclassified_named_npcs(stat as Record<string, unknown>) || changed;
    changed = replayNpcInnerStateFromChat(stat, ctx.message_id) || changed;
    changed = replayNpcActionRecordsFromChat(stat, ctx.message_id) || changed;
  }

  if (has_modules(ctx, 'affairs')) {
    changed = sync_comprehensive_affairs(stat) || changed;
    changed = completePendingAffairsFromSettlementChatHistory(stat, ctx.message_id) || changed;
    changed = archive_settled_pending_affairs(stat) || changed;
  }

  if (has_modules(ctx, 'vastLand')) {
    changed = apply_user_squad_commands(stat) || changed;
    // 派队也走玩家指令（广阔大地 写进输入栏的那条 [外出采集] …），不再依赖模型写 NPC 面板
    changed = apply_user_squad_dispatch(stat) || changed;
    if (!debug_skip('purge')) {
      changed = purge_unauthorized_exploration_squads(stat, ctx.message_id) || changed;
    }
    if (!debug_skip('settle')) {
      changed = sync_squads_from_settlement_chat_history(stat, ctx.message_id) || changed;
    }
    if (!debug_skip('return')) {
      changed = sync_squads_from_return_story(stat) || changed;
    }
    if (!debug_skip('reconcile')) {
      changed = reconcile_exploration_squads(stat) || changed;
    }
    changed = reconcile_squad_member_exclusivity(stat) || changed;
    changed = ensure_exploration_area_catalog(stat) || changed;
  }

  if (has_modules(ctx, 'camp')) {
    changed = reconcile_completed_work_queue(stat) || changed;
    // 我们自己的时间推进指令：[时间推进] N小时/天（幂等，按楼层号去重）
    changed = apply_user_time_command(stat, ctx.message_id) || changed
    // 燃料夹取：模型/旧档可能把 当前 写成超过上限（实机见过 30 > 上限 20）
    {
      const fuel = stat.营地?.篝火燃料
      if (fuel) {
        const cap = Number(fuel.上限) > 0 ? Number(fuel.上限) : 20
        const now = Number(fuel.当前) || 0
        const clamped = Math.min(cap, Math.max(0, now))
        if (clamped !== now) {
          fuel.当前 = clamped
          changed = true
        }
      }
    }
    // 写权闸口（P5 前的临时版）：人口必须等于 Σ族人构成，模型单改一个人口会被拉回来
    changed = align_population(stat.营地) || changed;
    changed = sync_work_queue_from_settlement_chat_history(stat, ctx.message_id) || changed;
    const msgText = ctx.messageText ?? '';
    if (msgText) {
      changed = repair_work_queue_removes_from_message(stat, msgText) || changed;
    }
    for (const msg of typeof getChatMessages === 'function'
      ? getChatMessages(`0-${ctx.message_id}`).filter(m => m.role === 'assistant')
      : []) {
      changed = repair_work_queue_removes_from_message(stat, msg.message) || changed;
    }
    syncAllWorkActivation(stat);
    // 指标统一在 pipeline 末尾收口（见下方「指标收口必须放在最后」），此处不再重复计算
    sync_world_time_tick(stat);
  }

  if (has_modules(ctx, 'warehouse')) {
    changed = replayWarehouseReservesFromChat(stat, ctx.message_id) || changed;
  // 面板指令必须在仓储回放**之后**执行：回放会从开局基准整份重建，
  // 若先扣料再回放，这轮扣料会被抹掉（审查 P1-2 / A1）
  if (ctx.messageText) changed = apply_panel_commands(stat, ctx.messageText, ctx.message_id) || changed;
    changed = sync_user_warehouse_deposits(stat) || changed;
    changed = repairMisplacedWarehouse(stat) || changed;
    changed = clampWarehouseReserves(stat) || changed;
    // 注意：**不要**再在实时管线里调 `inferCampfireFuelFromStory`。
    // 实机踩过：燃料按 Δt 烧到 0 之后，这个"按剧情推断生火"的补丁看到
    // 「火塘状态=稳定燃烧 + 燃料=0」就把燃料回补到 15 —— 于是火永远烧不完，
    // 而指标（在同轮更早处算）又按"没火"给出 栖居 0 / 向心 20，同一轮自相矛盾。
    // 燃料的唯一写入方是 `advance/settle_time`；推断只在开局修复路径里用。
    syncFirepitWithFuel(stat.营地.当前建筑, stat.营地.篝火燃料);
  }

  // 指标收口必须放在最后：仓库/燃料/队列/编队都改完之后再算，
  // 否则会拿"上一轮的数"算派生值（实机表现为 栖居 0 但燃料 15）。
  if (has_modules(ctx, 'camp')) {
    changed = sync_survival_metrics(stat) || changed;
  }

  return changed;
}

/**
 * 把事件给的 message_id 落成一个**真实存在**的楼层号。
 *
 * 实机踩过：GENERATION_ENDED 有时会在消息真正进入 chat 之前就发出来（其它消息处理扩展
 * 还会增删楼层），于是 `getChatMessages(4)` 撞上 "楼层号 '4' 超出了范围 [-4, 4)"，
 * 整个 pipeline 直接抛错 —— 那一轮就什么都不会同步（腐坏/临时仓/水印全都停摆）。
 * 这里先重试几次，实在不行就退到"最后一条 assistant 楼层"。
 */
async function resolve_sync_message_id(requested: number): Promise<number | null> {
  if (typeof getChatMessages !== 'function') {
    return null;
  }
  for (let attempt = 0; attempt < 4; attempt += 1) {
    try {
      const hit = getChatMessages(requested)[0];
      if (hit && typeof hit.message_id === 'number') {
        return hit.message_id;
      }
    } catch {
      /* 楼层还没进 chat，等一拍再试 */
    }
    await new Promise(resolve => setTimeout(resolve, 400));
  }
  try {
    const latest = getChatMessages(-1, { role: 'assistant' })[0];
    if (latest && typeof latest.message_id === 'number') {
      console.warn('[坠星数据同步] 目标楼层不存在，退到最新 assistant 楼层', latest.message_id);
      return latest.message_id;
    }
  } catch {
    /* ignore */
  }
  return null;
}

/**
 * 调试用跳过开关（只读 localStorage，默认全开）。
 * 用来二分定位"编队状态被谁打回"这种问题：把步骤名写进 `__zx_skip` 再重载即可。
 */
function debug_skip(step: string): boolean {
  try {
    const raw = String(localStorage.getItem('__zx_skip') ?? '')
    return raw.split(',').map(s => s.trim()).includes(step)
  } catch {
    return false
  }
}

/** 从指定楼层读取 stat → 跑 pipeline → 写回 MVU（单次写回） */
export async function run_stat_sync_from_message(ctx: StatSyncContext): Promise<void> {
  // 只在"同一次同步重入"时短路。
  // **不要**再用 isStatusBarLocalMutation() 做门禁：那是给 store 的 pull 用的 8~15s 窗口，
  // 状态栏自愈/开局写入会把它续上，结果整轮管线被跳过 —— 实机表现为
  // 时间不回正（19:58 停着）、指标停在旧值（显示值 ≠ 基准+修正）。P1/P2 同步根因。
  if (syncing) {
    // 锁卡死保护：上一轮如果因为 await 挂住没走到 finally，这里超时强制接管。
    const held = Date.now() - syncing_since;
    if (held < SYNC_LOCK_TIMEOUT_MS) {
      return;
    }
    console.warn('[坠星数据同步] 上一轮同步卡了', Math.round(held / 1000), '秒，强制接管');
  }

  syncing = true;
  syncing_since = Date.now();
  let message_id = ctx.message_id;
  try {
    const resolved = await resolve_sync_message_id(message_id);
    if (resolved === null) {
      console.warn('[坠星数据同步] 拿不到可用楼层，跳过本轮', message_id);
      return;
    }
    message_id = resolved;

    if (has_modules(ctx, 'npc')) {
      await syncNpcPanelsFromMessage(message_id);
    }

    await waitGlobalInitialized('Mvu');
    const option = { type: 'message', message_id } as const;
    const mvu_data = Mvu.getMvuData(option);
    const stat = _.get(mvu_data, 'stat_data') as Schema | undefined;
    if (!stat || typeof stat !== 'object') {
      return;
    }

    const msg = getChatMessages(message_id)[0];
    const story = ctx.story ?? extractStoryFromMessage(msg?.message ?? '');
    const fullCtx: StatSyncContext = {
      ...ctx,
      message_id,
      story,
      messageText: ctx.messageText ?? msg?.message ?? '',
    };

    const changed = run_stat_sync_pipeline(stat, fullCtx);
    if (!changed) {
      return;
    }

    _.set(mvu_data, 'stat_data', stat);
    await Mvu.replaceMvuData(mvu_data, option);
    console.info('[坠星数据同步] 已写回楼层', message_id);
  } catch (error) {
    console.error('[坠星数据同步] 失败', message_id, error);
  } finally {
    syncing = false;
  }
}

/** 启动时：回填空 NPC + 同步最新 AI 楼 */
export async function run_stat_sync_startup(): Promise<void> {
  await backfillNpcPanelsIfEmpty();
  const latest = getChatMessages(-1, { role: 'assistant' })[0];
  if (latest) {
    await run_stat_sync_from_message({
      message_id: latest.message_id,
    });
  }
}

export async function run_stat_sync_after_swipe(message_id: number): Promise<void> {
  await run_stat_sync_from_message({ message_id });
  await cascade_purge_squads_after_regenerate(message_id);
}

export async function run_stat_sync_after_generation(message_id: number): Promise<void> {
  // 删层后跳过一次同步：否则本地残留状态会被写回上一楼层（审查 P2-2b）
  const should_skip = (globalThis as unknown as { __zx_should_skip_sync?: () => boolean }).__zx_should_skip_sync;
  if (typeof should_skip === 'function' && should_skip()) {
    console.info('[数据同步] 删层后的第一轮同步已跳过');
    return;
  }
  const msgs = getChatMessages(message_id);
  const msg = msgs[0];
  const story = extractStoryFromMessage(msg?.message ?? '');
  await run_stat_sync_from_message({
    message_id,
    story,
    messageText: msg?.message ?? '',
  });
  await cascade_purge_squads_after_regenerate(message_id);
}
