/**
 * 建筑完工结算 + 防御值重算（P3-c 尾部 / P4 尾部）
 *
 * 完工：建筑阶段「建造中」且所需工时已归零 → 「已建成」，状态「完好」
 * 防御：总防御 = 建筑加成 + 守卫加成（全部前端派生，禁止 AI 写）
 */



type Building = {
  建筑阶段?: string
  状态?: string
  所需工时?: number
  完工效果?: { 防御值?: number; 栖居?: number }
}


type Stat = {
  部族日志?: Record<string, { 关联键?: string; 类型?: string; 完成日期?: string }>
  营地?: {
    当前建筑?: Record<string, Building>
      防御?: { 建筑加成?: number; 守卫加成?: number; 总防御?: number }
  }
  具名NPC?: Record<string, { 当前任务?: string; 状态?: string }>
}

/** 建造中且工时归零 → 已建成 */
/** 归一化：'交付清点·X' / 'X·待交付' → 'X' */
function normalize_key(key: string): string {
  return String(key ?? '')
    .replace(/^交付清点·/, '')
    .replace(/·待交付$/, '')
    .trim()
}

/** 是否已有该建筑的完工归档（交付清点结算后写日志） */
function has_delivered_log(stat: Stat, name: string): boolean {
  for (const [key, log] of Object.entries(stat.部族日志 ?? {})) {
    if (!log) continue
    const k = normalize_key(log.关联键 || key)
    if (k === name) return true
  }
  return false
}

export function settle_completed_buildings(stat: Stat): boolean {
  const buildings = stat.营地?.当前建筑
  if (!buildings) return false
  let changed = false
  for (const [name, b] of Object.entries(buildings)) {
    if (!b) continue
    if (b.建筑阶段 !== '建造中') continue
    // 只认「交付清点已归档」为完工依据（审查 P1-9）：
    // 此前「工时缺失/为 0」也算完工，导致 AI 漏写工时 → 免料免工直接已建成。
    if (!has_delivered_log(stat, name)) continue
    b.建筑阶段 = '已建成'
    b.状态 = '完好'
    changed = true
    console.info('[建筑] 完工:', name)
  }
  return changed
}

/** 重算营地防御（派生值） */
export function recompute_defense(stat: Stat): boolean {
  const camp = stat.营地
  if (!camp) return false

  // 围栏已并入「护栏类建筑」：防御全部由已建成的防御类建筑提供
  const 建筑加成 = Object.values(camp.当前建筑 ?? {}).reduce((sum, b) => {
    // 「升级中」仍算生效：否则一升级防御就掉，玩家会以为被偷了
    const stage = (b as { 建筑阶段?: string })?.建筑阶段
    if (!b || (stage !== '已建成' && stage !== '升级中')) return sum
    const explicit = Number(b.完工效果?.防御值 ?? 0) || 0
    const tags = Array.isArray((b as { 功能标签?: string[] }).功能标签)
      ? ((b as { 功能标签?: string[] }).功能标签 as string[])
      : []
    // 带「防御」标签的建筑：每层 +5，可叠加（同名建筑重复规划会累加层数）
    // 等级即层数：Lv1/2/3 → +5/+10/+15（层数字段为旧档兼容，取两者较大值）
    const layers = Math.max(
      1,
      Number((b as { 等级?: number }).等级 ?? 1) || 1,
      Number((b as { 层数?: number }).层数 ?? 1) || 1,
    )
    const from_tag = tags.includes('防御') ? 5 * layers : 0
    // 有显式数值就用显式的（乘以层数），否则用标签规则
    return sum + (explicit > 0 ? explicit * layers : from_tag)
  }, 0)

  // 守卫：当前任务或状态里写了「守」的成员，每人 +2
  const 守卫人数 = Object.values(stat.具名NPC ?? {}).filter(n => {
    if (!n) return false
    const text = `${n.当前任务 ?? ''}${n.状态 ?? ''}`
    return /守|巡逻|放哨|警戒/.test(text)
  }).length
  const 守卫加成 = 守卫人数 * 2

  const 总防御 = Math.round((建筑加成 + 守卫加成) * 10) / 10

  const prev = camp.防御 ?? {}
  if (
    prev.建筑加成 === 建筑加成 &&
    prev.守卫加成 === 守卫加成 &&
    prev.总防御 === 总防御
  ) {
    return false
  }

  camp.防御 = { 建筑加成, 守卫加成, 总防御 }
  return true
}

/** 交付清点被结算 → 对应建筑完工 */
export function complete_building_by_delivery(stat: Stat, affair_name: string): boolean {
  const m = String(affair_name ?? '').match(/^交付清点·(.+)$/)
  if (!m) return false
  const name = m[1].trim()
  const building = stat.营地?.当前建筑?.[name]
  if (!building) return false
  if (building.建筑阶段 === '已建成') return false
  building.建筑阶段 = '已建成'
  building.状态 = '完好'
  console.info('[建筑] 交付清点完成 → 已建成:', name)
  return true
}
