/**
 * 时间推进模块（我们自己的，不依赖预设）
 *
 * 玩家/面板把 `[时间推进] N小时｜…` 写进聊天框，发送后这条消息就是"时间要往前走"的指令。
 * 管线读到它 → 用 balance/timeAdvance.advance() 结算 → 变量与正文从此同一个时间轴。
 *
 * 幂等：`世界.已处理时间指令` 记住最后处理的楼层号，同一层只推进一次
 * （管线一次加载会跑 1~3 遍，重复推进会直接毁档）。
 */
import type { Schema } from '../schema'

const CMD_RE = /\[时间推进\]\s*(\d+(?:\.\d+)?)\s*(小时|天)/


export type TimeCommand = { message_id: number; hours: number; raw: string }

/** 从一段文本里解析时间推进指令 */
export function parse_time_command(text: string): { hours: number } | null {
  if (!text) return null
  const raw = String(text)
    const m = raw.match(CMD_RE)
  if (!m) return null
  const amount = Number(m[1])
  if (!Number.isFinite(amount) || amount <= 0) return null
  const hours = m[2] === '天' ? amount * 24 : amount
  return { hours: Math.min(hours, 24 * 30) }
}

/** 找出"最新一条含时间推进指令的用户楼层" */
export function find_latest_time_command(max_message_id: number): TimeCommand | null {
  if (typeof getChatMessages !== 'function' || max_message_id < 0) return null
  const msgs = getChatMessages(`0-${max_message_id}`).filter(m => m.role === 'user')
  for (let i = msgs.length - 1; i >= 0; i -= 1) {
    const msg = msgs[i]
    const parsed = parse_time_command(msg.message)
    if (parsed) {
      return { message_id: msg.message_id, hours: parsed.hours, raw: msg.message }
    }
  }
  return null
}

/** 应用时间指令（幂等）。返回是否发生变更 */
export function apply_user_time_command(stat: Schema, max_message_id: number): boolean {
  const cmd = find_latest_time_command(max_message_id)
  if (!cmd) return false
  const processed = Number(stat.世界.已处理时间指令 ?? -1)
  if (processed >= cmd.message_id) return false

  // 【架构】时间由**模型**写入 世界.时间（按正文剧情推进）；管线不再自己推时钟。
  // 这里只记录"这条指令已处理"，避免重复解析；燃料/口粮由楼层 Δt 结算负责。
  // （此前 advance() 会与模型的 patch 双推，实测 12h 只结算 8h。）
  stat.世界.已处理时间指令 = cmd.message_id
  console.info('[时间] 已记录推进指令', cmd.hours, '小时（时间由模型写入，管线不推进）')
  return false
}
