import type { Schema } from '../../../schema';

/**
 * 部族事务 / 综合事物的清洗与上限。
 *
 * 目的：
 *   1. 去重 —— 已归档到【部族日志】的事务，禁止再插回同名主要事务（世界书有要求，但 AI 不一定守）；
 *   2. 上限 —— 事务表不能被 AI 无限堆积（实机见过一口气写 7 条主要事务）；
 *   3. 保序 —— 超限时优先保留「有剩余时间」的（紧迫）与新近创建的。
 */

const CAPS = {
  主要: 3,
  次要: 5,
  综合: 8,
} as const;

/** 提取排序用权重：有剩余时间 > 有创建日期 > 其他 */
function urgency(affair: { 剩余时间?: string; 创建日期?: string }): number {
  let score = 0;
  if (affair.剩余时间) score += 100;
  if (affair.创建日期) score += 10;
  return score;
}

/** 事务名是否已经出现在归档日志里 */
function is_archived(data: Schema, name: string): boolean {
  for (const log of Object.values(data.部族日志 ?? {})) {
    if (!log) continue;
    if (log.关联键 && log.关联键 === name) return true;
  }
  return false;
}


/** 待结算的归来/交付清点：被裁掉会导致战利品与建筑回写永久丢失 */
function is_protected_settlement(name: string, item?: { 状态?: string; 元数据?: { 类型?: string } }): boolean {
  if (!/^归来清点·|^交付清点·/.test(name)) return false;
  // 已完成的可以裁；进行中的必须保留
  return item?.状态 !== '已完成';
}

export function prune_tribal_affairs(data: Schema): boolean {
  let changed = false;

  // ---- 0) 级别重算：紧迫的自动升为主要（AI 分级不可靠） ----
  const URGENT = /断粮|断火|缺柴|断电|受伤|逃离|疫病|寒夜|寒潮|野兽|入侵|坍塌|失温|缺水/;
  for (const [name, affair] of Object.entries(data.部族事务 ?? {})) {
    if (!affair) continue;
    const shouldBeMain = Boolean(affair.剩余时间) || URGENT.test(name) || URGENT.test(affair.说明 ?? '');
    const next = shouldBeMain ? '主要' : '次要';
    if (affair.级别 !== next) {
      affair.级别 = next;
      changed = true;
    }
  }

  // ---- 1) 部族事务：去重 + 分级上限 ----
  const affairs = data.部族事务 ?? {};
  const kept: string[] = [];
  for (const [name, affair] of Object.entries(affairs)) {
    if (!affair) {
      delete affairs[name];
      changed = true;
      continue;
    }
    if (is_archived(data, name)) {
      console.info('[部族事务] 已归档，丢弃重复插入:', name);
      delete affairs[name];
      changed = true;
      continue;
    }
    kept.push(name);
  }

  for (const level of ['主要', '次要'] as const) {
    const names = kept.filter(n => affairs[n]?.级别 === level);
    const cap = CAPS[level];
    if (names.length <= cap) continue;
    const sorted = [...names].sort((a, b) => {
      const diff = urgency(affairs[b]!) - urgency(affairs[a]!);
      if (diff !== 0) return diff;
      return names.indexOf(b) - names.indexOf(a); // 同权重保留较新的
    });
    for (const name of sorted.slice(cap)) {
      console.info(`[部族事务] 超过${level}上限 ${cap}，移除:`, name);
      delete affairs[name];
      changed = true;
    }
  }

  // ---- 2) 综合事物：上限（已完成优先清，其次最旧） ----
  const items = data.综合事物 ?? {};
  // 已完成项留待归档流程处理（裁剪若先删掉它们，日志与建筑回写都会丢失，见审查 P1-8）
  const itemNames = Object.keys(items).filter(
    name => items[name]?.状态 !== '已完成' && !is_protected_settlement(name, items[name]),
  );
  if (itemNames.length > CAPS.综合) {
    const sorted = [...itemNames].sort((a, b) => {
      const doneA = items[a]?.状态 === '已完成' ? 1 : 0;
      const doneB = items[b]?.状态 === '已完成' ? 1 : 0;
      if (doneA !== doneB) return doneB - doneA; // 已完成排前面等着被删
      return 0;
    });
    for (const name of sorted.slice(0, itemNames.length - CAPS.综合)) {
      console.info('[综合事物] 超过上限，移除:', name, items[name]?.状态);
      delete items[name];
      changed = true;
    }
  }

  return changed;
}

/** 解析 1年9月1日 → 天数序号（解析失败返回 null） */
function dateIndex(兽历: string | undefined): number | null {
  const m = String(兽历 ?? '').match(/(\d{4})\D+(\d{1,2})\D+(\d{1,2})/);
  if (!m) return null;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return Number.isNaN(d.getTime()) ? null : Math.floor(d.getTime() / 86400000);
}

/**
 * 收尾：放在归档之后跑。
 *  1) 「待定」超过 3 天 → 标记已完成（由归档流程移入日志），避免僵尸事项永久占位；
 *  2) 部族日志超过上限 → 保留最近 N 条（按完成日期）。
 */
export function finalize_affairs(data: Schema, log_cap = 20): boolean {
  let changed = false;
  const now = dateIndex(data.世界.兽历);

  if (now !== null) {
    for (const [name, item] of Object.entries(data.综合事物 ?? {})) {
      if (!item || item.状态 !== '待定') continue;
      const created = dateIndex(item.创建日期);
      if (created === null) continue;
      if (now - created >= 3) {
        item.状态 = '已完成';
        item.说明 = `${item.说明}（久未处理，自动归档）`;
        console.info('[综合事物] 待定超 3 天，自动归档:', name);
        changed = true;
      }
    }
  }

  const logs = data.部族日志 ?? {};
  const keys = Object.keys(logs);
  if (keys.length > log_cap) {
    const sorted = [...keys].sort((a, b) => {
      const ai = dateIndex(logs[a]?.完成日期) ?? 0;
      const bi = dateIndex(logs[b]?.完成日期) ?? 0;
      return bi - ai;
    });
    for (const key of sorted.slice(log_cap)) {
      delete logs[key];
      changed = true;
    }
    console.info('[部族日志] 超过上限，已裁到', log_cap, '条');
  }

  return changed;
}
