import { is_storage_building } from '../界面/状态栏/util/settlementSync';
/**
 * 坠星大陆 · 生存指标派生公式（唯一实现）
 *
 * 三个 `_基准` 全部由配方算出，**不是在别处手写的数**（审计文档 §五「五层骨架」）。
 * 实时 UI（`survivalMetricsSync`）与离线模拟器（`_audit/balance-v2.mjs`）都调这里，
 * 这样"模拟器算出来的温饱"和"真机显示的温饱"才可能是同一个数。
 *
 * 口粮折算走 `CONSUME.UNIT_TO_RATION`（`balance/table.ts`）——以前 UI 里另有一张正则食物表，
 * 两张表各说各话，已在这里收口。
 */
import type { Schema } from '../schema'
import { CONSUME, foodDaysScore } from './table'
import {
  dailyFuelBurn,
  fuelHoursRemaining,
  isFireLit,
  resolveFirepitKey,
} from '../界面/状态栏/util/campfire'

type Camp = Schema['营地']

/** 食物储备档位加成 */
export const FOOD_RESERVE_BONUS: Record<Camp['营地状态']['食物储备'], number> = {
  极度匮乏: 0,
  勉强果腹: 8,
  储备充足: 18,
}

/** 住所等级分值 */
export const SHELTER_LEVEL_SCORE: Record<Camp['营地状态']['住所等级'], number> = {
  露宿: 0,
  简陋窝棚: 12,
  稳固聚落: 28,
  石砌聚落: 42,
  舰城生活区: 55,
}

export function clamp_metric(value: number): number {
  return Math.max(0, Math.min(100, Math.round(value)))
}

/**
 * 1 单位该物资折算多少份标准口粮。
 * 表里登记过的以表为准（`UNIT_TO_RATION: 2` = 两单位一份口粮）；表里没有的，
 * 保留一条正则兜底，供"未登记但明显是口粮"的名字用 —— P2 的 ItemDef 登记表补齐后应删掉。
 */
export function rations_per_unit(name: string): number | null {
  const factor = CONSUME.UNIT_TO_RATION[name]
  if (factor > 0) {
    return 1 / factor
  }
  if (/方便面|能量棒|蛋白棒|压缩饼干|罐头|口粮|自热/.test(name)) return 1
  if (/风干肉/.test(name)) return 2
  if (/生肉|烤肉|烟熏|熏肉|熟肉|肉条/.test(name)) return 1
  if (/块茎|野果|菌菇|浆果|植物|果/.test(name)) return 0.5
  return null
}

/** 营地现有总口粮（份）：仓库储备 + 物品栏 */
export function rations_of(camp: Camp): number {
  let total = 0
  for (const [name, slot] of Object.entries(camp.仓库储备 ?? {})) {
    const per_unit = rations_per_unit(name)
    if (per_unit && slot.当前 > 0) {
      total += slot.当前 * per_unit
    }
  }
  for (const [name, item] of Object.entries(camp.物品栏 ?? {})) {
    const per_unit = rations_per_unit(name)
    if (per_unit && item.数量 > 0) {
      total += item.数量 * per_unit
    }
  }
  return total
}

/** 还能吃几天（人口 0 且有存粮时按 99 天算） */
export function food_days_of(camp: Camp): number {
  const rations = rations_of(camp)
  const population = camp.人口 ?? 0
  if (population > 0) return rations / population
  return rations > 0 ? 99 : 0
}

function buildingEnvironmentScore(buildings: Camp['当前建筑']): number {
  let score = 0
  for (const building of Object.values(buildings ?? {})) {
    const phase = building.建筑阶段 ?? '已建成'
    const state = building.状态 ?? ''
    if (phase === '受损' || /漏风|破损|漏雨|冰冷|熄灭/.test(state)) {
      score -= 6
      continue
    }
    if (phase === '建造中' || phase === '蓝图') {
      score -= 2
      continue
    }
    if (/稳定|完好|温|旺|加固/.test(state)) {
      score += 5
    } else if (phase === '已建成') {
      score += 2
    }
  }
  return score
}

/** 温饱基准：口粮储备 + 食物档位 + 住所 */
export function warmth_base(camp: Camp): number {
  const food_days = food_days_of(camp)
  let score = foodDaysScore(food_days) * 0.62
  score += FOOD_RESERVE_BONUS[camp.营地状态.食物储备] ?? 0
  score += (SHELTER_LEVEL_SCORE[camp.营地状态.住所等级] ?? 0) * 0.28
  return clamp_metric(score)
}

/** 栖居基准：住所、建筑完好、篝火/燃料、防御与仓储环境 */
export function shelter_base(camp: Camp): number {
  let score = (SHELTER_LEVEL_SCORE[camp.营地状态.住所等级] ?? 0) * 0.55
  score += buildingEnvironmentScore(camp.当前建筑)

  const daily_burn = dailyFuelBurn(camp.当前建筑 as never)
  const fuel_current = camp.篝火燃料.当前
  const firepit_key = resolveFirepitKey(camp.当前建筑)
  const firepit = firepit_key ? camp.当前建筑[firepit_key] : undefined
  const fire_lit = isFireLit(fuel_current, firepit?.状态)

  if (!fire_lit || fuel_current <= 0) {
    score -= 22
  } else {
    const hours = fuelHoursRemaining(fuel_current, daily_burn)
    if (hours < 4) score -= 10
    else if (hours < 12) score += 4
    else score += 12
  }

  // 防御工事已删除，改用派生总防御（只计一次，权重 1.1 为原两条 0.5+0.6 之和）
  score += (camp.防御?.总防御 ?? 0) * 1.1
  // 仓库等级已删除，改用已建成的储存类建筑数量
  score += Object.entries(camp.当前建筑 ?? {}).filter(([n, b]) =>
    is_storage_building(n, b as { 功能标签?: string[]; 建筑阶段?: string }),
  ).length * 2.5

  return clamp_metric(score)
}

/** 向心力基准：温饱/栖居 + 防御与储备稳定性 */
export function cohesion_base(camp: Camp): number {
  const warmth = warmth_base(camp)
  const shelter = shelter_base(camp)
  const reserve_bonus = FOOD_RESERVE_BONUS[camp.营地状态.食物储备] ?? 0

  let score = warmth * 0.38 + shelter * 0.38
  score += reserve_bonus * 0.35
  score += (camp.防御?.总防御 ?? 0) * 0.7

  if (warmth < 20) score -= 8
  if (shelter < 15) score -= 8
  if (warmth >= 60 && shelter >= 50) score += 6

  return clamp_metric(score)
}

/** 三个基准一次算完（顺序固定：温饱 → 栖居 → 向心，向心吃前两者） */
export function metric_bases(camp: Camp): { 温饱: number; 栖居: number; 向心: number } {
  return { 温饱: warmth_base(camp), 栖居: shelter_base(camp), 向心: cohesion_base(camp) }
}
