/**
 * NPC 生理随时间推进（原本缺失：饱食度/体力只在模型写面板时才变，与时间轴无关）
 *
 * 规则：
 *   饱食度  每 24h −40（约 2.5 天从满到空）
 *   体力    饱食度 ≥ 30 时每 24h +10（上限 100）；饱食度 < 30 时每 24h −20（下限 0）
 *   心情    饱食度归零时强制「低落」，恢复进食后由模型改回
 *
 * 只作用于【具名NPC】，未收入/幼崽不在此列。
 */
import _ from 'lodash'
import type { Schema } from '../schema'

/** 解析 HH:mm → 分钟 */
function parse_clock(hhmm: string): number {
  const m = String(hhmm ?? '').match(/^(\d{1,2}):(\d{2})$/)
  if (!m) return 0
  return Number(m[1]) * 60 + Number(m[2])
}

/**
 * 按世界时钟差值结算 NPC 生理（每次生成后都会跑，不依赖 advance() 被调用）。
 *
 * 用 世界.生理结算 做水位：首次只对齐不扣；之后按 (天数差 × 24h + 时分差) 结算。
 * 时间倒退（重 roll / 删层）时只对齐水位，不倒扣。
 */
export function settle_npc_vitals_by_clock(stat: Schema): boolean {
  const cur = { 生存天数: Number(stat.世界.生存天数 ?? 1), 时间: String(stat.世界.时间 ?? '00:00') }
  const mark = (stat.世界 as unknown as { 生理结算?: { 生存天数?: number; 时间?: string } }).生理结算
  const setMark = () => {
    ;(stat.世界 as unknown as Record<string, unknown>).生理结算 = {
      生存天数: cur.生存天数,
      时间: cur.时间,
    }
  }
  if (!mark || !Number.isFinite(Number(mark.生存天数))) {
    setMark()
    return false
  }
  const hours =
    (cur.生存天数 - Number(mark.生存天数)) * 24 + (parse_clock(cur.时间) - parse_clock(String(mark.时间 ?? '00:00'))) / 60
  if (hours <= 0) {
    // 时间倒退（重 roll / 删层 / 编辑）：**不推进水位**，也不倒扣。
    // 若这里把水位对齐到更早的时间，时间再走回原值时会重复扣一次（审查 P1-13）。
    return false
  }
  const changed = decay_npc_vitals(stat, hours)
  setMark()
  return changed || true
}

export function decay_npc_vitals(stat: Schema, hours: number): boolean {
  if (!Number.isFinite(hours) || hours <= 0) return false
  const npcs = (stat.具名NPC ?? {}) as Record<string, Record<string, unknown>>
  if (!npcs || Object.keys(npcs).length === 0) return false

  let changed = false
  const dayFraction = hours / 24
  const 供应档 = String(
    (stat.营地 as unknown as { 营地状态?: { 食物储备?: string } } | undefined)?.营地状态?.食物储备 ?? '极度匮乏',
  )

  for (const npc of Object.values(npcs)) {
    if (!npc) continue

    const satiety = Number(npc.饱食度 ?? 0)
    // 按「食物储备」档位决定吃饱还是挨饿（与仓库每日扣粮联动，见审查后的新问题）
    const supplyDelta =
      供应档 === '储备充足' ? 35 : 供应档 === '勉强果腹' ? 10 : -40
    const nextSatiety = _.clamp(satiety + dayFraction * supplyDelta, 0, 100)
    if (Math.abs(nextSatiety - satiety) > 1e-6) {
      npc.饱食度 = Math.round(nextSatiety)
      changed = true
    }

    const stamina = Number(npc.体力 ?? 0)
    const delta = nextSatiety >= 30 ? dayFraction * 10 : -dayFraction * 20
    const nextStamina = _.clamp(stamina + delta, 0, 100)
    if (Math.abs(nextStamina - stamina) > 1e-6) {
      npc.体力 = Math.round(nextStamina)
      changed = true
    }

    // 心情随饱食度分档（模型不写时也能反映生理状态）
    const mood = String(npc.心情 ?? '')
    const FEELINGS = ['低落', '饥饿', '温饱', '满足']
    const wanted =
      nextSatiety <= 5 ? '饥饿' : nextSatiety < 30 ? '饥饿' : nextSatiety < 70 ? '温饱' : '满足'
    if (!FEELINGS.includes(mood) || (mood !== wanted && (mood === '低落' || mood === '饥饿' || mood === '温饱' || mood === '满足'))) {
      npc.心情 = wanted
      changed = true
    }
  }

  return changed
}
