import type { Schema } from '../../../schema';
import { complete_building_by_delivery } from '../../../balance/buildingSettle';

export type TribeLogType = Schema['部族日志'][string]['类型'];

export type TribeLogEntryInput = {
  类型: TribeLogType;
  说明: string;
  归档摘要: string;
  关联键: string;
  具名参与?: string[];
  创建日期?: string;
  完成日期?: string;
  完成时日?: string;
};


/** 归一化关联键：'交付清点·X' / 'X·待交付' → 'X'，用于日志去重 */
export function normalize_log_key(key: string): string {
  return String(key ?? '')
    .replace(/^交付清点·/, '')
    .replace(/·待交付$/, '')
    .replace(/^\d{4}年\d{1,2}月\d{1,2}日_/, '')
    .trim()
}

function make_log_key(完成日期: string, 关联键: string, 类型: string): string {
  const safe = 关联键.replace(/[/.]/g, '_').slice(0, 48);
  return `${完成日期}_${类型}_${safe}`;
}

/** 写入部族日志（已完成事务/工作/探索的结构记录，供 AI 参考） */
export function archive_tribe_log(data: Schema, entry: TribeLogEntryInput): void {
  // 同一事件的多条日志（待交付 / 交付清点 / 综合归档）合并成一条
  const normalized = normalize_log_key(entry.关联键)
  if (normalized) {
    for (const [key, log] of Object.entries(data.部族日志 ?? {})) {
      if (!log) continue
      if (normalize_log_key(log.关联键 || key) === normalized) {
        log.说明 = entry.说明 || log.说明
        log.归档摘要 = entry.归档摘要 || log.归档摘要
        log.完成日期 = entry.完成日期 ?? log.完成日期
        log.完成时日 = entry.完成时日 ?? log.完成时日
        if (entry.具名参与?.length) log.具名参与 = entry.具名参与
        return
      }
    }
  }

  const 完成日期 = entry.完成日期 ?? data.世界.兽历;
  const 完成时日 = entry.完成时日 ?? data.世界.时间;
  const base_key = make_log_key(完成日期, entry.关联键, entry.类型);
  let final_key = base_key;
  let suffix = 1;
  while (data.部族日志[final_key] && data.部族日志[final_key].关联键 !== entry.关联键) {
    final_key = `${base_key}_${suffix++}`;
  }
  data.部族日志[final_key] = {
    类型: entry.类型,
    说明: entry.说明,
    归档摘要: entry.归档摘要,
    完成日期,
    完成时日,
    创建日期: entry.创建日期 ?? '',
    具名参与: entry.具名参与 ?? [],
    关联键: entry.关联键,
  };
}

export function backfill_affair_creation_dates(data: Schema): boolean {
  let changed = false;
  const cal = data.世界.兽历;
  for (const affair of _.values(data.部族事务)) {
    if (!affair.创建日期) {
      affair.创建日期 = cal;
      changed = true;
    }
  }
  for (const item of _.values(data.综合事物)) {
    if (!item.创建日期) {
      item.创建日期 = cal;
      changed = true;
    }
  }
  return changed;
}

/** 综合事物标记「已完成」后移入部族日志并删除（待剧情结算项除外，须 AI 结算后再归档） */
export function archive_completed_comprehensive_affairs(data: Schema): boolean {
  let changed = false;
  for (const name of Object.keys(data.综合事物)) {
    const item = data.综合事物[name];
    if (!item || item.状态 !== '已完成') {
      continue;
    }
    if (item.元数据?.类型 === '探索结算' || item.元数据?.类型 === '生产交付') {
      continue;
    }
    archive_tribe_log(data, {
      类型: '综合事物',
      关联键: name,
      说明: item.说明,
      归档摘要: item.说明 || `综合事物「${name}」已完成`,
      创建日期: item.创建日期,
      具名参与: item.具名参与,
    });
    complete_building_by_delivery(data as never, name);
    delete data.综合事物[name];
    changed = true;
    console.info('[综合事物] 已归档至部族日志:', name);
  }
  return changed;
}

/** 是否为「归来清点 / 交付清点」类待剧情结算事项（与状态无关） */
export function is_story_settlement_affair(
  name: string,
  item: Schema['综合事物'][string],
): boolean {
  if (name.startsWith('归来清点') || name.startsWith('交付清点')) {
    return true;
  }
  if (item.来源 === '时间结算') {
    return true;
  }
  const meta_type = item.元数据?.类型;
  return meta_type === '探索结算' || meta_type === '生产交付';
}

/** 待剧情结算的综合事物（归来清点等，尚未完成） */
export function is_pending_story_settlement(name: string, item: Schema['综合事物'][string]): boolean {
  if (item.状态 === '已完成') {
    return false;
  }
  return is_story_settlement_affair(name, item);
}

/** 归档已结算的待剧情事项（AI 将状态标为已完成时调用） */
export function archive_settled_pending_affairs(data: Schema): boolean {
  let changed = false;
  for (const name of Object.keys(data.综合事物)) {
    const item = data.综合事物[name];
    if (!item || item.状态 !== '已完成') {
      continue;
    }
    if (!is_story_settlement_affair(name, item)) {
      continue;
    }
    const log_type = item.元数据?.类型 === '探索结算' ? '探索' : '工作';
    archive_tribe_log(data, {
      类型: log_type,
      关联键: name,
      说明: item.说明,
      归档摘要: item.说明,
      创建日期: item.创建日期,
      具名参与: item.具名参与,
    });
    complete_building_by_delivery(data as never, name);
    delete data.综合事物[name];
    changed = true;
    console.info('[待剧情结算] 已归档:', name);
  }
  return changed;
}
