import {
  LEGACY_NPC_GRADE_MAP,
  NPC_SKILL_TIERS,
  tier_from_skill_value,
  type NpcSkillTier,
} from '../../../constants/gradeSystem';

export const NPC_GRADES = NPC_SKILL_TIERS;
export type NpcGrade = NpcSkillTier;

export type NpcSkillsLike = {
  狩猎?: number;
  战斗?: number;
  采集?: number;
  后勤?: number;
};

const GRADE_SET = new Set<string>(NPC_GRADES);

export function max_skill_value(skills: NpcSkillsLike | undefined | null): number {
  if (!skills) {
    return 0;
  }
  return Math.max(skills.狩猎 ?? 0, skills.战斗 ?? 0, skills.采集 ?? 0, skills.后勤 ?? 0);
}

/** 主专精项（用于姓名旁「后勤·大师」展示） */
export function primary_skill_entry(
  skills: NpcSkillsLike | undefined | null,
): { key: keyof NpcSkillsLike; value: number } | null {
  if (!skills) return null;
  const entries = (['狩猎', '战斗', '采集', '后勤'] as const)
    .map(key => ({ key, value: skills[key] ?? 0 }))
    .sort((a, b) => b.value - a.value);
  if (entries[0].value <= 0) return null;
  return entries[0];
}

export function format_npc_grade_label(
  grade: NpcGrade,
  skills?: NpcSkillsLike | null,
): string {
  const primary = primary_skill_entry(skills);
  if (primary && primary.value >= 21) {
    return `${primary.key}·${grade}`;
  }
  return grade;
}

/** 四项技能最高值 → 六档（与 skill_tier 阈值一致） */
export function infer_npc_grade_from_skills(skills: NpcSkillsLike | undefined | null): NpcGrade {
  return tier_from_skill_value(max_skill_value(skills));
}

export function normalize_npc_grade(value: string | undefined): NpcGrade {
  if (value && GRADE_SET.has(value)) {
    return value as NpcGrade;
  }
  if (value && LEGACY_NPC_GRADE_MAP[value]) {
    return LEGACY_NPC_GRADE_MAP[value];
  }
  return '生疏';
}

export function resolve_npc_grade(
  stored: string | undefined,
  skills: NpcSkillsLike | undefined | null,
): NpcGrade {
  if (skills && max_skill_value(skills) > 0) {
    return infer_npc_grade_from_skills(skills);
  }
  return normalize_npc_grade(stored);
}

export function parse_skills_from_panel_text(text: string): NpcSkillsLike {
  const skills: NpcSkillsLike = {};
  const re = /(狩猎|战斗|采集|后勤):(\d+)/g;
  let match: RegExpExecArray | null;
  while ((match = re.exec(text)) !== null) {
    const key = match[1] as keyof NpcSkillsLike;
    skills[key] = Number(match[2]);
  }
  return skills;
}

export function npc_grade_class(grade: string | undefined): string {
  const normalized = normalize_npc_grade(grade);
  return {
    生疏: 'grade-novice',
    入门: 'grade-entry',
    熟练: 'grade-skilled',
    精通: 'grade-expert',
    大师: 'grade-master',
    传说: 'grade-legend',
  }[normalized];
}
