import { is_function_group, resolve_group_candidates, FALLBACK_FACTOR } from './requirementCatalog'
/**
 * 经济系统核心（v1）—— 设计见 _audit/设计_经济与建造_v1.md
 *
 * 两条封闭集合 + 一个等价量货币 + 一个扣料入口：
 *   品类：食物/材料/工具/燃料/药品/杂物（永不枚举具体物品）
 *   品级：劣质0.6 / 普通1.0 / 优良1.5 / 精品2.5
 *   等价量 = 1 单位 × 品级系数，扣料以等价量计
 *
 * 建筑（规划/升级）与工作队列（建造/生产）共用同一份 MaterialDemand 与 consume_materials。
 */

export const CATEGORIES = ['食物', '材料', '工具', '燃料', '药品', '杂物'] as const
export type Category = (typeof CATEGORIES)[number]

// 与世界书《品级与分级系统》材料五档对齐（P1-5）
export const GRADES = ['常见', '普通', '少有', '罕见', '稀世'] as const
export type Grade = (typeof GRADES)[number]

export const GRADE_FACTOR: Record<Grade, number> = {
  常见: 0.6,
  普通: 1,
  少有: 1.5,
  罕见: 2.5,
  稀世: 4,
}

/** 类别别名：世界书写「医疗」，代码用「药品」 */
const CATEGORY_ALIAS: Record<string, Category> = { 医疗: '药品', 珍异储备: '杂物', 工具与装备: '工具' }

/** 旧四档 → 新五档（兼容历史数据与旧调用处） */
const GRADE_ALIAS: Record<string, Grade> = {
  劣质: '常见',
  优良: '少有',
  精品: '罕见',
  粗糙: '常见',
  精良: '少有',
  稀有: '少有', // 世界书里「稀有材料」指材料五档的少见档；制作品级的「稀有」不走这里
  传说: '稀世',
  史诗: '稀世',
  神迹: '稀世',
}

/** 单格仓储上限基数（× 品级系数） */
export const SLOT_CAP_BASE = 200

/** 后缀兜底规则：兜不住就进「杂物」并标未分类 */
const SUFFIX_RULES: Array<{ re: RegExp; category: Category }> = [
  { re: /面|饭|粥|汤|菜|肉|蛋|奶|果|糕|糖|酒|茶|汁|肠|爪|翅|脯|干|酱|块茎|口粮|罐头|饼干|棒/i, category: '食物' },
  { re: /柴|木|石|藤|骨|皮|矿|枝|草|绳|铁|铜|布/i, category: '材料' },
  { re: /刀|斧|针|枪|锤|镐|碗|锅|绳结|工具/i, category: '工具' },
  { re: /油|炭|煤|燃料/i, category: '燃料' },
  { re: /药|绷带|解毒|膏/i, category: '药品' },
]

export function is_category(v: unknown): v is Category {
  return typeof v === 'string' && (CATEGORIES as readonly string[]).includes(v)
}

export function is_grade(v: unknown): v is Grade {
  return typeof v === 'string' && (GRADES as readonly string[]).includes(v)
}

/**
 * 判定物资类别：声明优先 → 后缀规则 → 杂物（标记未分类）
 */
export function classify_item(name: string, declared?: unknown): {
  category: Category;
  unclassified: boolean;
} {
  // 类别别名归一（世界书里写「医疗」，代码用「药品」）
  const normalized =
    typeof declared === 'string' ? (CATEGORY_ALIAS[declared.trim()] ?? declared) : declared
  if (is_category(normalized)) return { category: normalized, unclassified: false }
  const text = String(name ?? '')
  for (const rule of SUFFIX_RULES) {
    if (rule.re.test(text)) return { category: rule.category, unclassified: false }
  }
  return { category: '杂物', unclassified: true }
}

/** 品级归一：非法值回落「普通」 */
export function normalize_grade(raw: unknown, defaultGrade: Grade = '普通'): Grade {
  if (is_grade(raw)) return raw
  const alias = GRADE_ALIAS[String(raw ?? '').trim()]
  return alias ?? defaultGrade
}

/** 等价量 = 单位数 × 品级系数 */
export function equivalence(amount: number, grade: Grade | string): number {
  const n = Number(amount)
  if (!Number.isFinite(n) || n <= 0) return 0
  const g = normalize_grade(grade)
  return n * GRADE_FACTOR[g]
}

export function slot_cap(grade: Grade | string): number {
  const g = normalize_grade(grade)
  return Math.round(SLOT_CAP_BASE * GRADE_FACTOR[g])
}

// ---------------- 材料需求与扣料 ----------------

export type MaterialDemand = Record<
  string,
  {
    需求: number
    可替代?: string[]
  }
>

export type ConsumeResult = {
  成功: boolean
  已扣: Record<string, { 数量: number; 等价量: number }>
  缺口: Record<string, number>
  /** 超出需求的等价量（玩家选了就用完，多出的作废，不返还） */
  浪费: number
}

type Slot = {
  锁定?: boolean
  当前?: number
  上限?: number
  类别?: string
  品级?: string
  未分类?: boolean
}

/** 品级优先级：先扣差的，好的留着 */
const SPEND_ORDER: Grade[] = ['常见', '普通', '少有', '罕见', '稀世']

/** 某仓库键的品级（缺省普通） */
function grade_of(slot: Slot | undefined): Grade {
  return normalize_grade(slot?.品级)
}

/**
 * 扣料（立即扣、整笔成功或整笔失败）。
 *
 * 规则：
 *  1. 同键优先，其次 可替代 列表
 *  2. 同键内优先消耗低品级
 *  3. 按等价量累计，凑够需求即停
 *  4. 任一品类凑不齐 → 不扣任何东西，返回缺口
 *  5. 成功则写回仓库，并返回实际扣了什么（供 已投入 留痕）
 */
export function consume_materials(
  warehouse: Record<string, Slot>,
  demand: MaterialDemand,
  options: { allowSurplus?: boolean } = {},
): ConsumeResult {
  const plan: Record<string, { 数量: number; 等价量: number }> = {}
  const shortfall: Record<string, number> = {}
  const working: Record<string, number> = {}

  const amount_of = (key: string) => (working[key] ??= Number(warehouse[key]?.当前 ?? 0) || 0)

  for (const [needKey, spec] of Object.entries(demand)) {
    const need = Number(spec?.需求 ?? 0)
    if (!Number.isFinite(need) || need <= 0) continue

    const candidates = is_function_group(needKey)
      ? [...resolve_group_candidates(needKey, warehouse), ...(spec.可替代 ?? [])]
      : [needKey, ...(spec.可替代 ?? [])]
    let gathered = 0

    // 低品级优先：把所有候选按品级排序后逐个取
    const flat: Array<{ key: string; grade: Grade }> = []
    for (const key of candidates) {
      flat.push({ key, grade: grade_of(warehouse[key]) })
    }
    flat.sort((a, b) => SPEND_ORDER.indexOf(a.grade) - SPEND_ORDER.indexOf(b.grade))

    for (const { key, grade } of flat) {
      if (gathered >= need) break
      if (warehouse[key]?.锁定) continue // 玩家锁定的物资永不消耗
      const available = amount_of(key)
      if (available <= 0) continue
      // 未分类/杂物作为最后手段：系数再乘 0.6
      const factor = GRADE_FACTOR[grade] * ((warehouse[key]?.类别 ?? '杂物') === '杂物' && is_function_group(needKey) ? FALLBACK_FACTOR : 1)
      const needUnits = Math.ceil((need - gathered) / factor)
      const takeUnits = Math.min(available, needUnits)
      if (takeUnits <= 0) continue
      working[key] = available - takeUnits
      const eq = equivalence(takeUnits, grade)
      plan[key] = { 数量: (plan[key]?.数量 ?? 0) + takeUnits, 等价量: (plan[key]?.等价量 ?? 0) + eq }
      gathered += eq
    }

    if (gathered + 1e-6 < need) {
      shortfall[needKey] = Math.round((need - gathered) * 10) / 10
    }
  }

  if (Object.keys(shortfall).length > 0) {
    return { 成功: false, 已扣: {}, 缺口: shortfall, 浪费: 0 }
  }

  // 整笔成功 → 写回仓库
  for (const [key, taken] of Object.entries(plan)) {
    const slot = warehouse[key]
    if (!slot) continue
    slot.当前 = Math.max(0, (Number(slot.当前 ?? 0) || 0) - taken.数量)
  }

  // 多出来的等价量：玩家选了就用完，多余部分作废（不返还）
  let surplus = 0
  if (options.allowSurplus) {
    for (const [needKey, spec] of Object.entries(demand)) {
      const need = Number(spec?.需求 ?? 0)
      const got = Object.entries(plan)
        .filter(([key]) => key === needKey || (spec.可替代 ?? []).includes(key))
        .reduce((sum, [, v]) => sum + v.等价量, 0)
      if (got > need) surplus += got - need
    }
  }

  return { 成功: true, 已扣: plan, 缺口: {}, 浪费: Math.round(surplus * 10) / 10 }
}
