import type { Schema } from '../../../schema';

type NamedNpc = Schema['具名NPC'][string];

/** 与营地/窝棚等安全区相关的位置关键词 */
export const CAMP_LOCATION_RE = /营地|长屋|火塘|聚落|残骸|营帐|窝棚|防风|营地内部|湖畔营地|乱石滩营地|主角身旁|主角身边|主角侧|火塘边|火塘旁|火堆边/;

/** 归来清点等结算阶段任务 */
const RETURN_SETTLEMENT_TASK_RE = /归来清点|献宝|上交|待清点/;

/** 营地守夜/警戒类任务（不属于外出编队） */
export const GUARD_DUTY_TASK_RE =
  /营地巡逻|守营|留守|看守|守夜|警戒|守卫|岗哨|上半夜|下半夜|夜间警戒|夜间守卫|放哨|值守/;

export function is_npc_guard_duty_task(task: string): boolean {
  return GUARD_DUTY_TASK_RE.test(task.trim());
}

/** NPC 当前位置是否在营地（或等效安全区） */
export function is_npc_at_camp(npc: NamedNpc | undefined): boolean {
  if (!npc) return false;
  const loc = (npc.当前位置 ?? '').trim();
  if (!loc) return false;
  return CAMP_LOCATION_RE.test(loc);
}

/** 是否处于归来清点等待结算阶段 */
export function is_npc_on_return_settlement(npc: NamedNpc | undefined): boolean {
  if (!npc) return false;
  return RETURN_SETTLEMENT_TASK_RE.test(npc.当前任务 ?? '');
}

/**
 * 是否仍在野外执行任务（普适判定：位置优先，其次「外出」状态，不依赖任务文案霜华名单）。
 */
export function is_npc_physically_outbound(npc: NamedNpc | undefined): boolean {
  if (!npc) return false;
  if (npc.状态 === '外出') return true;
  const loc = (npc.当前位置 ?? '').trim();
  if (!loc) return false;
  return !CAMP_LOCATION_RE.test(loc);
}

/** 是否应视为尚未归营（在野外且非归来清点阶段） */
export function npc_indicates_still_outbound(npc: NamedNpc | undefined): boolean {
  if (!npc) return false;
  if (is_npc_on_return_settlement(npc) && is_npc_at_camp(npc)) return false;
  if (npc_task_indicates_active_squad_mission(npc)) return true;
  return is_npc_physically_outbound(npc);
}

/** 当前任务是否表明正在带队外出（位置仍写营地时也视为外出） */
export function npc_task_indicates_active_squad_mission(npc: NamedNpc | undefined): boolean {
  if (!npc) return false;
  const task = (npc.当前任务 ?? '').trim();
  if (!task) return false;
  return /带领.*(狩猎|采集|探索)|外出(狩猎|采集|探索)|带队(狩猎|采集|周边)|狩猎中|采集中|探索中/.test(task);
}

/** 是否已回到营地、可结束外出状态 */
export function npc_indicates_returned_to_camp(npc: NamedNpc | undefined): boolean {
  if (!npc) return false;
  if (npc_indicates_still_outbound(npc)) return false;
  if (is_npc_at_camp(npc)) return true;
  if (is_npc_on_return_settlement(npc)) return is_npc_at_camp(npc);
  return false;
}
