/**
 * 坠星大陆 · 仓储结算（A6 腐坏 / A7 溢出→临时仓）
 *
 * 唯一实现，只认 Δt（§8.10）。两个调用方：
 *   1. `balance/timeAdvance.ts` 的 `advance()` —— 结算器 / 100 天模拟器路径；
 *   2. `界面/状态栏/util/settlementSync.ts` 的入库/回放路径（仓储由聊天记录重建，
 *      时间驱动的损耗必须落在重建里，否则每轮都被重建抹掉）。
 *
 * 规矩：腐坏率、消散率、单格上限全部从 `table.ts` 读，这里不许写死任何数字。
 */
import type { Schema } from '../schema'
import { CONSUME, DECAY, OVERFLOW, capOf } from './table'

type Stock = Schema['营地']['仓库储备']
type TempStore = Schema['营地']['临时仓']

/**
 * 容量加成系数：由「已建成的储存类建筑」提供，默认 1（基础容量）。
 * 没有新建储存建筑时仓库维持基础容量——「升级仓库」按钮已删除。
 */
/**
   * 容量加成系数（模块级可变）。
   * 审计 F1-09 指出这会破坏可重放性 —— 已知并接受：
   * 管线每次同步前都会 set_storage_bonus 重设，且全部结算都在同一线程内顺序执行；
   * 若将来出现并发/多档并行，应改为显式传参。
   */
let __storage_bonus = 1
export function set_storage_bonus(v: number): void {
  __storage_bonus = Number.isFinite(v) && v > 0 ? v : 1
}
export function storage_bonus(): number {
  return __storage_bonus
}

/**
 * 单格实际可用上限：槽位自带的「上限」只能更小，不能突破品级天花板（A2）。
 * 槽位没有合法上限（旧档 / AI 写坏）时退回品级值。
 * 再乘上「储存类建筑」提供的容量系数。
 */
export function slot_cap(name: string, slot?: { 上限?: number; 品级?: string }): number {
  const grade_cap = Math.max(1, Math.round(capOf(name, (slot?.品级 ?? '常见') as never) * __storage_bonus))
  const own = Number(slot?.上限)
  if (!Number.isFinite(own) || own <= 0) {
    return grade_cap
  }
  return Math.min(own, grade_cap)
}

/** 每日腐坏比例（A6）；未登记但可当口粮的按默认值，其余不腐坏 */
export function decay_rate_of(name: string): number {
  if (name in DECAY.DAILY_RATE) {
    return DECAY.DAILY_RATE[name]
  }
  return name in CONSUME.UNIT_TO_RATION ? DECAY.DEFAULT_FOOD : 0
}

/** 该物资的单位→配额折算（不在表里 = 不能吃） */
export function ration_factor_of(name: string): number {
  return name in CONSUME.UNIT_TO_RATION ? CONSUME.UNIT_TO_RATION[name] : 0
}

export type RationResult = { eaten: number; missing: number }

/**
 * 口粮消耗（世界书《营地消耗与生存结算规则》：有易坏先吃易坏）。
 * 排序规则：腐坏率高者优先，同率按名称固定序 —— 纯函数，可重放（D9）。
 * `rations` 允许小数（欠账口径由调用方决定），返回没吃到的缺口。
 */
export function consume_rations(stock: Stock, rations: number): RationResult {
  if (!(rations > 0)) {
    return { eaten: 0, missing: 0 }
  }
  const order = Object.keys(stock)
    .filter(name => ration_factor_of(name) > 0 && stock[name].当前 > 0)
    .sort((a, b) => {
      const rateDiff = decay_rate_of(b) - decay_rate_of(a)
      return rateDiff !== 0 ? rateDiff : a.localeCompare(b)
    })

  let remaining = rations
  let eaten = 0
  for (const name of order) {
    if (remaining <= 1e-9) {
      break
    }
    const factor = ration_factor_of(name)
    const slot = stock[name]
    const takeUnits = Math.min(slot.当前, remaining * factor)
    if (!(takeUnits > 0)) {
      continue
    }
    slot.当前 -= takeUnits
    remaining -= takeUnits / factor
    eaten += takeUnits / factor
  }
  return { eaten, missing: Math.max(0, remaining) }
}

const r1 = (v: number) => Math.round(v * 10) / 10
/**
 * 按日百分比复利衰减 —— 而不是线性扣减。
 * 复利是「每日 8%」的本义，而且 (1-r)^(a/24) × (1-r)^(b/24) === (1-r)^((a+b)/24)，
 * 所以把同一段 Δt 拆成几楼分别结算，结果完全一致（D9 可重放的前提）。
 */
const keep_shrinking = (v: number, rate: number, hours: number) =>
  v * Math.pow(Math.max(0, 1 - Math.min(1, rate)), hours / 24)

/**
 * A6：按 Δt 结算仓库腐坏，原地修改，返回损失单位数。
 * `round` 为 true 时取整（界面直接显示整数）；回放里逐楼累加时传 false 以免小额被取整抹平。
 */
export function apply_decay(
  stock: Stock,
  hours: number,
  round = true,
  /** 腐坏系数：1=正常；有储存建筑时由调用方传更小的值（0=完全不腐坏） */
  decay_factor = 1,
): number {
  if (!(hours > 0)) {
    return 0
  }
  let lost = 0
  for (const name of Object.keys(stock)) {
    const slot = stock[name]
    const rate = decay_rate_of(name) * (decay_factor > 0 ? decay_factor : 0)
    if (!(rate > 0) || !(slot.当前 > 0)) {
      continue
    }
    const before = slot.当前
    const raw = keep_shrinking(before, rate, hours)
    const after = round ? Math.round(raw) : raw
    if (after === before) {
      continue
    }
    slot.当前 = after
    lost += before - after
  }
  return lost
}

/** A7：临时仓按日消散（默认 40%/天），返回消散单位数 */
export function vanish_temporary(temp: TempStore | undefined, hours: number, round = true): number {
  if (!temp || !(hours > 0)) {
    return 0
  }
  let lost = 0
  for (const name of Object.keys(temp)) {
    const entry = temp[name]
    if (!(entry.当前 > 0)) {
      delete temp[name]
      continue
    }
    const before = entry.当前
    const raw = keep_shrinking(before, OVERFLOW.DAILY_VANISH_RATE, hours)
    const after = round ? (raw < 0.1 ? 0 : r1(raw)) : raw
    if (after <= 0) {
      lost += before
      delete temp[name]
      continue
    }
    if (after !== before) {
      entry.当前 = after
      lost += before - after
    }
  }
  return lost
}

/** 消散说法：同输入同结果（D9 可重放），不用 Math.random */
export function vanish_reason_for(name: string): string {
  const list = OVERFLOW.VANISH_REASONS
  let hash = 0
  for (let i = 0; i < name.length; i += 1) {
    hash = (hash + name.charCodeAt(i)) % list.length
  }
  return list[hash]
}

/** 取（必要时创建）临时仓；stat 没有营地时返回 undefined（回放用的 scratch 也走这里） */
function ensure_temp(stat: Schema): TempStore | undefined {
  const camp = stat?.营地
  if (!camp) {
    return undefined
  }
  if (!camp.临时仓) {
    camp.临时仓 = {}
  }
  return camp.临时仓
}

/** A7 溢出落点：把 units 记进临时仓，返回实际记账数量（无临时仓表时返回 0） */
export function add_to_temporary(stat: Schema, name: string, units: number): number {
  if (!(units > 0)) {
    return 0
  }
  const temp = ensure_temp(stat)
  if (!temp) {
    return 0
  }
  const entry = temp[name] ?? { 当前: 0, 说明: '' }
  entry.当前 = r1(entry.当前 + units)
  if (!entry.说明) {
    entry.说明 = vanish_reason_for(name)
  }
  temp[name] = entry
  return units
}

/**
 * 统一入库：加库存 → 按单格上限钳制 → 超出部分转临时仓。
 *
 * 为什么需要它（技术债清理）：
 *   仓库写入点曾分散在 7 个文件，其中 dailySettle / workQueueProgress 直接
 *   `slot.当前 += count` 不钳上限；而 warehouse.ts 里设计好的 route_overflow
 *   全项目零调用 —— 等于「单格上限 + 溢出转临时仓」机制从未上线。
 *   现在确定性产出统一走这里：入账 + 溢出都返回，撤回可按返回值精确回滚。
 *
 * 注意：这是**单个物资**的入库；不要拿全局 route_overflow 当 per-slot 用
 * （它扫整张表，多点调用会误搬历史溢出、不幂等）。
 */
export function add_slot_with_overflow(
  stat: Schema,
  name: string,
  units: number,
): { 入账: number; 溢出: number } {
  if (!(units > 0)) {
    return { 入账: 0, 溢出: 0 }
  }
  const stock = stat?.营地?.仓库储备
  if (!stock) {
    return { 入账: 0, 溢出: 0 }
  }
  const slot = stock[name] ?? { 当前: 0 }
  const cap = slot_cap(name, slot)
  const before = Number(slot.当前 ?? 0)
  const room = Math.max(0, cap - before)
  const 入账 = Math.min(units, room)
  slot.当前 = r1(before + 入账)
  stock[name] = slot
  const 溢出 = r1(units - 入账)
  if (溢出 > 0) {
    add_to_temporary(stat, name, 溢出)
  }
  return { 入账: r1(入账), 溢出 }
}

/** A7：全仓扫描，超单格上限的部分转入临时仓（不再静默丢弃），返回转入总数 */
export function route_overflow(stat: Schema): number {
  const stock = stat?.营地?.仓库储备
  if (!stock) {
    return 0
  }
  let moved = 0
  for (const name of Object.keys(stock)) {
    const slot = stock[name]
    const cap = slot_cap(name, slot)
    if (!(slot.当前 > cap)) {
      continue
    }
    const over = r1(slot.当前 - cap)
    slot.当前 = cap
    moved += add_to_temporary(stat, name, over)
  }
  return moved
}

/**
 * 建筑是否具备某功能标签。
 * 优先读 功能标签（时代二会细化），缺省时按名称关键词兜底 —— 旧档 / AI 漏标也能跑。
 */
const TAG_FALLBACK: Record<string, RegExp> = {
  储存: /储|窖|架|仓|库/,
  干燥: /烟熏|风干|晒|烘/,
  冷藏: /冰|冷藏|地窖/,
  制作: /工作屋|工作台|台|作坊/,
  居住: /屋|棚|帐篷|窝/,
  防御: /栏|墙|塔|栅栏|壁垒/,
}

export function building_has_tag(
  buildings: Record<string, { 功能标签?: string[] }> | undefined,
  tag: string,
): boolean {
  const list = buildings ?? {}
  for (const [name, b] of Object.entries(list)) {
    const tags = b?.功能标签
    const has = Array.isArray(tags) && tags.length > 0
      ? tags.includes(tag)
      : (TAG_FALLBACK[tag] ?? /(?:)/).test(name)
    if (has) return true
  }
  return false
}
