        const stat_data = _.get(getVariables(variable_option), 'stat_data', {});
        const parsed = schema.safeParse(stat_data, { reportInput: true });
        if (!parsed.success) {
            console.error('[MVU store] stat_data 校验失败，将尝试用 schema 默认值恢复', parsed.error);
        }
