type JsonPatchOp = { op?: string; path?: string; value?: unknown };

function decode_json_pointer_segment(segment: string): string {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

/** 从 assistant 正文提取 JSONPatch 数组 */
export function extractJsonPatchesFromMessage(text: string): JsonPatchOp[] {
  const block = text.match(
    /(?:<|&lt;)JSONPatch(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/JSONPatch(?:>|&gt;)/i,
  );
  if (!block?.[1]) {
    return [];
  }
  try {
    const parsed = JSON.parse(block[1].trim());
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

type SettlementKind = '探索' | '狩猎' | '采集' | '工作';

export type ParsedSettlementCard = {
  kind: SettlementKind;
  target: string;
  materials: Array<{ name: string; amount: number }>;
  /** settlement_card [参与|霜华, 林果] */
  participants?: string[];
  /** settlement_card [副标题|…] */
  subtitle?: string;
};

const WAREHOUSE_RESOURCE_ALIAS: Record<string, string> = {
  生藤蔓: '藤蔓',
  完整大兽皮: '完整小兽皮',
};

const SETTLEMENT_CARD_RE =
  /(?:<|&lt;)settlement_card(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/settlement_card(?:>|&gt;)/gi;

const SETTLEMENT_FIELD_RE =
  /\[(类型|品质|标题|副标题|参与|参与人员|说明|结算对象|获取物资|消耗状况|事件描述|消耗|产出|状态|情报带回|时间消耗|队伍状态|[^\]|]+)\|([^\]]*)\]/g;

const RESERVED_FIELDS = new Set([
  '类型',
  '品质',
  '标题',
  '副标题',
  '参与',
  '参与人员',
  '说明',
  '结算对象',
  '结算事项',
  '获取物资',
  '消耗状况',
  '事件描述',
  '消耗',
  '产出',
  '状态',
  '情报带回',
  '时间消耗',
  '队伍状态',
  '编队',
]);

const HUNT_RESOURCE_RE = /生肉|兽皮|兽脂|骨骼|皮革|猎物|内脏|狼/;
const GATHER_RESOURCE_RE = /块茎|野果|藤蔓|木柴|菌菇|浆果|植物|果|藤/;

function normalizeResourceName(name: string): string {
  return WAREHOUSE_RESOURCE_ALIAS[name.trim()] ?? name.trim();
}

function expandCompoundResourceName(name: string): string[] {
  if (name.includes('/')) {
    return name.split('/').map(part => normalizeResourceName(part)).filter(Boolean);
  }
  return [normalizeResourceName(name)];
}

function parseOutputStarMaterials(raw: string): Array<{ name: string; amount: number }> {
  const items: Array<{ name: string; amount: number }> = [];
  for (const part of raw.split(/[,，、]/)) {
    const trimmed = part.trim();
    if (!trimmed) continue;
    let m = trimmed.match(/^(.+?)[*×xX]\s*(\d+)\s*$/);
    if (!m) {
      m = trimmed.match(/^(.+?)[:：]\+?(\d+)\s*$/);
    }
    if (!m) continue;
    const amount = Number(m[2]);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const names = expandCompoundResourceName(m[1]);
    if (names.length > 1) {
      let rest = amount;
      const base = Math.floor(amount / names.length);
      names.forEach((name, index) => {
        const add = index === names.length - 1 ? rest : base;
        items.push({ name, amount: add });
        rest -= add;
      });
    } else {
      items.push({ name: names[0], amount });
    }
  }
  return items;
}

function parseMaterialList(raw: string): Array<{ name: string; amount: number }> {
  return parseOutputStarMaterials(raw.replace(/\//g, ','));
}

function parseMarkdownMaterials(raw: string): Array<{ name: string; amount: number }> {
  const items: Array<{ name: string; amount: number }> = [];
  for (const line of raw.split('\n')) {
    const m = line.trim().match(/^[-•*]?\s*\[([^\]]+)\]\s*[x×*]\s*(\d+)/i);
    if (!m) continue;
    const amount = Number(m[2]);
    if (!Number.isFinite(amount) || amount <= 0) continue;
    const names = expandCompoundResourceName(m[1]);
    if (names.length > 1) {
      let rest = amount;
      const base = Math.floor(amount / names.length);
      names.forEach((name, index) => {
        const add = index === names.length - 1 ? rest : base;
        items.push({ name, amount: add });
        rest -= add;
      });
    } else {
      items.push({ name: names[0], amount });
    }
  }
  return items;
}

function extractMultilineField(content: string, fieldName: string): string {
  const marker = `[${fieldName}|`;
  const start = content.indexOf(marker);
  if (start < 0) return '';
  const bodyStart = start + marker.length;
  const lineEnd = content.indexOf('\n]', bodyStart);
  if (lineEnd >= 0) {
    return content.slice(bodyStart, lineEnd).trim();
  }
  const inlineEnd = content.indexOf(']', bodyStart);
  if (inlineEnd >= 0) {
    return content.slice(bodyStart, inlineEnd).trim();
  }
  return content.slice(bodyStart).trim();
}

function inferKindFromSquadName(name: string): SettlementKind {
  if (/采集/.test(name)) return '采集';
  if (/狩猎/.test(name)) return '狩猎';
  if (/巡逻|探索/.test(name)) return '探索';
  if (/工作|交付|队列/.test(name)) return '工作';
  return '探索';
}

function inferKindFromTitle(title: string, content: string): SettlementKind {
  if (/^类型\|(探索|狩猎|采集|工作)/.test(content)) {
    const m = content.match(/\[类型\|(探索|狩猎|采集|工作)\]/);
    if (m) return m[1] as SettlementKind;
  }
  if (/采集/.test(title) && !/狩猎/.test(title)) return '采集';
  if (/狩猎/.test(title) && !/采集/.test(title)) return '狩猎';
  if (/工作|交付/.test(title)) return '工作';
  return '探索';
}

function parseSquadNamedSettlementLines(content: string): ParsedSettlementCard[] {
  const cards: ParsedSettlementCard[] = [];
  const lineRe = /\[(采集队|狩猎队|巡逻队|探索队)(?:_[^|\]]+|\/[^|\]]+)?\|(.+?)(?:\|([^\]]+))?\]/g;
  let m: RegExpExecArray | null;
  while ((m = lineRe.exec(content)) !== null) {
    const squadKey = m[0].slice(1, m[0].indexOf('|'));
    const materials = parseOutputStarMaterials(m[2]);
    if (materials.length === 0) continue;
    cards.push({
      kind: inferKindFromSquadName(squadKey),
      target: squadKey,
      materials,
    });
  }
  return cards;
}

function parseMultiSquadBlocks(content: string): ParsedSettlementCard[] {
  return content
    .split(/(?=\[编队\|)/)
    .map(chunk => {
      if (!/\[编队\|/.test(chunk)) return null;
      const squad = chunk.match(/\[编队\|([^\]]+)\]/)?.[1]?.trim();
      if (!squad) return null;
      const output = chunk.match(/\[产出\|([^\]]+)\]/)?.[1] ?? '';
      return {
        kind: inferKindFromSquadName(squad),
        target: squad,
        materials: parseOutputStarMaterials(output),
      };
    })
    .filter((card): card is ParsedSettlementCard => card !== null && card.materials.length > 0);
}

function parseCombinedMaterialBlock(content: string): ParsedSettlementCard[] {
  const matBlock = extractMultilineField(content, '物资获取');
  if (!matBlock) return [];
  const titleMatch = content.match(/^\[([^\]|]+)\|([^\]]+)\]/);
  const title = titleMatch?.[2]?.trim() ?? '归来清点';
  const materials = parseMarkdownMaterials(matBlock);
  if (materials.length === 0) return [];

  if (/狩猎/.test(title) && /采集/.test(title)) {
    const hunt = materials.filter(m => HUNT_RESOURCE_RE.test(m.name));
    const gather = materials.filter(m => GATHER_RESOURCE_RE.test(m.name));
    const other = materials.filter(m => !HUNT_RESOURCE_RE.test(m.name) && !GATHER_RESOURCE_RE.test(m.name));
    const cards: ParsedSettlementCard[] = [];
    if (hunt.length) {
      cards.push({ kind: '狩猎', target: `${title}·狩猎`, materials: hunt });
    }
    if (gather.length || other.length) {
      cards.push({ kind: '采集', target: `${title}·采集`, materials: [...gather, ...other] });
    }
    return cards.length ? cards : [{ kind: inferKindFromTitle(title, content), target: title, materials }];
  }

  return [{ kind: inferKindFromTitle(title, content), target: title, materials }];
}

function parseParticipantNames(raw?: string): string[] {
  if (!raw?.trim()) {
    return [];
  }
  return raw
    .split(/[,，、]/)
    .map(s => s.trim())
    .filter(Boolean);
}

function settlementCardMeta(fields: Record<string, string>): {
  participants: string[];
  subtitle: string;
} {
  return {
    participants: parseParticipantNames(fields['参与'] ?? fields['参与人员'] ?? ''),
    subtitle: fields['副标题'] ?? fields['标题'] ?? '',
  };
}

export function parseSettlementCardContent(content: string): ParsedSettlementCard {
  const fields: Record<string, string> = {};
  const rewardLines: Array<{ name: string; amount: number }> = [];

  let m: RegExpExecArray | null;
  SETTLEMENT_FIELD_RE.lastIndex = 0;
  while ((m = SETTLEMENT_FIELD_RE.exec(content)) !== null) {
    const key = m[1].trim();
    const val = m[2].trim();
    if (key === '编队' || key === '物资获取') continue;
    fields[key] = val;
    if (RESERVED_FIELDS.has(key) || !val) continue;
    const amountMatch = val.match(/^\+?(\d+)\s*$/);
    if (amountMatch) {
      rewardLines.push({
        name: normalizeResourceName(key),
        amount: Number(amountMatch[1]),
      });
    }
  }

  if (fields['产出']) {
    const meta = settlementCardMeta(fields);
    return {
      kind: inferKindFromSquadName(fields['编队'] ?? fields['结算对象'] ?? ''),
      target: fields['编队'] ?? fields['结算对象'] ?? '',
      materials: parseOutputStarMaterials(fields['产出']),
      participants: meta.participants,
      subtitle: meta.subtitle,
    };
  }

  const materials = fields['获取物资']
    ? parseMaterialList(fields['获取物资'])
    : rewardLines;

  const kindSource = fields['结算对象'] ?? fields['编队'] ?? fields['标题'] ?? '';
  const meta = settlementCardMeta(fields);
  return {
    kind: fields['类型']
      ? (fields['类型'] as SettlementKind)
      : inferKindFromSquadName(kindSource) || inferKindFromTitle(kindSource, content),
    target: fields['结算对象'] ?? fields['标题'] ?? fields['编队'] ?? '',
    materials,
    participants: meta.participants,
    subtitle: meta.subtitle,
  };
}

function parseSettlementCardBlocks(content: string): ParsedSettlementCard[] {
  const squadNamed = parseSquadNamedSettlementLines(content);
  if (squadNamed.length) return squadNamed;
  if (/\[编队\|/.test(content)) {
    const multi = parseMultiSquadBlocks(content);
    if (multi.length) return multi;
  }
  const combined = parseCombinedMaterialBlock(content);
  if (combined.length) return combined;
  const single = parseSettlementCardContent(content);
  return single.materials.length ? [single] : [single];
}

export function extractSettlementCardsFromStory(story: string): ParsedSettlementCard[] {
  if (!story) return [];
  const cards: ParsedSettlementCard[] = [];
  SETTLEMENT_CARD_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = SETTLEMENT_CARD_RE.exec(story)) !== null) {
    cards.push(...parseSettlementCardBlocks(match[1]));
  }
  return dedupeSettlementCards(cards);
}

function settlementCardFingerprint(card: ParsedSettlementCard): string {
  const mats = card.materials
    .map(m => `${normalize_warehouse_item_name(m.name)}:${m.amount}`)
    .sort()
    .join('|');
  return `${card.kind}#${card.target}#${mats}`;
}

function dedupeSettlementCards(cards: ParsedSettlementCard[]): ParsedSettlementCard[] {
  const seen = new Set<string>();
  return cards.filter(card => {
    if (card.materials.length === 0) {
      return false;
    }
    const key = settlementCardFingerprint(card);
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function affairForCard(stat: Schema, card: ParsedSettlementCard): string | undefined {
  if (card.kind === '工作') {
    const blob = `${card.subtitle ?? ''}${card.target ?? ''}`;
    for (const project of WORK_PROJECT_CATALOG) {
      if (blob.includes(project.name)) {
        const key = `交付清点·${project.name}`;
        if (stat.综合事物[key]) {
          return key;
        }
      }
    }
  }

  const pending = Object.keys(stat.综合事物).filter(name =>
    /^归来清点·|^交付清点·/.test(name),
  );
  if (pending.length === 0) {
    return undefined;
  }

  const canonicalSquad =
    card.kind === '采集' ? '采集队' : card.kind === '狩猎' ? '狩猎队' : card.kind === '探索' ? '探索队' : '';

  for (const name of pending) {
    const affair = stat.综合事物[name];
    const squadMeta = affair.元数据?.编队;
    if (canonicalSquad && squadMeta === canonicalSquad) {
      return name;
    }
    if (card.participants?.length) {
      const overlap = card.participants.some(p => affair.具名参与.includes(p));
      if (overlap && canonicalSquad && name.includes(canonicalSquad.replace('队', ''))) {
        return name;
      }
    }
  }

  return pending.find(name => {
    const suffix = name.replace(/^归来清点·|^交付清点·/, '');
    const targetNorm = card.target.replace(/_/g, '').replace(/\//g, '');
    if (suffix && targetNorm.includes(suffix.replace(/队/g, ''))) return true;
    if (targetNorm.includes(suffix.replace(/[-_·]/g, ''))) return true;
    if (card.target && name.includes(card.target.split(/[-_·/]/)[0])) return true;
    if (card.kind === '采集' && name.includes('采集')) return true;
    if (card.kind === '狩猎' && name.includes('狩猎')) return true;
    if (card.kind === '工作' && name.includes('交付')) return true;
    return false;
  });
}

function clearReturnSettlementNpcTasks(stat: Schema, card: ParsedSettlementCard, affairName?: string): void {
  const affair = affairName ? stat.综合事物[affairName] : undefined;
  const members = new Set([
    ...(affair?.具名参与 ?? []),
    ...(card.participants ?? []),
  ]);
  for (const name of members) {
    const npc = stat.具名NPC[name];
    if (!npc) continue;
    if (/归来清点|待清点|献宝|上交/.test(npc.当前任务 ?? '')) {
      npc.当前任务 = '待指派';
    }
  }
}

/** settlement_card 已出现时，将对应「归来清点·*」标为已完成 */
export function completePendingAffairsFromSettlementCards(
  stat: Schema,
  story: string,
  messageText = '',
): boolean {
  const cardSource = settlementCardSource(messageText, story);
  const cards = extractSettlementCardsFromStory(cardSource);
  if (cards.length === 0) {
    return false;
  }

  let changed = false;
  for (const card of cards) {
    if (card.materials.length === 0 && (card.participants?.length ?? 0) === 0) {
      continue;
    }
    const affairName = affairForCard(stat, card);
    if (!affairName) {
      continue;
    }
    const affair = stat.综合事物[affairName];
    if (!affair || affair.状态 === '已完成') {
      continue;
    }
    affair.状态 = '已完成';
    clearReturnSettlementNpcTasks(stat, card, affairName);
    changed = true;
    console.info('[综合事物] settlement_card 已结算，标记完成:', affairName);
  }
  return changed;
}

/** 按聊天记录回放 settlement_card，归档已结算的归来/交付清点 */
export function completePendingAffairsFromSettlementChatHistory(stat: Schema, maxMessageId: number): boolean {
  if (typeof getChatMessages !== 'function' || maxMessageId < 0) {
    return false;
  }
  let changed = false;
  const msgs = getChatMessages(`0-${maxMessageId}`).filter(m => m.role === 'assistant');
  for (const msg of msgs) {
    const story = extractStoryFromMessage(msg.message);
    changed =
      completePendingAffairsFromSettlementCards(stat, story, msg.message) || changed;
  }
  return changed;
}

function addToWarehouse(stat: Schema, name: string, amount: number): void {
  const key = normalize_warehouse_item_name(name);
  const slot = stat.营地.仓库储备[key] ?? stat.营地.仓库储备[name] ?? {
    当前: 0,
    上限: default_warehouse_cap(key),
  };
  const cap = slot_cap(key, slot);
  const next = slot.当前 + amount;
  if (next > cap) {
    // A7：超单格上限不再静默丢弃，超出部分进临时仓（按日消散）
    slot.当前 = cap;
    add_to_temporary(stat, key, next - cap);
  } else {
    slot.当前 = next;
  }
  stat.营地.仓库储备[key] = slot;
  if (key !== name && stat.营地.仓库储备[name]) {
    delete stat.营地.仓库储备[name];
  }
}

/**
 * 迫降舱开局储物仓基准。
 * 【铁律】必须与 wreckOpeningStatPreset.ts 逐项一致 —— 回放会按这份基准整份重建仓库，
 * 一旦两边不同，玩家会看到「开局 24 份、回放后变 30 份」这种幽灵变化（B6 审计发现过一次）。
 */
export function openingWarehouseBaseline(
  route: '迫降' | '自定义',
): Schema['营地']['仓库储备'] {
  if (route === '自定义') {
    /* 自定义开局 = 原始部落白手起家：不继承飞船补给，只给少量引火木柴。
       与 customOpeningStatPreset 必须逐项一致（否则回放会把仓库改回另一套）。 */
    return {
      坚固木材: { 当前: 0, 上限: capOf('坚固木材') },
      藤蔓: { 当前: 0, 上限: capOf('藤蔓') },
      石料: { 当前: 0, 上限: capOf('石料') },
      清水: { 当前: 0, 上限: capOf('清水') },
      黏土: { 当前: 0, 上限: capOf('黏土') },
      高蛋白棒: { 当前: 0, 上限: capOf('高蛋白棒') },
      压缩饼干: { 当前: 0, 上限: capOf('压缩饼干') },
      营养肉罐头: { 当前: 0, 上限: capOf('营养肉罐头') },
      普通木柴: { 当前: 6, 上限: capOf('普通木柴') },
    };
  }
  return {
    坚固木材: { 当前: 0, 上限: capOf('坚固木材') },
    藤蔓: { 当前: 0, 上限: capOf('藤蔓') },
    石料: { 当前: 0, 上限: capOf('石料') },
    清水: { 当前: 0, 上限: capOf('清水') },
    黏土: { 当前: 0, 上限: capOf('黏土') },
    风干肉条: { 当前: 20, 上限: capOf('风干肉条') },
    普通木柴: { 当前: 12, 上限: capOf('普通木柴') },
  };
}

function isWarehouseMaterial(name: string): boolean {
  const n = normalize_warehouse_item_name(name);
  if (/情报|见闻|探索度|声誉|威望/.test(n)) {
    return false;
  }
  return true;
}

/**
 * 某物资「这一楼到底到了多少」= 仓库当前 + 临时仓当前。
 * 必须带上临时仓：A7 之后超上限的部分没丢，只是进了临时仓；
 * 若只数仓库，补缺口逻辑会把同一批货再加一遍（400 变成 仓库200 + 临时仓400）。
 */
function warehouseStock(stat: Schema, name: string): number {
  const key = normalize_warehouse_item_name(name);
  const in_warehouse = stat.营地.仓库储备[key]?.当前 ?? stat.营地.仓库储备[name]?.当前 ?? 0;
  const in_temporary = stat.营地.临时仓?.[key]?.当前 ?? stat.营地.临时仓?.[name]?.当前 ?? 0;
  return in_warehouse + in_temporary;
}

/** 按 settlement_card 只补缺口（单条物资） */
function applySettlementCardShortfall(stat: Schema, cards: ParsedSettlementCard[]): boolean {
  let changed = false;
  for (const card of cards) {
    for (const { name, amount } of card.materials) {
      if (!isWarehouseMaterial(name) || amount <= 0) {
        continue;
      }
      const current = warehouseStock(stat, name);
      if (current >= amount) {
        continue;
      }
      addToWarehouse(stat, name, amount - current);
      changed = true;
    }
  }
  return changed;
}

/** 按 settlement_card Grant 全额（用于重算回放，每楼只加一次） */
function applySettlementCardGrants(stat: Schema, cards: ParsedSettlementCard[]): void {
  for (const card of cards) {
    for (const { name, amount } of card.materials) {
      if (!isWarehouseMaterial(name) || amount <= 0) {
        continue;
      }
      addToWarehouse(stat, name, amount);
    }
  }
}

function messageHasSettlementCards(messageText: string): boolean {
  if (!messageText) {
    return false;
  }
  return extractSettlementCardsFromStory(messageText).some(card =>
    card.materials.some(m => isWarehouseMaterial(m.name)),
  );
}

/** settlement_card 只从完整楼层正文解析一次（勿拼接 story，否则与 message 重复计两次） */
function settlementCardSource(messageText: string, story = ''): string {
  return messageText.trim() || story.trim();
}

/**
 * MVU 对「父路径不存在」的 add（如 /营地/仓库储备/普通木柴/当前）会静默失败；
 * 从正文 JSONPatch 按 settlement 语义补写入库。
 */
export function repairWarehouseJsonPatchesFromMessage(stat: Schema, messageText: string): boolean {
  if (!messageText) {
    return false;
  }
  let changed = false;
  for (const patch of extractJsonPatchesFromMessage(messageText)) {
    const path = patch.path;
    if (!path) {
      continue;
    }
    const addCurrent = path.match(/^\/营地\/仓库储备\/([^/]+)\/当前$/);
    if (addCurrent && patch.op === 'add') {
      // 只认 add（入库 / 赠送）。**拒绝 replace**：那是"直接改库存"的写法 ——
      // 实机里模型一句"我把生肉扔了"就把 40 单位清零（D1：结构性字段只有 resolver 能写）。
      // 日常消耗由回放的机械吃粮负责，不需要模型去 replace。
      const name = decode_json_pointer_segment(addCurrent[1]);
      const amount = Number(patch.value);
      if (!Number.isFinite(amount)) {
        continue;
      }
      if (amount > 0) {
        addToWarehouse(stat, name, amount);
        changed = true;
      }
      continue;
    }
    if (addCurrent && patch.op === 'replace') {
      const name = decode_json_pointer_segment(addCurrent[1]);
      const target = Number(patch.value);
      const cur = Number(stat.营地.仓库储备[name]?.当前 ?? 0);
      // 审计 F2-07：整片忽略会让「模型按 replace 扣口粮」这类合理消耗凭空不生效。
      // 折中：只在**正文明确写吃/烹饪/分食**时接受「向下 replace」，且扣减幅度不超过当前库存的 30%；
      // 其余情况（例如"我把生肉扔了"）仍按 D1 拒绝，避免一句话清零。
      const eating =
        /(吃|进食|进餐|分食|烹|煮|烤|烧水|喂|口粮|开.*罐头|干粮)/.test(messageText ?? '');
      const delta = cur - target;
      if (eating && Number.isFinite(target) && target >= 0 && delta > 0 && delta <= Math.max(3, cur * 0.3)) {
        stat.营地.仓库储备[name]!.当前 = target;
        changed = true;
        console.info(
          `[仓库] 接受正文语境内的消耗：${name} ${cur} → ${target}`,
        );
      } else {
        console.warn(
          `[仓库] 忽略模型对库存的直接改写：replace /营地/仓库储备/${name}/当前 = ${patch.value}（当前 ${cur}）`,
        );
      }
      continue;
    }
    const addSlot = path.match(/^\/营地\/仓库储备\/([^/]+)$/);
    if (addSlot && patch.op === 'add' && patch.value && typeof patch.value === 'object') {
      const name = decode_json_pointer_segment(addSlot[1]);
      const raw = patch.value as { 当前?: number; 上限?: number };
      const key = normalize_warehouse_item_name(name);
      const slot = stat.营地.仓库储备[key] ?? {
        当前: 0,
        上限: default_warehouse_cap(key),
      };
      if (Number.isFinite(raw.当前)) {
        // AI 补库是「不可信输入」（铁律：AI 不做计数），所以只钳制、不转临时仓
        // （转仓等于给 AI 开后门灌仓）。但**不能静默**：差额必须留痕，
        // 否则溢出量消失在 Math.min 里，玩家与排查都看不到。
        const cap = slot_cap(key, slot);
        const want = Math.max(0, raw.当前!);
        const clamped = Math.min(cap, want);
        const dropped = want - clamped;
        if (dropped > 0) {
          console.warn(
            `[仓库] AI 补库超单格上限，已截断：${key} 请求 ${want} → 上限 ${cap}，丢弃 ${dropped}`,
          );
        }
        slot.当前 = clamped;
        changed = true;
      }
      if (Number.isFinite(raw.上限) && raw.上限! > slot.上限) {
        slot.上限 = raw.上限!;
        changed = true;
      }
      stat.营地.仓库储备[key] = slot;
    }
  }
  if (changed) {
    console.info('[仓库] 已按 JSONPatch 补入库（只认 add；直接 replace 库存会被忽略）');
  }
  return changed;
}

const MEAL_CONSUMPTION_RE =
  /(午饭|午餐|开.*罐头|吃.*罐头|分食|进餐|打开了|营养肉罐头|压缩饼干|蛋白棒|高蛋白棒)/;

/**
 * AI 常把迫降舱库存 patch 到 /营地/物品栏/*，而 UI 读 /营地/仓库储备/*。
 * 当正文描写进食且 patch 改动物品栏数量时，同步扣减储物仓。
 */
export function syncInventoryBarConsumptionToWarehouse(
  stat: Schema,
  messageText: string,
  story: string,
): boolean {
  const blob = `${story}\n${messageText}`;
  if (!MEAL_CONSUMPTION_RE.test(blob)) {
    return false;
  }
  let changed = false;
  for (const patch of extractJsonPatchesFromMessage(messageText)) {
    const m = patch.path?.match(/^\/营地\/物品栏\/([^/]+)\/(数量|当前)$/);
    if (!m || patch.op !== 'replace') {
      continue;
    }
    const rawName = decode_json_pointer_segment(m[1]);
    const item = normalize_warehouse_item_name(rawName);
    const slot = stat.营地.仓库储备[item];
    if (!slot || slot.当前 <= 0) {
      continue;
    }
    const target = Number(patch.value);
    if (!Number.isFinite(target)) {
      continue;
    }
    const invEntry = stat.营地.物品栏[rawName];
    const prevInv = invEntry?.数量 ?? 1;
    const delta = Math.max(0, prevInv - target);
    const consume = delta > 0 ? delta : target === 0 ? 1 : 0;
    if (consume <= 0) {
      continue;
    }
    slot.当前 = Math.max(0, slot.当前 - consume);
    changed = true;
    if (invEntry) {
      delete stat.营地.物品栏[rawName];
    }
  }
  if (changed) {
    console.info('[仓库] 已将物品栏进食 patch 同步至储物仓扣减');
  }
  return changed;
}

type WorldTickSnapshot = { 生存天数: number; 时间: string };

/**
 * 读该楼层快照里的世界时间。
 *
 * 实测（localhost:8000 + TH/mvu 当前版本）：
 *   `getChatMessages(-1)[0]` 的字段是 message_id/name/role/is_hidden/message/data/extra/swipe_id/swipes，
 *   **没有 variables**；逐楼 stat_data 挂在 `message.data.stat_data` 上，
 *   且与 `Mvu.getMvuData({type:'message'})` 逐楼完全一致。
 * 旧版形态（`variables[0].stat_data`）一并兼容。读不到就返回 null —— 宁可不算，也不要猜时间。
 */
function read_message_world_tick(msg: { message?: unknown }): WorldTickSnapshot | null {
  type StatLike = { 世界?: { 生存天数?: unknown; 时间?: unknown } };
  type Carrier = {
    data?: { stat_data?: StatLike };
    variables?: { stat_data?: StatLike } | Array<{ stat_data?: StatLike }>;
  };
  const carrier = msg as unknown as Carrier;
  const vars = carrier.variables;
  const from_variables = Array.isArray(vars) ? vars[0]?.stat_data : vars?.stat_data;
  const world = (carrier.data?.stat_data ?? from_variables)?.世界;
  if (!world) {
    return null;
  }
  const day = Number(world.生存天数);
  const clock = typeof world.时间 === 'string' ? world.时间.trim() : '';
  if (!Number.isFinite(day) || !clock) {
    return null;
  }
  return { 生存天数: day, 时间: clock };
}

/** 读该楼快照里的人口（口粮消耗按楼当时的在册人口算） */
function read_message_population(msg: { message?: unknown }): number {
  type StatLike = { 营地?: { 人口?: unknown } };
  type Carrier = {
    data?: { stat_data?: StatLike };
    variables?: { stat_data?: StatLike } | Array<{ stat_data?: StatLike }>;
  };
  const carrier = msg as unknown as Carrier;
  const vars = carrier.variables;
  const from_variables = Array.isArray(vars) ? vars[0]?.stat_data : vars?.stat_data;
  const pop = Number((carrier.data?.stat_data ?? from_variables)?.营地?.人口);
  return Number.isFinite(pop) && pop > 0 ? pop : 0;
}

/**
 * 两楼快照之间的 Δt（小时）：走 `balance/timeAdvance.elapsed_hours`，单一口径。
 * 回拨 → 0（不猜跨夜）；单步超过安全阀视为时间数据异常，按上限截断。
 */
function hours_between(prev: WorldTickSnapshot, curr: WorldTickSnapshot): number {
  return Math.min(elapsed_hours(prev, curr), TIME.MAX_DECAY_STEP_HOURS);
}

/**
 * 从开局基准按 AI 楼顺序重算储物仓（每楼 patch 与 card 不重复计入）。
 *
 * A6/A7 落在这里：储物仓是**从聊天记录重建**的，所以时间驱动的损耗（腐坏、临时仓消散）
 * 必须参与重建，否则每轮都会被重建抹平。逐楼用「上一条快照 → 这一条快照」的 Δt 结算，
 * 入库发生在本楼末尾，因此先结算时间、再入库，新到的货物不会被倒扣时间。
 */
export function replayWarehouseReservesFromChat(stat: Schema, max_message_id: number): boolean {
  if (typeof getChatMessages !== 'function' || max_message_id < 0) {
    return false;
  }

  const route = (String((stat.世界 as { 开局路线?: string }).开局路线 ?? '迫降') as '迫降' | '自定义');
  const replayWh = klona(openingWarehouseBaseline(route));
  const replayTemp: Schema['营地']['临时仓'] = {};
  const scratch = {
    营地: { 仓库储备: replayWh, 物品栏: {}, 临时仓: replayTemp },
  } as Schema;

  const msgs = getChatMessages(`0-${max_message_id}`).filter(m => m.role === 'assistant');
  const seen_message_ids = new Set<number>();
  let prev_tick: WorldTickSnapshot | null = null;
  /** 口粮欠账：逐楼可能只过零点几小时，攒够整份再吃，避免每楼 floor 掉 */
  let meal_debt = 0;
  for (const msg of msgs) {
    if (seen_message_ids.has(msg.message_id)) {
      continue;
    }
    seen_message_ids.add(msg.message_id);

    const tick = read_message_world_tick(msg);
    if (tick && prev_tick) {
      const hours = hours_between(prev_tick, tick);
      if (hours > 0) {
        // 口粮：每人每日 1 配额（世界书《营地消耗与生存结算规则》），人口按该楼快照
        meal_debt +=
          read_message_population(msg) * CONSUME.RATION_PER_PERSON_PER_DAY * (hours / 24);
        const whole = Math.floor(meal_debt);
        if (whole > 0) {
          meal_debt -= whole;
          consume_rations(replayWh, whole);
        }
        // 逐楼结算时不取整，避免小额损耗被每楼四舍五入抹平；小数在循环末尾收口
        apply_decay(replayWh, hours, false);
        vanish_temporary(replayTemp, hours, false);
      }
    }
    if (tick) {
      prev_tick = tick;
    }

    const story = extractStoryFromMessage(msg.message);
    // 注意：**不再**跑 syncInventoryBarConsumptionToWarehouse（AI 写物品栏进食 → 扣仓库）。
    // 食量现在由上面的机械消耗拥有（每人每日 1 配额、先吃易腐坏），两处都扣就是双写。

    const cardSource = settlementCardSource(msg.message, story);
    const cards = extractSettlementCardsFromStory(cardSource);
    if (messageHasSettlementCards(cardSource)) {
      // 同一楼既有 card 又有 patch 时，以 card 为准，避免 +32 变 +64
      applySettlementCardGrants(scratch, cards);
      // patch 漏写或父路径不存在时补缺口（如引火物），不重复叠加已满额物资
      applySettlementCardShortfall(scratch, cards);
    } else {
      repairWarehouseJsonPatchesFromMessage(scratch, msg.message);
    }
  }

  for (const slot of Object.values(replayWh)) {
    slot.当前 = Math.max(0, Math.round(slot.当前));
  }
  for (const name of Object.keys(replayTemp)) {
    const entry = replayTemp[name];
    entry.当前 = Math.max(0, Math.round(entry.当前 * 10) / 10);
    if (entry.当前 <= 0) {
      delete replayTemp[name];
    }
  }

  // 回放模型之外的存量（UI 直接入库 / 旧档遗留）原样保留。
  // 注意：**不能给它们补算腐坏** —— 这类存量不是从历史重算出来的，
  // 而 run_stat_sync_startup 一次加载会跑 1~3 遍（0/1.5s/4s），按总 Δt 补算会成倍扣。
  const merged = klona(replayWh);
  for (const [name, slot] of Object.entries(stat.营地.仓库储备)) {
    if (!(name in merged) && slot.当前 > 0) {
      merged[name] = klona(slot);
    }
  }

  // 逐楼增量容差：面板指令（添柴/加固/投喂/规划）扣的料不在聊天记录里，
  // 回放从基准重建会把它们抹回。凡「当前值 < 回放值」，说明发生过扣料 → 保留较小的当前值。
  for (const [name, slot] of Object.entries(merged)) {
    const cur = Number(stat.营地.仓库储备[name]?.当前 ?? Number.NaN);
    const rep = Number((slot as { 当前?: number }).当前 ?? 0);
    if (Number.isFinite(cur) && cur < rep) {
      ;(slot as { 当前: number }).当前 = cur;
    }
  }

  const stock_same = _.isEqual(stat.营地.仓库储备, merged);
  const temp_same = _.isEqual(stat.营地.临时仓 ?? {}, replayTemp);
  if (stock_same && temp_same) {
    return false;
  }
  if (!stock_same) {
    stat.营地.仓库储备 = merged;
  }
  if (!temp_same) {
    stat.营地.临时仓 = klona(replayTemp);
  }
  console.info('[仓库] 已按聊天记录重算储物仓（含腐坏与临时仓）');
  return true;
}

/**
 * 将各资源「当前」限制在单格上限内。
 *
 * 注意：这里**不再**把超出部分转进临时仓 —— 临时仓是「回放派生」的（见
 * replayWarehouseReservesFromChat），而这一次加载里 pipeline 会跑 1~3 遍，
 * 在收口处临时仓加东西会被下一遍回放清掉，来回抖动。溢出落点在入库那一处
 * （addToWarehouse → add_to_temporary）和 advance() 的 route_overflow，二者都只算一次。
 */
/**
 * 储存类建筑判定（审计 F2-01：此前管线与 metrics 各有一套口径）。
 * 以功能标签为准，名称关键词只作旧档兜底。
 */
export function is_storage_building(
  name: string,
  building?: { 功能标签?: string[]; 建筑阶段?: string },
): boolean {
  if (building?.建筑阶段 !== '已建成' && building?.建筑阶段 !== '受损') return false;
  const tags = building?.功能标签;
  if (Array.isArray(tags) && tags.includes('储存')) return true;
  return /堆架|物资棚|沙土窖|陶缸|仓/.test(name);
}

export function clampWarehouseReserves(stat: Schema): boolean {
  let changed = false;
  let clipped = 0;
  for (const [name, slot] of Object.entries(stat.营地.仓库储备)) {
    const cap = slot_cap(name, slot);
    if (slot.当前 > cap) {
      clipped += slot.当前 - cap;
      slot.当前 = cap;
      changed = true;
    }
    if (slot.当前 < 0) {
      slot.当前 = 0;
      changed = true;
    }
  }
  if (clipped > 0) {
    console.warn(`[仓库] ${Math.round(clipped)} 单位超出单格上限，已按上限截断（未登记来源，不转临时仓）`);
  }
  return changed;
}

/**
 * JSONPatch 未写入或写错仓库时，按 settlement_card 明文补入库（不自行推算产出）。
 */
export function syncWarehouseFromSettlementStory(
  stat: Schema,
  story: string,
  options: { messageText?: string; messageId?: number; syncedFloors?: number[] } = {},
): boolean {
  const cardSource = settlementCardSource(options.messageText ?? '', story);
  if (!cardSource) {
    return false;
  }
  if (
    options.messageId !== undefined &&
    options.syncedFloors?.includes(options.messageId)
  ) {
    // 仍允许补全「归来清点」状态，仅跳过重复入库
  }

  const cards = extractSettlementCardsFromStory(cardSource);
  if (cards.length === 0) return false;

  const alreadySynced =
    options.messageId !== undefined &&
    options.syncedFloors?.includes(options.messageId);

  let changed = false;
  for (const card of cards) {
    const affairName = affairForCard(stat, card);
    if (affairName && stat.综合事物[affairName]?.状态 !== '已完成') {
      stat.综合事物[affairName].状态 = '已完成';
      clearReturnSettlementNpcTasks(stat, card, affairName);
      changed = true;
    }
  }

  if (alreadySynced) {
    return changed || clampWarehouseReserves(stat);
  }

  changed = applySettlementCardShortfall(stat, cards) || changed;

  if (changed) {
    console.info('[仓库] 已从 settlement_card 补写入库（JSONPatch 遗漏或路径无效）');
  }
  return changed || clampWarehouseReserves(stat);
}

/** AI 误写 /仓库储备 时合并到 /营地/仓库储备（仅路径修正，不自行结算产出） */
export function repairMisplacedWarehouse(data: Schema): boolean {
  const root = data as Schema & { 仓库储备?: Schema['营地']['仓库储备'] };
  const misplaced = root.仓库储备;
  if (!misplaced || typeof misplaced !== 'object') return false;

  let changed = false;
  for (const [name, entry] of Object.entries(misplaced)) {
    if (!entry || typeof entry !== 'object') continue;
    const current = Number(entry.当前);
    const max = Number(entry.上限);
    const slot = data.营地.仓库储备[name] ?? { 当前: 0, 上限: 200 };
    if (Number.isFinite(current) && current > slot.当前) {
      slot.当前 = current;
      changed = true;
    }
    if (Number.isFinite(max) && max > slot.上限) {
      slot.上限 = max;
      changed = true;
    }
    data.营地.仓库储备[name] = slot;
  }
  delete root.仓库储备;
  if (changed) {
    console.info('[仓库] 已合并误路径 /仓库储备 → /营地/仓库储备');
  }
  return changed || clampWarehouseReserves(data);
}

export function extractStoryFromMessage(text: string): string {
  const m = text.match(/(?:<|&lt;)story(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/story(?:>|&gt;)/i);
  return m?.[1] ?? text;
}

export function getLatestAssistantStoryAndMessage(): {
  story: string;
  message: string;
  messageId?: number;
} {
  if (typeof getChatMessages !== 'function') {
    return { story: '', message: '' };
  }
  const latest = getChatMessages(-1, { role: 'assistant' })[0];
  if (!latest) {
    return { story: '', message: '' };
  }
  return {
    story: extractStoryFromMessage(latest.message),
    message: latest.message,
    messageId: latest.message_id,
  };
}
