import type { Schema } from '../schema'

/**
 * 模型常见补丁错误兜底：
 * ① 对「仓库里不存在的物资」用 delta（undefined + N）→ 整条补丁被 MVU 拒绝
 * ② 对「前端维护的字典」整表 replace → 正在进行的项被抹掉
 */

const PROTECTED_DICTS: Array<[string, string]> = [
  ['工作队列', '进行中'],
  ['探索编队', '采集中'],
  ['综合事物', '进行中'],
]

/** 从消息文本里抽取 JSONPatch 操作（宽松解析，失败返回空） */
export function extract_patch_ops(message_text: string): Array<Record<string, unknown>> {
  const text = String(message_text ?? '')
  const blocks = text.match(/<JSONPatch>[\s\S]*?<\/JSONPatch>/g) ?? []
  for (const block of blocks) {
    const body = block.replace(/<\/?JSONPatch>/g, '').trim()
    const candidates = [body, ...(body.match(/\[[\s\S]*\]/g) ?? [])]
    for (const c of candidates) {
      try {
        const parsed = JSON.parse(c)
        if (Array.isArray(parsed)) return parsed as Array<Record<string, unknown>>
        if (parsed && typeof parsed === 'object') return [parsed as Record<string, unknown>]
      } catch {
        /* 试下一个形式 */
      }
    }
  }
  return []
}

function warehouse_has(stock: Record<string, unknown>, name: string): boolean {
  if (name in stock) return true
  return Object.keys(stock).some((k) => k.includes(name) || name.includes(k))
}

/** delta-on-missing → add：避免「整条补丁作废」 */
export function repair_delta_on_missing(stat: Schema, message_text: string): boolean {
  const ops = extract_patch_ops(message_text)
  if (ops.length === 0) return false
  const stock = stat.营地.仓库储备 as unknown as Record<string, { 当前: number; 上限?: number }>
  let changed = false
  for (const op of ops) {
    if (op.op !== 'delta' || typeof op.path !== 'string') continue
    const m = op.path.match(/^\/营地\/仓库储备\/([^/]+)\/当前$/)
    if (!m) continue
    const name = m[1]
    if (warehouse_has(stock, name)) continue
    const amount = Number(op.value)
    if (!Number.isFinite(amount)) continue
    stock[name] = { 当前: Math.max(0, amount), 上限: 200 }
    changed = true
    console.info('[补丁修复] delta-on-missing 已补成 add:', name, amount)
  }
  return changed
}

/** 整表 replace 后还原「仍在进行中」的项 */
export function restore_local_records(
  stat: Schema,
  snapshot: Record<string, Record<string, unknown>> | undefined,
): boolean {
  if (!snapshot) return false
  let changed = false
  for (const [dict, keep_status] of PROTECTED_DICTS) {
    const before = snapshot[dict]
    const now = (stat as unknown as Record<string, Record<string, unknown>>)[dict]
    if (!before || !now) continue
    for (const [name, item] of Object.entries(before)) {
      if (name in now) continue
      const status = (item as { 状态?: string })?.状态
      if (status !== keep_status) continue
      now[name] = item
      changed = true
      console.info('[补丁修复] 整表覆盖后已还原:', dict, name)
    }
  }
  return changed
}
