import type { Schema } from '../../../schema';
import type { WorldTick } from '../../../balance/timeAdvance';
import { archive_tribe_log } from './tribeLog';
import { isMorningWorldTime, isNightWorldTime } from './worldClock';

function passed_first_cold_night(data: Schema, prev: WorldTick | null): boolean {
  if (data.世界.生存天数 >= 2) {
    return true;
  }
  if (data.营地.篝火燃料.当前 <= 0) {
    return false;
  }
  if (prev && data.世界.生存天数 > prev.生存天数) {
    return true;
  }
  if (prev && isNightWorldTime(prev.时间) && isMorningWorldTime(data.世界.时间)) {
    return true;
  }
  return false;
}

/** 按规则自动完成并归档部族事务 */
export function sync_tribal_affairs(data: Schema, prev_tick: WorldTick | null): boolean {
  let changed = false;
  const cold_night = data.部族事务['熬过第一个寒夜'];
  if (cold_night && passed_first_cold_night(data, prev_tick)) {
    archive_tribe_log(data, {
      类型: '部族事务',
      关联键: '熬过第一个寒夜',
      说明: cold_night.说明,
      归档摘要: `${data.世界.兽历} ${data.世界.时间}：部落已度过第一个寒夜`,
      创建日期: cold_night.创建日期,
    });
    delete data.部族事务['熬过第一个寒夜'];
    changed = true;
    console.info('[部族事务] 已完成：熬过第一个寒夜');
  }
  return changed;
}
