import type { Schema } from '../schema';
import {
  collect_pending_authorized_squad_names,
  get_disbanded_squad_names,
  parse_squad_create_commands,
} from './squadUserCommands';

type Stat = Schema;

const USER_INPUT_RE = /<本轮用户输入>([\s\S]*?)<\/本轮用户输入>/i;

function squad_names_from_user_text(text: string): string[] {
  return parse_squad_create_commands(text).map(c => c.name);
}

/** 从用户 [新建编队] 指令（含手打与广阔大地 UI）收集合法编队名 */
export function collect_authorized_squad_names(max_message_id: number): Set<string> {
  const names = new Set<string>();
  if (typeof getChatMessages !== 'function' || max_message_id < 0) {
    return names;
  }

  const msgs = getChatMessages(`0-${max_message_id}`);
  for (const msg of msgs) {
    if (msg.role !== 'user') {
      continue;
    }
    const hit = USER_INPUT_RE.exec(msg.message);
    USER_INPUT_RE.lastIndex = 0;
    const text = hit?.[1]?.trim() ?? msg.message;
    if (!/\[新建编队\]/.test(text)) {
      continue;
    }
    for (const name of squad_names_from_user_text(text)) {
      names.add(name);
    }
  }

  for (const name of get_disbanded_squad_names()) {
    names.delete(name);
  }
  for (const name of collect_pending_authorized_squad_names()) {
    names.add(name);
  }
  return names;
}

/** 移除 stat 中无玩家 [新建编队] 依据的编队（含 AI 误 insert、剧情推断残留） */
export function purge_unauthorized_exploration_squads(
  stat: Stat,
  max_message_id: number,
  authorized?: Set<string>,
): boolean {
  const allowed = authorized ?? collect_authorized_squad_names(max_message_id);
  // 面板「复用」建出来的编队没有用户楼层指令，靠这份持久授权放行
  for (const name of stat.编队档案?.已授权 ?? []) {
    allowed.add(name);
  }
  let changed = false;
  for (const name of Object.keys(stat.探索编队)) {
    if (allowed.has(name)) continue;
    delete stat.探索编队[name];
    changed = true;
    console.info('[探索编队] 已移除无 UI/玩家指令依据的编队:', name);
  }
  return changed;
}

export function resolve_latest_message_id(): number {
  try {
    return getChatMessages(-1)[0]?.message_id ?? -1;
  } catch {
    return -1;
  }
}

/** 重 roll 第 N 层后：N..latest 各楼编队只保留 0..N 层用户 [新建编队] 出现过的队名 */
export async function cascade_purge_squads_after_regenerate(from_message_id: number): Promise<void> {
  if (typeof Mvu === 'undefined' || typeof waitGlobalInitialized !== 'function') {
    return;
  }
  await waitGlobalInitialized('Mvu');
  const latest = resolve_latest_message_id();
  if (latest < from_message_id) {
    return;
  }
  const authorized = collect_authorized_squad_names(from_message_id);
  for (let mid = from_message_id; mid <= latest; mid++) {
    const mvu_data = Mvu.getMvuData({ type: 'message', message_id: mid });
    const stat = _.get(mvu_data, 'stat_data') as Stat | undefined;
    if (!stat || typeof stat !== 'object') continue;
    if (!purge_unauthorized_exploration_squads(stat, from_message_id, authorized)) {
      continue;
    }
    _.set(mvu_data, 'stat_data', stat);
    await Mvu.replaceMvuData(mvu_data, { type: 'message', message_id: mid });
  }
}
