/**
 * 功能组需求目录（需求组落地的核心一层）
 *
 * 设计：扣料需求不写具体物资，而写"功能组"（骨架/覆盖物/绑扎…）。
 * 每个功能组有一份候选物资清单；仓库里任意候选都能折算等价量顶替。
 * 全部候选用完仍不够 → 允许「杂物」按 0.6 系数兜底（永不建不起来）。
 */


/**
 * 食物/药品不能当建材替代（实机踩过：加固栅栏把 24 个高蛋白棒当"杂物"扣光）。
 * 仓库槽位的 类别 可能是「杂物」默认值，所以还要按名字兜一层。
 */
const CONSUMABLE_RE = /肉|粮|饭|饼|果|块茎|棒|罐头|奶|蛋|鱼|薯|谷|麦|面包|干粮|口粮|糖|盐|药|膏|绷带|膏药/
function is_consumable_name(name: string): boolean {
  return CONSUMABLE_RE.test(String(name ?? ''))
}


/** 按名字粗略判定大类（不引外部模块，保证离线断言可运行） */
function guess_category(name: string): string {
  const n = String(name ?? '')

  // 顺序很重要：先判工具/燃料/医疗这类明确后缀，最后才判食物。
  // 之前「棒」同时出现在食物与工具正则里且食物在前 → 木棒/防身短棒被判成食物。
  if (/药|膏|糊|汁|汤|敷|绷带|丸|散/.test(n)) return '医疗'
  if (/木柴|木炭|燃料|煤油|柴薪/.test(n)) return '燃料'
  if (/矛|斧|刀|锤|镐|铲|棒|叉|箭|弓|网|陷阱|背篓|水袋|骨针|钩/.test(n)) return '工具与装备'
  if (/残骸|零件|星痕|合金|能源块|矿屑|种子/.test(n)) return '珍异储备'

  // 食物：去掉与工具冲突的「棒」，补上实际会出现的「面/粉/干」等写法
  if (/肉|粮|饭|饼|面|粉|果|块茎|罐头|奶|蛋|鱼|薯|谷|麦|干粮|口粮|糖|盐|菌|菇|菜/.test(n)) {
    return '食物'
  }
  return '材料'
}

export const FUNCTION_GROUPS: Record<string, string[]> = {
  骨架: ['木材', '坚固木材', '原木', '树枝', '石料', '骨材', '金属杆'],
  覆盖物: ['兽皮', '厚毛皮', '毛皮', '旧麻布', '麻布', '布', '藤编席', '席子', '油布'],
  填充: ['干草', '芦苇', '苔藓', '稻草', '绒毛'],
  硬质: ['石料', '黏土', '金属', '铁片', '骨材'],
  绑扎: ['藤蔓', '绳', '麻绳', '皮条', '藤条'],
  功能件: ['工具', '铁片', '齿轮', '铜锭', '燧石'],
}

/** 功能组兜底：任何「杂物」类物资都可按 0.6 系数顶替 */
export const FALLBACK_CATEGORY = '杂物'
export const FALLBACK_FACTOR = 0.6

export function is_function_group(key: string): boolean {
  return Object.prototype.hasOwnProperty.call(FUNCTION_GROUPS, key)
}

/**
 * 把功能组展开成"仓库里实际存在且可用"的候选物资名列表。
 * 顺序：静态表命中的 → 其余同类别物资 → 杂物兜底。
 */
/** 各功能组可接受的「同类材料」特征词：extras 必须命中本组，否则同仓所有材料都会顶替任何需求 */
const GROUP_KEYWORDS: Record<string, RegExp> = {
  骨架: /木|石|骨|金属|杆/,
  覆盖物: /皮|布|席|油布|麻/,
  填充: /草|苇|苔|绒|稻/,
  硬质: /石|黏|金属|铁|骨|矿/,
  绑扎: /藤|绳|条|线/,
  功能件: /工具|铁|齿轮|铜|燧石|零件/,
}

export function resolve_group_candidates(
  group: string,
  warehouse: Record<string, { 当前?: number; 类别?: string; 锁定?: boolean }>,
): string[] {
  const names = Object.keys(warehouse ?? {})
  const listed = (FUNCTION_GROUPS[group] ?? []).filter(n => names.includes(n) && Number(warehouse[n]?.当前 ?? 0) > 0 && !warehouse[n]?.锁定)

  const groupPat = GROUP_KEYWORDS[group]
  const listedSet = new Set(listed)
  const extras = names.filter(n => {
    if (listedSet.has(n)) return false
    const slot = warehouse[n]
    if (!slot || Number(slot.当前 ?? 0) <= 0 || slot.锁定) return false
    if (is_consumable_name(n)) return false
    // 必须与本功能组同类（此前只判「是材料」，导致骨架/硬质/覆盖物返回同一批候选）
    if (groupPat && !groupPat.test(n)) return false
    return (slot.类别 ?? guess_category(n) ?? '材料') === '材料'
  })

  const fallback = names.filter(n => {
    if (listedSet.has(n) || extras.includes(n)) return false
    const slot = warehouse[n]
    if (!slot || Number(slot.当前 ?? 0) <= 0 || slot.锁定) return false
    if (is_consumable_name(n)) return false
    return (slot.类别 ?? guess_category(n) ?? '杂物') === FALLBACK_CATEGORY
  })

  return [...listed, ...extras, ...fallback]
}
