// ---------------- 仓库上限（A2 按品级） ----------------
export const STORAGE = {
  BY_GRADE: { 常见: 200, 普通: 200, 少有: 100, 罕见: 30, 稀世: 10 } as Record<string, number>,
  /** 制成品默认 */
  PRODUCT: { min: 50, max: 150 },
  /** 特例覆盖（明确大于品级值时才写这里） */
  OVERRIDE: {
    坚固木材: 500, 石料: 300, 黏土: 250,
  } as Record<string, number>,
} as const

/** 单格上限查询（A2）：特例覆盖 > 品级上限 > 兜底 200 */
export function capOf(itemName: string, grade: keyof typeof STORAGE.BY_GRADE = '常见'): number {
  return STORAGE.OVERRIDE[itemName] ?? STORAGE.BY_GRADE[grade] ?? 200
}

// ---------------- 人力与产出 ----------------
export const LABOR = {
  /**
   * 无名族人基准效率 = 向心力档位系数 × 100（派生值，不再作为独立输入）
   * 解决世界书自相矛盾：「初值 40 对应低迷档」vs「动荡档效率 −30%」
   */
  BASE_EFFICIENCY_BY_COHESION(cohesion: number): number {
    if (cohesion >= 81) return 120
    if (cohesion >= 41) return 100
    if (cohesion >= 21) return 70
    return 40
  },
  /** 单位/人日（v2 模拟标定值） */
  OUTPUT_PER_MANDAY: { 采集: 3.6, 狩猎: 2.6, 探索: 1.2, 砍柴: 2.5 },
  /** 具名 NPC 的效率高于无名 */
  NAMED_MULTIPLIER: 1.33,
  /** 监工/带队加成 */
  SUPERVISE: { PER_NAMED: 0.12, CAP: 0.8 },
} as const

