// ---------------- 生存指标曲线（foodScore） ----------------
/** 口粮天数 → 分数（下限 0、上限 100，消除 12~85 的死区间） */
export function foodDaysScore(days: number): number {
  if (days <= 0) return 0
  if (days < 1) return 18
  if (days < 2) return 28
  if (days < 5) return 42
  if (days < 10) return 58
  if (days < 20) return 72
  if (days < 30) return 88
  return 100
}

