// ─── NPC 综合档位（方案 B：与单项技能 0~100 六档对齐）───

export const NPC_SKILL_TIERS = ['生疏', '入门', '熟练', '精通', '大师', '传说'] as const;
export type NpcSkillTier = (typeof NPC_SKILL_TIERS)[number];

/** @deprecated 旧四档名；写入时由 coerce 与技能推算迁移 */
export const LEGACY_NPC_GRADES = ['初学', '入门', '熟练', '精通'] as const;

export const NPC_TIER_THRESHOLDS: { min: number; tier: NpcSkillTier }[] = [
  { min: 100, tier: '传说' },
  { min: 81, tier: '大师' },
  { min: 61, tier: '精通' },
  { min: 41, tier: '熟练' },
  { min: 21, tier: '入门' },
  { min: 0, tier: '生疏' },
];

export function tier_from_skill_value(value: number): NpcSkillTier {
  const v = Math.max(0, Math.min(100, value));
  for (const row of NPC_TIER_THRESHOLDS) {
    if (v >= row.min) return row.tier;
  }
  return '生疏';
}

