export function craft_grade_for(name: string): CraftItemGrade {
  if (CRAFT_ITEM_GRADE_BY_NAME[name]) return CRAFT_ITEM_GRADE_BY_NAME[name];
  if (/粗制|简易|应急|临时/.test(name)) return '粗糙';
  if (/精制|强化|韧化|硬化/.test(name)) return '精良';
  if (/巨兽|部落|首领|仪式/.test(name)) return '传说';
  if (/图腾|议事|城墙|演进/.test(name)) return '史诗';
  if (/坠毁|星痕|迫降舱|异星/.test(name)) return '神迹';
  return '精良';
}

