export function material_grade_for(name: string): MaterialGrade {
  const direct = MATERIAL_GRADE_BY_NAME[name];
  if (direct) return direct;
  if (/杂草|枯叶|木柴|普通石/.test(name)) return '常见';
  if (/巨兽|皮甲/.test(name)) return '罕见';
  if (/异星|坠毁|星痕|迫降|能源块/.test(name)) return '稀世';
  if (/草药|燧石|菌|药用/.test(name)) return '少有';
  return '普通';
}

export function material_grade_css(name: string): string {
  return MATERIAL_GRADE_META[material_grade_for(name)].cssClass;
}

export function craft_grade_css(name: string): string {
  return CRAFT_GRADE_META[craft_grade_for(name)].cssClass;
}
