import type { Schema } from '../schema'
import { add_slot_with_overflow } from './warehouse'

/**
 * 每日结算（跨午夜触发一次）：
 * ① 伤病恢复：轻微/中度/重度按「有医篷 +2 / 无医篷 +1」推进剩余天数，归零即痊愈
 * ② 无名族人：伤病数递减、预警中递减
 * ③ 被动产出：在营地、健康、未外派、未在队列的兽耳娘按最强技能产出少量物资
 *
 * 设计约束（见世界书《医疗科技》《被动产出》设计稿）：
 *  · 具名 NPC 永不死亡；伤病只是拖慢，最多 5 天必愈
 *  · 被动产出有上限：不超过当日口粮消耗的 30%，防止"挂机也饿不死"
 */

type AnyRec = Record<string, unknown>

const 被动上限比例 = 0.3

function has_medical_tent(stat: Schema): boolean {
  const buildings = (stat.营地 as unknown as { 当前建筑?: Record<string, AnyRec> }).当前建筑 ?? {}
  for (const [name, b] of Object.entries(buildings)) {
    if (!b || b.建筑阶段 !== '已建成') continue
    const tags = Array.isArray(b.功能标签) ? (b.功能标签 as string[]) : []
    if (tags.includes('医疗')) return true
    if (/医篷|药棚|医帐/.test(name)) return true
  }
  return false
}

/** 是否正在外派或已在队列里干活 */
function is_busy(stat: Schema, name: string): boolean {
  const squads = (stat.探索编队 ?? {}) as Record<string, AnyRec>
  for (const s of Object.values(squads)) {
    const status = String(s?.状态 ?? '')
    if (status === '待命') continue
    const members = Array.isArray(s?.具名成员) ? (s.具名成员 as string[]) : []
    if (members.includes(name)) return true
  }
  const queue = (stat.工作队列 ?? {}) as Record<string, AnyRec>
  for (const q of Object.values(queue)) {
    if (String(q?.状态 ?? '') !== '进行中') continue
    const assigned = Array.isArray(q?.具名指派) ? (q.具名指派 as string[]) : []
    if (assigned.includes(name)) return true
  }
  return false
}

function add_stock(stat: Schema, item: string, count: number): void {
  if (count <= 0) return
  // 技术债清理：原来直接 `slot.当前 += count`，不钳单格上限、也不转临时仓
  // （warehouse 里设计好的溢出机制全项目零调用）。统一走 add_slot_with_overflow。
  add_slot_with_overflow(stat, item, count)
}

/** 跑一天的结算；返回本日发生的文字摘要（供事件流） */
export function settle_daily(stat: Schema): { recovered: string[]; produced: string[] } {
  const recovered: string[] = []
  const produced: string[] = []
  const tent = has_medical_tent(stat)

  // ① 伤病恢复
  const npcs = (stat.具名NPC ?? {}) as Record<string, AnyRec>
  for (const [name, npc] of Object.entries(npcs)) {
    const injury = npc?.伤病 as { 剩余天数?: number; 程度?: string } | undefined
    if (!injury) continue
    const step = tent ? 2 : 1
    const left = Number(injury.剩余天数 ?? 0) - step
    if (left <= 0) {
      delete (npc as AnyRec).伤病
      recovered.push(name)
    } else {
      injury.剩余天数 = Math.min(5, left)
    }
  }

  // ② 无名族人
  const camp = stat.营地 as unknown as { 无名族人状态?: { 伤病数?: number; 预警中?: number } }
  if (camp.无名族人状态) {
    camp.无名族人状态.伤病数 = Math.max(0, Number(camp.无名族人状态.伤病数 ?? 0) - 1)
    camp.无名族人状态.预警中 = Math.max(0, Number(camp.无名族人状态.预警中 ?? 0) - (tent ? 2 : 1))
  }

  // ②-b 区域枯竭倒计时（探索系统 v3）：归零即恢复
  const areas = stat.探索区域 as unknown as Record<
    string,
    { 状态?: string; 枯竭剩余天数?: number; 累计采集次数?: number; 累计狩猎次数?: number }
  > | undefined
  if (areas) {
    for (const area of Object.values(areas)) {
      if (!area || area.状态 !== '枯竭') continue
      const left = Math.max(0, Number(area.枯竭剩余天数 ?? 0) - 1)
      if (left <= 0) {
        area.状态 = '正常'
        area.枯竭剩余天数 = 0
        area.累计采集次数 = 0
        area.累计狩猎次数 = 0
      } else {
        area.枯竭剩余天数 = left
      }
    }
  }

  // ③ 被动产出（上限：当日口粮消耗 × 30%）
  const population = Number((stat.营地 as unknown as { 人口?: number }).人口 ?? 0)
  let budget = Math.max(1, Math.floor(population * 被动上限比例))
  for (const [name, npc] of Object.entries(npcs)) {
    if (budget <= 0) break
    if (is_busy(stat, name)) continue
    const injury = npc?.伤病 as { 程度?: string } | undefined
    if (injury && injury.程度 !== '轻微') continue
    const skills = (npc?.技能 ?? {}) as Record<string, number>
    const entries = Object.entries(skills).sort((a, b) => Number(b[1]) - Number(a[1]))
    const [topSkill, topValue] = entries[0] ?? ['采集', 0]
    const value = Number(topValue ?? 0)
    if (value < 40) continue
    const half = injury?.程度 === '轻微'

    if (topSkill === '采集') {
      const amount = Math.max(1, Math.min(budget, value >= 70 ? 3 : 2))
      const give = half ? Math.max(0, Math.floor(amount / 2)) : amount
      if (give > 0) {
        add_stock(stat, '普通木柴', give)
        produced.push(`${name} 被动采到 普通木柴×${give}`)
        budget -= give
      }
      if (value >= 60 && budget > 0 && !half) {
        add_stock(stat, '止血草', 1)
        produced.push(`${name} 顺手采到 止血草×1`)
        budget -= 1
      }
    } else if (topSkill === '后勤') {
      const give = half ? 0 : Math.max(1, Math.min(budget, value >= 70 ? 2 : 1))
      if (give > 0) {
        add_stock(stat, '兽皮碎料', give)
        produced.push(`${name} 整理了 兽皮碎料×${give}`)
        budget -= give
      }
    } else if (topSkill === '狩猎') {
      // 确定性判定：用「生存天数 + 狩猎值」决定今天是否收到猎物，
      // 避免 Math.random 导致同一楼层重放结果不同（审计 F1-07）
      const day = Number((stat.世界 as { 生存天数?: number }).生存天数 ?? 0)
      const hit = (day + value) % 10 < 3
      if (hit && budget > 0) {
        add_stock(stat, '生肉', 1)
        produced.push(`${name} 收拾陷阱得了 生肉×1`)
        budget -= 1
      }
    }
    // 战斗型：巡逻守夜，不产物资（降低夜袭概率由别处体现）
  }

  return { recovered, produced }
}

/**
 * 按「世界.生存天数」的推进量补结算。
 * 用 营地.__最近结算日 做水位，避免同一天重复发。
 */
export function settle_days_since_last(stat: Schema, max_days = 7): { days: number; recovered: string[]; produced: string[] } {
  const camp = stat.营地 as unknown as Record<string, unknown>
  const current = Number((stat.世界 as unknown as { 生存天数?: number }).生存天数 ?? 1)
  const last = Number(camp.__最近结算日 ?? current)
  const days = Math.max(0, Math.min(max_days, current - last))
  const recovered: string[] = []
  const produced: string[] = []
  for (let i = 0; i < days; i += 1) {
    const r = settle_daily(stat)
    recovered.push(...r.recovered)
    produced.push(...r.produced)
  }
  if (days > 0 || camp.__最近结算日 === undefined) {
    camp.__最近结算日 = current
  }
  return { days, recovered, produced }
}
