import _ from 'lodash';
import type { Schema } from '../../../schema';
import { WORK_PROJECT_CATALOG } from '../constants/workProjectCatalog';
import { parseMaterialString, warehouseHasMaterials } from './materials';

export function syncWorkActivation(
  work_name: string,
  work_queue: Schema['工作队列'],
  buildings: Schema['营地']['当前建筑'],
  warehouse: Schema['营地']['仓库储备'],
) {
  const work = work_queue[work_name];
  if (!work) return;

  // 暂停 / 已停止是玩家的显式意图，激活检查不得把它们拉回「进行中」
  if (work.状态 === '暂停' || work.状态 === '已停止') return;

  if (work.具名指派.length === 0) {
    work.状态 = '待指派';
    return;
  }

  // 材料已在开工时扣过 → 不再按仓库现有量重判（否则扣完就变「待指派」，进度恒 0）
  if ((work as unknown as { 已扣料?: boolean }).已扣料) {
    work.状态 = '进行中';
    return;
  }

  // 已经开工（进度 > 0）的项同样不再降级：
  // 只有「还没开始」的项才该因为材料不足停在待指派。
  if (Number((work as unknown as { 进度?: number }).进度 ?? 0) > 0) {
    work.状态 = '进行中';
    return;
  }

  const building = buildings[work_name];
  if (building?.所需材料 && !_.isEmpty(building.所需材料)) {
    work.状态 = warehouseHasMaterials(building.所需材料, warehouse) ? '进行中' : '待指派';
    return;
  }

  const project = WORK_PROJECT_CATALOG.find(p => p.name === work_name);
  if (project) {
    const mats = parseMaterialString(project.materials);
    work.状态 = warehouseHasMaterials(mats, warehouse) ? '进行中' : '待指派';
    return;
  }

  work.状态 = '进行中';
}

export function syncAllWorkActivation(data: Schema) {
  for (const name of _.keys(data.工作队列)) {
    syncWorkActivation(name, data.工作队列, data.营地.当前建筑, data.营地.仓库储备);
  }
}
