import type { Schema } from '../../../schema';
import { extractSettlementCardsFromStory, type ParsedSettlementCard } from './settlementSync';
import { ensure_squad_return_pending_affair } from './explorationTimeProgress';
import {
  is_npc_at_camp,
  is_npc_guard_duty_task,
  is_npc_on_return_settlement,
  npc_indicates_returned_to_camp,
  npc_indicates_still_outbound,
} from './squadNpcPresence';
import { computeOutboundPlanHours } from './worldClock';

type Stat = Schema;
type Squad = Schema['探索编队'][string];
type NamedNpc = Schema['具名NPC'][string];
type SquadKind = '采集' | '狩猎' | '探索';

const OUTBOUND_STATUSES = new Set<Squad['状态']>(['探索中', '采集中', '狩猎中']);
const OUTBOUND_TASK_RE = /探索|狩猎|采集|外出|带队|搜寻|追踪|出队/;

function extractStoryFromMessage(text: string): string {
  const m = text.match(/(?:<|&lt;)story(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/story(?:>|&gt;)/i);
  return m?.[1] ?? text;
}

function getLatestAssistantStoryText(): string {
  if (typeof getChatMessages !== 'function') {
    return '';
  }
  const msgs = getChatMessages('0-{{lastMessageId}}');
  const latestAssistant = [...msgs].reverse().find(m => m.role === 'assistant');
  if (!latestAssistant) {
    return '';
  }
  return extractStoryFromMessage(latestAssistant.message);
}

function member_returned_in_story(story: string, memberName: string): boolean {
  if (!story.includes(memberName)) return false;
  const escaped = memberName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(
    `${escaped}[^。\\n]{0,120}(?:返回|归来|回到|走进|走入|走到|冲出|冲出|钻出|走了出来|拖着重|拖着沉重|领到|撤|跟随)[^。\\n]{0,80}|` +
      `(?:最先|最后|随后|终于|阴影中)[^。\\n]{0,50}${escaped}|` +
      `${escaped}[^。\\n]{0,80}火塘`,
  ).test(story);
}

function should_squad_return_from_story(squad: Squad, story: string): boolean {
  if (!story || squad.状态 === '待命' || !OUTBOUND_STATUSES.has(squad.状态)) {
    return false;
  }
  return story_indicates_squad_returned(squad, story);
}

/** 正文是否已描写该编队全部具名成员归营（不检查当前编队状态） */
export function story_indicates_squad_returned(squad: Squad, story: string): boolean {
  if (!story) return false;
  if (!/返回|归来|回到|归营|陆续|撤了回来/.test(story)) {
    return false;
  }
  if (squad.具名成员.length === 0) {
    return false;
  }
  return squad.具名成员.every(name => member_returned_in_story(story, name));
}

function squad_members_indicate_departed(stat: Stat, squad: Squad): boolean {
  if (squad.具名成员.length === 0) {
    return false;
  }
  return squad.具名成员.some(name => npc_indicates_still_outbound(stat.具名NPC[name]));
}

function repair_squad_departure(stat: Stat, squad: Squad): void {
  if (!squad.计划时长 || squad.计划时长 < 2) {
    squad.计划时长 = computeOutboundPlanHours(stat.世界.时间);
  }
  squad.出发于 = {
    生存天数: stat.世界.生存天数,
    时间: stat.世界.时间,
    兽历: stat.世界.兽历,
  };
  squad.已耗工时 = 0;
  squad.已开始计时 = false;
}

function outbound_status_for_kind(kind: SquadKind): Squad['状态'] {
  if (kind === '采集') return '采集中';
  if (kind === '狩猎') return '狩猎中';
  return '探索中';
}

function is_squad_settlement_done(stat: Stat, squadName: string): boolean {
  const affairKey = `归来清点·${squadName}`;
  // 只看「当下这件事务是否刚被结算为已完成」。
  // 不再看历史日志：否则上一趟的归档日志会让新派出的队伍在下一轮被立刻打回待命。
  return stat.综合事物[affairKey]?.状态 === '已完成';
}

function is_empty_squad(squad: Squad): boolean {
  return squad.具名成员.length === 0 && squad.无名队员数 <= 0;
}

function squad_kind_from_squad(name: string, squad: Squad): SquadKind | null {
  const nameMatch = name.match(/(?:^|·)(采集|狩猎|探索)队(?:_|$)/);
  if (nameMatch) return nameMatch[1] as SquadKind;
  if (squad.状态 === '采集中') return '采集';
  if (squad.状态 === '狩猎中') return '狩猎';
  if (squad.状态 === '探索中') return '探索';
  return null;
}

/** 已 settlement 归档的编队仍标外出时，强制改待命 */
function reconcile_settled_squads_idle(stat: Stat): boolean {
  let changed = false;
  for (const [name, squad] of Object.entries(stat.探索编队)) {
    if (!is_squad_settlement_done(stat, name)) {
      continue;
    }
    if (OUTBOUND_STATUSES.has(squad.状态) || squad.出发于) {
      mark_squad_idle(stat, name, squad, '归来清点已结算', { skipPendingAffair: true });
      changed = true;
      continue;
    }
    for (const member of squad.具名成员) {
      const npc = stat.具名NPC[member];
      if (!npc) continue;
      if (!is_npc_at_camp(npc)) {
        npc.当前位置 = '营地';
        changed = true;
      }
      if (/归来清点|待清点|外出狩猎|外出采集|带领|带队|狩猎中|采集中|探索中/.test(npc.当前任务 ?? '')) {
        npc.当前任务 = '待指派';
        changed = true;
      }
      if (npc.状态 === '外出') {
        npc.状态 = '疲惫';
        changed = true;
      }
    }
  }
  return changed;
}

/** 待命编队成员已全部外出执行任务时，按 NPC 状态补写出发记录 */
function sync_idle_squads_to_outbound(stat: Stat): boolean {
  let changed = false;
  for (const [name, squad] of Object.entries(stat.探索编队)) {
    if (squad.状态 !== '待命' || squad.出发于) {
      continue;
    }
    if (is_squad_settlement_done(stat, name)) {
      continue;
    }
    const kind = squad_kind_from_squad(name, squad);
    if (!kind || squad.具名成员.length === 0) {
      continue;
    }
    const allOutbound = squad.具名成员.every(member => {
      const npc = stat.具名NPC[member];
      if (is_npc_on_return_settlement(npc)) {
        return false;
      }
      if (!npc_indicates_still_outbound(npc)) {
        return false;
      }
      const preferred = npc_preferred_squad_kind(npc);
      return preferred === null || preferred === kind;
    });
    if (!allOutbound) {
      continue;
    }
    squad.状态 = outbound_status_for_kind(kind);
    repair_squad_departure(stat, squad);
    changed = true;
    console.info('[探索编队] 成员已外出，补写出发:', name);
  }
  return changed;
}

function mark_squad_idle(
  stat: Stat,
  squadName: string,
  squad: Squad,
  reason: string,
  options: { skipPendingAffair?: boolean } = {},
): void {
  if (squad.状态 === '待命') return;
  // 计划时长没走完就不撤销归营：回营由时间驱动（sync_exploration_squads_time）。
  // 结算卡片这类"确证已回营"的路径会传 skipPendingAffair: true，照常撤销。
  // 实机踩过：派队出发后，下一轮管线因为成员任务被 NPC 面板重写成「待指派」，
  // 立刻把编队判成"成员已归营"打回待命，玩家的操作等于没发生。
  const planRunning =
    Boolean(squad.出发于) && squad.计划时长 > 0 && squad.已耗工时 < squad.计划时长;
  if (planRunning && !options.skipPendingAffair) {
    console.info('[探索编队] 计划未走完，忽略归营:', squadName, reason);
    return;
  }
  if (!squad.出发于) {
    squad.状态 = '待命';
    squad.已耗工时 = 0;
    squad.已开始计时 = false;
    console.info('[探索编队]', reason, '→ 未出发，改待命:', squadName);
    return;
  }
  if (!options.skipPendingAffair) {
    ensure_squad_return_pending_affair(stat, squadName, squad);
  }
  squad.状态 = '待命';
  squad.已耗工时 = 0;
  squad.已开始计时 = false;
  delete squad.出发于;
  // 审核 P1：归队后清空本次派遣，避免下一轮读到过期档位
  delete (squad as unknown as { 本次派遣?: unknown }).本次派遣;
  for (const name of squad.具名成员) {
    const npc = stat.具名NPC[name];
    if (!npc) continue;
    npc.当前位置 = '营地';
    if (!options.skipPendingAffair) {
      if (OUTBOUND_TASK_RE.test(npc.当前任务 ?? '') && !/清点|献宝|上交/.test(npc.当前任务 ?? '')) {
        npc.当前任务 = '归来清点';
      }
    } else if (/归来清点|待清点|外出|带领|带队|狩猎中|采集中|探索中/.test(npc.当前任务 ?? '')) {
      npc.当前任务 = '待指派';
    }
    if (npc.状态 === '外出') {
      npc.状态 = '疲惫';
    }
  }
  console.info('[探索编队]', reason, '→ 待命:', squadName);
}

/** AI 未把「探索中」改回「待命」时，据具名成员位置/状态推断是否已归营 */
export function should_squad_return_idle(squad: Squad, stat: Stat): boolean {
  if (squad.状态 === '待命' || !OUTBOUND_STATUSES.has(squad.状态)) return false;
  // 计划时长没走完就别归营：编队的"回营"由时间驱动（sync_exploration_squads_time），
  // 不能因为 NPC 面板把成员任务写成「待指派」（每次管线重跑都会重写一次）就当场撤销出发。
  // 实机踩过：玩家点了出发、编队已采集中，下一轮管线被这句判成"成员已归营"打回待命。
  if (squad.出发于 && squad.计划时长 > 0 && squad.已耗工时 < squad.计划时长) return false;
  if (is_empty_squad(squad)) return true;

  const named = squad.具名成员;
  if (named.length === 0) {
    return false;
  }

  if (named.every(name => is_npc_on_return_settlement(stat.具名NPC[name]))) {
    return true;
  }

  if (named.some(name => npc_indicates_still_outbound(stat.具名NPC[name]))) {
    return false;
  }
  return named.every(name => npc_indicates_returned_to_camp(stat.具名NPC[name]));
}

function find_settlement_squad(stat: Stat, card: ParsedSettlementCard): [string, Squad] | null {
  if (card.kind === '工作') {
    return null;
  }
  const kind = card.kind;
  const participants = (card.participants ?? []).filter(name => stat.具名NPC[name]);

  let best: [string, Squad] | null = null;
  let bestScore = 0;
  for (const [name, squad] of Object.entries(stat.探索编队)) {
    if (!OUTBOUND_STATUSES.has(squad.状态)) {
      continue;
    }
    if (squad_kind_from_squad(name, squad) !== kind) {
      continue;
    }
    const score =
      participants.length === 0 ? 1 : participants.filter(p => squad.具名成员.includes(p)).length;
    if (score > bestScore) {
      bestScore = score;
      best = [name, squad];
    }
  }
  if (best && bestScore > 0) {
    return best;
  }

  const outboundOfKind = Object.entries(stat.探索编队).filter(
    ([name, squad]) =>
      OUTBOUND_STATUSES.has(squad.状态) && squad_kind_from_squad(name, squad) === kind,
  );
  if (outboundOfKind.length === 1) {
    return outboundOfKind[0];
  }
  return null;
}

/** settlement_card 已结算时，将匹配的已有外出编队改待命（不新建、不改 roster） */
export function sync_squads_from_settlement_cards(
  stat: Stat,
  story: string,
  messageText = '',
): boolean {
  const source = messageText.trim() || story.trim();
  const cards = extractSettlementCardsFromStory(source);
  if (cards.length === 0) {
    return false;
  }

  let changed = false;
  for (const card of cards) {
    const match = find_settlement_squad(stat, card);
    if (!match) {
      continue;
    }
    const [name, squad] = match;
    if (OUTBOUND_STATUSES.has(squad.状态)) {
      mark_squad_idle(stat, name, squad, 'settlement_card 已结算', { skipPendingAffair: true });
      changed = true;
    }
  }
  return changed;
}

/**
 * 按聊天记录回放 settlement_card，校正已有编队的归营状态。
 *
 * **只回放"这一轮"的卡**（最新 assistant 楼层）。原来是把 0~max 的全部历史卡都回放一遍，
 * 结果实机出大问题：只要历史里存在过一张 `[编队|采集队]` 的卡，之后**每次新建的采集队**
 * 都会在下一轮管线里被判定成"已结算"、当场打回待命 —— 派队永远出发不了
 * （二分定位：只开 settle 这一步就能复现；关掉它就正常）。
 * 编队的真实状态由 `状态/出发于/已耗工时` 自己记着，历史卡不需要反复重放。
 */
export function sync_squads_from_settlement_chat_history(stat: Stat, maxMessageId: number): boolean {
  if (typeof getChatMessages !== 'function' || maxMessageId < 0) {
    return false;
  }
  let latest: { message: string } | undefined;
  try {
    latest = getChatMessages(-1, { role: 'assistant' })[0];
  } catch {
    latest = undefined;
  }
  if (!latest) {
    return false;
  }
  const story = extractStoryFromMessage(latest.message);
  return sync_squads_from_settlement_cards(stat, story, latest.message);
}

/** 最新 AI 正文已描写全队归来，但变量未 patch 时同步为待命 */
export function sync_squads_from_return_story(stat: Stat): boolean {
  const story = getLatestAssistantStoryText();
  if (!story) return false;
  let changed = false;
  for (const [name, squad] of Object.entries(stat.探索编队)) {
    if (should_squad_return_from_story(squad, story)) {
      mark_squad_idle(stat, name, squad, '剧情已描写归来');
      changed = true;
    }
  }
  return changed;
}

/** 校正已有编队的外出/归营生命周期（不创建、不改 roster） */
export function reconcile_exploration_squads(stat: Stat): boolean {
  let changed = false;
  const squads = stat.探索编队;

  if (reconcile_settled_squads_idle(stat)) {
    changed = true;
  }

  if (sync_idle_squads_to_outbound(stat)) {
    changed = true;
  }

  for (const [name, squad] of Object.entries(squads)) {
    if (OUTBOUND_STATUSES.has(squad.状态) && !squad.出发于) {
      if (squad_members_indicate_departed(stat, squad)) {
        repair_squad_departure(stat, squad);
        changed = true;
        console.info('[探索编队] 变量已标外出但缺出发于，已补写:', name);
      } else {
        squad.状态 = '待命';
        squad.已耗工时 = 0;
        squad.已开始计时 = false;
        changed = true;
        console.info('[探索编队] 未通过 UI 出发，改待命:', name);
      }
    }
  }

  for (const [name, squad] of Object.entries(squads)) {
    if (squad.状态 !== '待命' && should_squad_return_idle(squad, stat)) {
      mark_squad_idle(stat, name, squad, '成员已归营');
      changed = true;
    }
  }

  for (const [name, squad] of Object.entries(squads)) {
    if (squad.状态 === '待命') continue;
    const kind = squad_kind_from_squad(name, squad);
    if (!kind) continue;
    const expected: Squad['状态'] =
      kind === '采集' ? '采集中' : kind === '狩猎' ? '狩猎中' : '探索中';
    if (squad.状态 !== expected) {
      squad.状态 = expected;
      changed = true;
      console.info('[探索编队] 按队名校正状态:', name, '→', expected);
    }
  }

  return changed;
}

/** 据 NPC 当前任务判断应属哪类外出编队；留守/巡逻返回 null */
export function npc_preferred_squad_kind(npc: NamedNpc | undefined): SquadKind | null {
  if (!npc) return null;
  const task = (npc.当前任务 ?? '').trim();
  if (!task || task === '待指派' || is_npc_guard_duty_task(task)) {
    return null;
  }
  if (/巡逻/.test(task) && !/外出/.test(task)) {
    return null;
  }
  if (/带领采集|外出采集|采集中|采集队|^采集$/.test(task)) return '采集';
  if (/带领狩猎|外出狩猎|狩猎中|狩猎队|^狩猎$/.test(task)) return '狩猎';
  if (/带领探索|外出探索|探索中|探索队|^探索$/.test(task)) return '探索';
  return null;
}

/** 外出编队具名成员不可重复占用多支队伍 */
export function reconcile_squad_member_exclusivity(stat: Stat): boolean {
  let changed = false;
  const squads = stat.探索编队;

  for (const [squadName, squad] of Object.entries(squads)) {
    if (!OUTBOUND_STATUSES.has(squad.状态)) {
      continue;
    }

    for (const member of [...squad.具名成员]) {
      const npc = stat.具名NPC[member];
      if (npc_indicates_still_outbound(npc)) {
        continue;
      }
      if (!npc_indicates_returned_to_camp(npc)) {
        continue;
      }
      if (is_npc_on_return_settlement(npc)) {
        continue;
      }
      squad.具名成员 = squad.具名成员.filter(m => m !== member);
      changed = true;
      console.info('[探索编队] 外出队成员已归营，移除:', member, '←', squadName);
    }
  }

  const memberSquads = new Map<string, string[]>();
  for (const [squadName, squad] of Object.entries(squads)) {
    if (!OUTBOUND_STATUSES.has(squad.状态)) {
      continue;
    }
    for (const member of squad.具名成员) {
      const list = memberSquads.get(member) ?? [];
      list.push(squadName);
      memberSquads.set(member, list);
    }
  }

  for (const [member, squadNames] of memberSquads) {
    if (squadNames.length <= 1) continue;
    const keep = squadNames[0];
    for (const sn of squadNames) {
      if (sn === keep) continue;
      const squad = squads[sn];
      if (squad.具名成员.includes(member)) {
        squad.具名成员 = squad.具名成员.filter(m => m !== member);
        changed = true;
        console.info('[探索编队] 具名成员不可重复，从', sn, '移除', member);
      }
    }
  }

  return changed;
}

/** 出发时同步更新具名成员的外出状态 */
export function mark_squad_members_departed(
  stat: Stat,
  squad: Squad,
  mode: '探索' | '狩猎' | '采集',
  target_area: string,
): void {
  const task_label =
    mode === '探索' ? `探索：${target_area}` : mode === '狩猎' ? `外出狩猎：${target_area}` : `外出采集：${target_area}`;
  for (const name of squad.具名成员) {
    const npc = stat.具名NPC[name];
    if (!npc) continue;
    npc.当前任务 = task_label;
    npc.当前位置 = target_area;
    npc.状态 = '外出';
  }
}
