import { TIME, CONSUME, BUILD, EVENTS, POPULATION, foodDaysScore, } from './table';
import { apply_decay, consume_rations, route_overflow, vanish_temporary } from './warehouse';
import { sync_work_queue_hours } from '../界面/状态栏/util/workQueueProgress';
import { sync_exploration_squads_time } from '../界面/状态栏/util/explorationTimeProgress';
import { settle_days_since_last } from './dailySettle';
// ---------- 工具 ----------
function parseClock(t) {
    const m = /^(\d{1,2}):(\d{2})$/.exec(String(t).trim());
    if (!m)
        return 8 * 60;
    return Math.min(23, Number(m[1])) * 60 + Math.min(59, Number(m[2]));
}
function clockFromMinutes(total) {
    const t = ((total % 1440) + 1440) % 1440;
    return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0');
}
const clamp01 = (v) => Math.max(0, Math.min(100, v));
export function tick_of(stat) {
    return {
        生存天数: Number(stat.世界.生存天数 ?? 1),
        时间: String(stat.世界.时间 ?? '18:00'),
    };
}
/**
 * 单调时钟差（小时）。
 * 回拨一律 0（D8 时间不可倒退），**不做**"同一天时钟变小就补 24h"那种猜测 ——
 * 那会把 19:40 → 19:00 当成 23h20m 烧掉一整天的柴和粮。
 */
export function elapsed_hours(prev, curr) {
    if (!(curr.生存天数 >= prev.生存天数))
        return 0;
    const day_delta = curr.生存天数 - prev.生存天数;
    const minutes = day_delta * 1440 + (parseClock(curr.时间) - parseClock(prev.时间));
    return minutes > 0 ? minutes / 60 : 0;
}
/** 燃料日耗（有石砌防风火塘则 4，否则 10） */
export function dailyFuelBurn(buildings) {
    const has = Object.keys(buildings ?? {}).some(k => /防风火塘/.test(k) || (/石砌/.test(k) && /火塘/.test(k)));
    return has ? CONSUME.FUEL_PER_DAY.石砌防风火塘 : CONSUME.FUEL_PER_DAY.露天;
}
/** 库存单位 → 标准配额 */
export function unitsToRation(units) {
    let sum = 0;
    for (const [k, v] of Object.entries(units)) {
        const f = CONSUME.UNIT_TO_RATION[k];
        sum += f ? v / f : 0;
    }
    return sum;
}
/** 单格上限（A2 品级 + 特例覆盖）—— 定义在 table.ts，此处仅转发以保持既有引用 */
export { capOf } from './table';
/** 结算体：第 2 步以后全部在这里，`advance` 与 `settle_time` 共用，杜绝两套算法 */
function settle_subsystems(stat, hours, options, events, mk) {
    const with_stock = options.仓储 !== false;
    const reserves = stat.营地.仓库储备;
    // ---------- 2) 篝火燃料 ----------
    const burn = dailyFuelBurn(stat.营地.当前建筑) * (hours / 24);
    const fuelBefore = stat.营地.篝火燃料.当前 ?? 0;
    stat.营地.篝火燃料.当前 = Math.max(0, fuelBefore - burn);
    if (fuelBefore > 0 && stat.营地.篝火燃料.当前 === 0) {
        events.push(mk('must', 'fuel.out', '篝火熄灭了'));
    }
    // ---------- 3) 口粮消耗（整数扣，小数进欠账） ----------
    if (with_stock) {
        // 营地.人口 只统计部落成员，**不含主角**（驾驶员 2026-10-24 定）；
        // 主角自己也吃饭，所以摄取份数 = 人口 + 1
        const eaters = (stat.营地.人口 ?? 0) + 1;
        const need = eaters * CONSUME.RATION_PER_PERSON_PER_DAY * (hours / 24);
        const camp = stat.营地;
        const carry = Number(camp.__食物消耗欠账 ?? 0);
        const toEat = Math.floor(carry + need);
        camp.__食物消耗欠账 = carry + need - toEat;
        if (toEat > 0) {
            const { missing } = consume_rations(reserves, toEat);
            if (missing > 0.01) {
                events.push(mk('must', 'food.short', '存粮见底，族人挨饿'));
            }
        }
    }
    // ---------- 4) 工作队列（建造/学习/研发/生产 全走这里）----------
    // 实现见 workQueueProgress：区分 状态/具名指派，进度按 0~100，完工走「交付清点」流程。
    if (hours > 0) {
        sync_work_queue_hours(stat, hours);
    }
    // ---------- 5) 探索编队进行中 ----------
    // 实现见 explorationTimeProgress：只推进已出发的编队，到点归营并建「归来清点」。
    if (hours > 0) {
        sync_exploration_squads_time(stat, hours);
    }
    // ---------- 6) 建筑阶段 ----------
    for (const [name, b] of Object.entries(stat.营地.当前建筑 ?? {})) {
        if (b?.建筑阶段 === '蓝图') {
            b.建筑阶段 = '建造中';
            events.push(mk('may', 'build.started', `${name} 开工`));
        }
    }
    // ---------- 7) 怀孕 / 幼崽（规则待补，先占位不写） ----------
    // ---------- 8) 腐坏（A6）+ 临时仓消散（A7）----------
    if (with_stock) {
        const decayed = apply_decay(reserves, hours, true, decay_factor_for(stat));
        if (decayed >= 1) {
            events.push(mk('may', 'stock.decay', `仓储腐坏 ${Math.round(decayed)} 单位`));
        }
        const vanished = vanish_temporary(stat.营地.临时仓, hours);
        if (vanished >= 1) {
            events.push(mk('may', 'temp.vanish', `临时仓消散 ${Math.round(vanished)} 单位`));
        }
        // ---------- 9) 溢出 → 临时仓（A7）----------
        const overflowed = route_overflow(stat);
        if (overflowed > 0) {
            events.push(mk('may', 'storage.overflow', `超出仓储上限 ${Math.round(overflowed)} 单位转入临时仓，会很快消失`));
        }
    }
    // ---------- 9) 每日结算（跨午夜）：伤病恢复 + 被动产出 ----------
    {
        const daily = settle_days_since_last(stat);
        if (daily.days > 0) {
            for (const name of daily.recovered) {
                events.push(mk('may', 'injury.recover', `${name} 的伤好了`));
            }
            for (const line of daily.produced) {
                events.push(mk('silent', 'passive.output', line));
            }
        }
    }
    // ---------- 指标收口（派生 = clamp(基准 + 修正)）----------
    const m = stat.营地.生存指标;
    m.温饱度 = clamp01((m.温饱度_基准 ?? 0) + (m.温饱度_修正 ?? 0));
    m.栖居度 = clamp01((m.栖居度_基准 ?? 0) + (m.栖居度_修正 ?? 0));
    stat.营地.向心力 = clamp01((stat.营地.向心力_基准 ?? 0) + (stat.营地.向心力_修正 ?? 0));
}
/**
 * 世界时间推进 —— 命令/结算器入口：把时钟推 Δt，然后结算九个子系统。
 * 纯函数：不读写 MVU、不碰 UI、不调模型。只做 stat 内的确定性演算。
 */
export function advance(stat, hours, options = {}) {
    const events = [];
    // D9：seq 在本次调用内从 1 开始自增（不放模块级），否则同一输入两次调用结果不同，不可重放
    let seq = 0;
    const mk = (level, verb, text) => ({ seq: (seq += 1), at: `${stat.世界.兽历} ${stat.世界.时间}`, level, verb, text, source: 'tick' });
    if (!Number.isFinite(hours) || hours < 0) {
        return { ok: false, hours: 0, day_rollovers: 0, events, reasons: 'Δt 必须是非负数' };
    }
    if (hours > TIME.MAX_ADVANCE_HOURS) {
        return { ok: false, hours, day_rollovers: 0, events, reasons: `单次推进 ${hours}h 超过上限 ${TIME.MAX_ADVANCE_HOURS}h，需拆分或玩家确认` };
    }
    if (hours === 0) {
        return { ok: true, hours: 0, day_rollovers: 0, events };
    }
    // ---------- 1) 世界时间 / 兽历 / 生存天数 ----------
    const startMin = parseClock(stat.世界.时间);
    const endMin = startMin + Math.round(hours * 60);
    const dayRollovers = Math.floor(endMin / 1440);
    stat.世界.时间 = clockFromMinutes(endMin);
    if (dayRollovers > 0) {
        stat.世界.生存天数 = (stat.世界.生存天数 ?? 1) + dayRollovers;
        // 日期（兽历）也必须跟着走，否则会出现"第 3 天 · 9月1日"这种自相矛盾
        stat.世界.兽历 = shift_world_date(stat.世界.兽历, dayRollovers);
        const cubs = stat.幼崽;
        if (cubs && typeof cubs === 'object') {
            for (const cub of Object.values(cubs)) {
                if (!cub)
                    continue;
                cub.年龄 = (Number(cub.年龄 ?? 0) || 0) + dayRollovers;
            }
        }
        events.push(mk('silent', 'day.passed', `过去 ${dayRollovers} 天`));
    }
    // 水印跟着时钟走：否则实时 tick 会把这一段再结算一遍
    stat.世界.已结算 = { ...tick_of(stat), 兽历: stat.世界.兽历 };
    settle_subsystems(stat, hours, options, events, mk);
    return { ok: true, hours, day_rollovers: dayRollovers, events };
}
/** a 是否早于 b（同一套"天 + 分钟"比较） */
function is_before(a, b) {
    if (a.生存天数 !== b.生存天数)
        return a.生存天数 < b.生存天数;
    return parseClock(a.时间) < parseClock(b.时间);
}
/**
 * 把「兽历」字符串往后推 N 天。
 * 支持 `1年9月1日` / `1年9月1日 周三` 这类写法；解析不了就原样返回。
 */
export function shift_world_date(兽历, days) {
    if (!days)
        return 兽历;
    const m = String(兽历 ?? '').match(/(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日?/);
    if (!m)
        return 兽历;
    const [all, y, mo, d] = m;
    const date = new Date(Number(y), Number(mo) - 1, Number(d));
    if (Number.isNaN(date.getTime()))
        return 兽历;
    date.setDate(date.getDate() + days);
    const next = `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
    // 保留原字符串里的附加部分（如星期），只替换日期本体
    return String(兽历).replace(all, next);
}
/**
 * 实时管线唯一时间入口：结算「水印 → 当前世界时间」的差额。
 *
 * 模型已经把 `世界.时间` 写走了（P5 之前它仍有这个写权），这里不推时钟、只补结算，
 * 然后把水印推到当前时间。这样：
 *   - 一次加载跑 1~3 遍、reload 再跑，都不会重复扣燃料/口粮；
 *   - **时钟被写回拨时不再只是"Δt=0"，而是把世界时间按水印回正**（D8 单调不减）：
 *     否则水印会永久领先，之后每一轮都被判成回拨，整个时间轴死锁（实机踩过：
 *     模型把 6日22:30 写成 2日07:40）；
 *   - 单次跨度超过 12h 时按 D8 分片结算，不丢时间也不一次跳完。
 */
export function settle_time(stat, options = {}) {
    const curr = tick_of(stat);
    const mark = stat.世界.已结算;
    if (!mark) {
        // 旧档 / 首轮：只对齐水印，不补算历史（否则会一次性烧掉几天的柴和粮）
        stat.世界.已结算 = { ...curr, 兽历: stat.世界.兽历 };
        return { hours: 0, day_rollovers: 0, prev: curr, curr, events: [] };
    }
    const prev = { 生存天数: Number(mark.生存天数 ?? 1), 时间: String(mark.时间 ?? '18:00') };
    const events = [];
    let seq = 0;
    const mk = (level, verb, text) => ({ seq: (seq += 1), at: `${stat.世界.兽历} ${stat.世界.时间}`, level, verb, text, source: 'tick' });
    if (is_before(curr, prev)) {
        // 模型很常见的写法：只把时间改成"次日早晨"（21:25 → 08:00），忘了给 生存天数 +1。
        // 同一天里倒退超过 8 小时，按"跨日"解释（天数 +1），而不是当成回拨把时间拉回去。
        const dropped = parseClock(prev.时间) - parseClock(curr.时间);
        if (curr.生存天数 === prev.生存天数 && dropped > 8 * 60) {
            curr.生存天数 = prev.生存天数 + 1;
            stat.世界.生存天数 = curr.生存天数;
        }
        else {
            // 真回拨：拒绝，并把世界时钟拉回上一结算点
            stat.世界.时间 = prev.时间;
            stat.世界.生存天数 = prev.生存天数;
            events.push(mk('must', 'time.rewind', `时间不能倒流：已按上一结算点 ${prev.生存天数}日${prev.时间} 回正`));
            return { hours: 0, day_rollovers: 0, prev, curr: prev, events, rewound: true };
        }
    }
    let remaining = elapsed_hours(prev, curr);
    const day_rollovers = Math.max(0, curr.生存天数 - prev.生存天数);
    // __calendar_sync：兽历只在模型**没有**推进时才由管线补，避免双写（实机：第2天却显示9月3日）
    if (day_rollovers > 0) {
        const prev_calendar = String(mark.兽历 ?? '');
        const curr_calendar = String(stat.世界.兽历 ?? '');
        if (!curr_calendar || curr_calendar === prev_calendar) {
            stat.世界.兽历 = shift_world_date(stat.世界.兽历, day_rollovers);
        }
    }
    if (!(remaining > 0)) {
        return { hours: 0, day_rollovers, prev, curr, events };
    }
    const total = remaining;
    if (total > TIME.MAX_ADVANCE_HOURS) {
        // D8：单轮建议 ≤12h。这里不拒绝（时间必须走过去），但要留痕，
        // 让 UI / 日志能看出"这一轮模型一次跳了多久"。
        events.push(mk('may', 'time.jump', `一次推进 ${total.toFixed(1)}h，超过单轮建议上限 ${TIME.MAX_ADVANCE_HOURS}h`));
    }
    while (remaining > 1e-9) {
        const step = Math.min(remaining, TIME.MAX_ADVANCE_HOURS);
        settle_subsystems(stat, step, options, events, mk);
        remaining -= step;
    }
    stat.世界.已结算 = { ...curr, 兽历: stat.世界.兽历 };
    return { hours: total, day_rollovers, prev, curr, events };
}
/** "推进到下一个事件"：返回距今最近事件的 Δt（小时，已按上限裁剪） */
export function hoursToNextEvent(stat) {
    const now = parseClock(stat.世界.时间);
    let best = { hours: Infinity, what: '' };
    const consider = (h, what) => { if (h > 0 && h < best.hours)
        best = { hours: h, what }; };
    for (const [name, s] of Object.entries(stat.探索编队 ?? {})) {
        if (!s)
            continue;
        consider(Math.max(0, (s.计划时长 ?? 0) - (s.已耗工时 ?? 0)), `${name} 到点归营`);
    }
    for (const [name, q] of Object.entries(stat.工作队列 ?? {})) {
        if (!q || q.状态 === '已停止')
            continue;
        consider(Math.max(0, (q.所需工时 ?? 0) - (q.进度 ?? 0)), `${name} 完工`);
    }
    const 天黑 = (18 * 60 - now) / 60;
    consider(天黑, '天黑');
    if (!Number.isFinite(best.hours))
        best = { hours: 4, what: '下一个时段' };
    const capped = Math.min(best.hours, TIME.MAX_ADVANCE_HOURS);
    return { hours: Math.max(0.25, Math.round(capped * 4) / 4), what: best.what };
}
export { foodDaysScore, BUILD, EVENTS, POPULATION, TIME };
/**
 * 腐坏系数：由「已建成」的储存类建筑决定（世界书面子里的"可长期保存"）。
 * 地窖/冷藏 → 0（完全不腐坏）；烟熏/风干房 → 0.5；普通储存架 → 0.7。
 * 功能标签缺失时按建筑名关键词兜底，旧档也能用。
 */
export function decay_factor_for(stat) {
    const buildings = stat.营地?.当前建筑 ?? {};
    const PAT = {
        储存: /储|架|仓|库/,
        干燥: /烟熏|风干|晒|烘/,
        冷藏: /冰|窖/,
    };
    let factor = 1;
    for (const [name, b] of Object.entries(buildings)) {
        if (!b || b.建筑阶段 !== '已建成')
            continue;
        const tags = Array.isArray(b.功能标签) ? b.功能标签 : [];
        const hit = (tag) => (tags.length ? tags.includes(tag) : (PAT[tag] ?? /x^/).test(name));
        if (hit('冷藏'))
            return 0;
        if (hit('干燥'))
            factor = Math.min(factor, 0.5);
        else if (hit('储存'))
            factor = Math.min(factor, 0.7);
    }
    return factor;
}
