/** settlement_card / JSONPatch 等使用的方括号字段名，不可当作 NPC 名 */
export const SETTLEMENT_BRACKET_LABELS = new Set([
  '类型',
  '品质',
  '标题',
  '副标题',
  '参与',
  '参与人员',
  '说明',
  '结算对象',
  '结算事项',
  '获取物资',
  '消耗状况',
  '事件描述',
  '消耗',
  '产出',
  '状态',
  '情报带回',
  '时间消耗',
  '队伍状态',
  '编队',
  '物资获取',
  '参与',
]);

/** npc_panel 方括号字段名，不可当作 NPC 名（如 [档位|入门]） */
export const NPC_PANEL_BRACKET_LABELS = new Set([
  '姓名',
  '种族',
  '档位',
  '饱食度',
  '好感度',
  '技能',
  '行为',
  '动作',
  '表情',
  '心里话',
]);

const NPC_GRADE_VALUES = new Set(['生疏', '入门', '熟练', '精通', '大师', '传说', '初学']);

export function is_settlement_bracket_label(label: string): boolean {
  return SETTLEMENT_BRACKET_LABELS.has(label.trim());
}

export function is_npc_panel_bracket_label(label: string): boolean {
  return NPC_PANEL_BRACKET_LABELS.has(label.trim());
}

export function is_bracket_field_label(label: string): boolean {
  const trimmed = label.trim();
  return is_settlement_bracket_label(trimmed) || is_npc_panel_bracket_label(trimmed);
}

export function is_npc_grade_value(value: string): boolean {
  return NPC_GRADE_VALUES.has(value.trim());
}
