import type { Schema } from '../../../schema';
import { WORK_PROJECT_CATALOG } from '../constants/workProjectCatalog';
import {
  extractSettlementCardsFromStory,
  extractStoryFromMessage,
  type ParsedSettlementCard,
} from './settlementSync';
import { unlockOneTimeWorkProject } from './workProjectStatus';

/** 从 settlement_card 副标题/标题解析工作队列项目名（如「纤维与编织研发」→「纤维与编织」） */
export function resolve_work_project_name_from_card(card: ParsedSettlementCard): string | null {
  if (card.kind !== '工作') {
    return null;
  }
  const blob = `${card.subtitle ?? ''}${card.target ?? ''}`;
  for (const project of WORK_PROJECT_CATALOG) {
    if (blob.includes(project.name)) {
      return project.name;
    }
  }
  const stripped = blob.replace(/[^\u4e00-\u9fff·、与编]+/g, ' ').trim();
  for (const project of WORK_PROJECT_CATALOG) {
    if (stripped.includes(project.name)) {
      return project.name;
    }
  }
  return null;
}

function remove_work_queue_aliases(stat: Schema, project_name: string): boolean {
  let changed = false;
  for (const key of [...Object.keys(stat.工作队列)]) {
    if (key === project_name || key.startsWith(`${project_name}研发`) || key.startsWith(`${project_name}·`)) {
      delete stat.工作队列[key];
      changed = true;
    }
  }
  return changed;
}

/** settlement_card [类型|工作] 已结算 → 移除工作队列项、解锁研发/学习、完成交付清点 */
export function sync_work_queue_from_settlement_cards(stat: Schema, cards: ParsedSettlementCard[]): boolean {
  let changed = false;
  for (const card of cards) {
    if (card.kind !== '工作') {
      continue;
    }
    const project_name = resolve_work_project_name_from_card(card);
    if (!project_name) {
      continue;
    }

    const work = stat.工作队列[project_name];
    const work_type = work?.类型 ?? '研发';

    let card_changed = false;

    if (remove_work_queue_aliases(stat, project_name)) {
      card_changed = true;
    }

    if (!stat.已解锁科技.includes(project_name)) {
      unlockOneTimeWorkProject(stat, project_name, work_type);
      card_changed = true;
    }

    const affair_key = `交付清点·${project_name}`;
    const affair = stat.综合事物[affair_key];
    if (affair && affair.状态 !== '已完成') {
      affair.状态 = '已完成';
      card_changed = true;
    }

    if (stat.世界.当前研发 === project_name) {
      stat.世界.当前研发 = '无';
      stat.世界.研发进度 = 0;
      card_changed = true;
    }

    if (card_changed) {
      changed = true;
      console.info('[工作队列] settlement_card 已结算:', project_name);
    }
  }
  return changed;
}

/** 按聊天记录回放工作类 settlement_card */
export function sync_work_queue_from_settlement_chat_history(stat: Schema, maxMessageId: number): boolean {
  if (typeof getChatMessages !== 'function' || maxMessageId < 0) {
    return false;
  }
  let changed = false;
  const msgs = getChatMessages(`0-${maxMessageId}`).filter(m => m.role === 'assistant');
  for (const msg of msgs) {
    const story = extractStoryFromMessage(msg.message);
    const source = msg.message.trim() || story.trim();
    const cards = extractSettlementCardsFromStory(source);
    changed = sync_work_queue_from_settlement_cards(stat, cards) || changed;
  }
  return changed;
}

/** JSONPatch 误写「纤维与编织研发」等别名时，映射到 catalog 项目名并 remove */
export function repair_work_queue_removes_from_message(stat: Schema, messageText: string): boolean {
  if (!messageText) {
    return false;
  }
  let changed = false;
  for (const patch of extractJsonPatchesFromMessage(messageText)) {
    if (patch.op !== 'remove' || !patch.path?.startsWith('/工作队列/')) {
      continue;
    }
    const raw = patch.path.replace(/^\/工作队列\//, '').replace(/~1/g, '/').replace(/~0/g, '~');
    const project = WORK_PROJECT_CATALOG.find(p => raw === p.name || raw.startsWith(p.name))?.name;
    if (!project) {
      continue;
    }
    if (remove_work_queue_aliases(stat, project)) {
      changed = true;
    }
    if (!stat.已解锁科技.includes(project)) {
      unlockOneTimeWorkProject(stat, project, stat.工作队列[project]?.类型 ?? '研发');
      changed = true;
    }
    if (stat.世界.当前研发 === project) {
      stat.世界.当前研发 = '无';
      stat.世界.研发进度 = 0;
      changed = true;
    }
  }
  return changed;
}

function extractJsonPatchesFromMessage(text: string): Array<{ op?: string; path?: string }> {
  const block = text.match(/(?:<|&lt;)JSONPatch(?:>|&gt;)([\s\S]*?)(?:<|&lt;)\/JSONPatch(?:>|&gt;)/i);
  if (!block?.[1]) {
    return [];
  }
  try {
    const parsed = JSON.parse(block[1].trim());
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}
