const SLOT_META_BY_NAME = new Map<string, WarehouseSlotMeta>();

function register_catalog(): void {
  for (const [top, subs] of Object.entries(WAREHOUSE_CATALOG) as [
    WarehouseTopCategory,
    Record<string, readonly string[]>,
  ][]) {
    for (const [sub, names] of Object.entries(subs)) {
      for (const name of names) {
        if (!SLOT_META_BY_NAME.has(name)) {
          SLOT_META_BY_NAME.set(name, {
            top,
            sub,
            defaultCap: GRADE_DEFAULT_CAP[material_grade_for(name)],
          });
        }
      }
    }
  }
}
register_catalog();

/** 资源别名 → 仓库标准键（与 settlement 同步一致） */
export const WAREHOUSE_ITEM_ALIASES: Record<string, string> = {
  生藤蔓: '藤蔓',
  止血草: '止血草药', // 世界书用简称，仓库目录用全称
    护胃草: '护胃草药',
    驱寒草: '驱寒草药',
    肉类罐头: '罐头',
  营养罐头: '营养肉罐头',
};

export function normalize_warehouse_item_name(name: string): string {
  const trimmed = name.trim();
  return WAREHOUSE_ITEM_ALIASES[trimmed] ?? trimmed;
}

function infer_warehouse_slot_meta(name: string): WarehouseSlotMeta {
  const n = normalize_warehouse_item_name(name);
  if (/方便面|罐头|能量棒|口粮|蛋白棒|压缩饼干/.test(n)) {
    return { top: '食物', sub: '应急口粮', defaultCap: 200, hint: '长期保存的应急食品' };
  }
  if (/熏|风干|熟肉|烤肉|肉条/.test(n)) {
    return { top: '食物', sub: '熟食与保存', defaultCap: GRADE_DEFAULT_CAP[material_grade_for(name)] };
  }
  if (/生肉|块茎|野果|浆果|菌|果/.test(n)) {
    return { top: '食物', sub: '生食', defaultCap: 200 };
  }
  if (/草药|敷剂|草汁|草汤|草糊/.test(n)) {
    return n.includes('糊') || n.includes('敷') || n.includes('汤') || n.includes('汁')
      ? { top: '医疗', sub: '成药敷剂', defaultCap: GRADE_DEFAULT_CAP[material_grade_for(name)] }
      : { top: '医疗', sub: '草药原料', defaultCap: GRADE_DEFAULT_CAP[material_grade_for(name)] };
  }
  if (/矛|枪|斧|棒|叉|镖|刀|陷阱|索|针|袋|篓|衣|网|陶|夹板/.test(n)) {
    return { top: '工具与装备', sub: '工具', defaultCap: 50 };
  }
  if (/异星|坠毁|星痕|迫降|能源块|发光矿/.test(n)) {
    return { top: '珍异储备', sub: '异星遗存', defaultCap: 10 };
  }
  if (/木炭|燧石|骨骼|兽脂|过滤/.test(n)) {
    return { top: '材料', sub: '加工材料', defaultCap: GRADE_DEFAULT_CAP[material_grade_for(n)] };
  }
  if (/兽皮|皮甲|藤绳|绳/.test(n)) {
    return { top: '材料', sub: '纤维与皮革', defaultCap: GRADE_DEFAULT_CAP[material_grade_for(name)] };
  }
  if (/木柴|引火|干草|杂草|枯叶/.test(n)) {
    return { top: '燃料', sub: '引火杂薪', defaultCap: 200 };
  }
  if (/木柴|炭/.test(n) && !/普通/.test(n)) {
    return { top: '燃料', sub: '主燃料', defaultCap: 200 };
  }
  return {
    top: '材料',
    sub: '原材料',
    defaultCap: GRADE_DEFAULT_CAP[material_grade_for(n)],
    hint: '未在目录登记的资源',
  };
}

export function warehouse_slot_meta(name: string): WarehouseSlotMeta {
  const normalized = normalize_warehouse_item_name(name);
  return SLOT_META_BY_NAME.get(normalized) ?? infer_warehouse_slot_meta(normalized);
}

export function default_warehouse_cap(name: string): number {
  return warehouse_slot_meta(name).defaultCap;
}

export type WarehouseDisplayItem = {
  name: string;
  当前: number;
  上限: number;
  grade: MaterialGrade;
  top: WarehouseTopCategory;
  sub: string;
};

export type WarehouseSubsection = {
  sub: string;
  items: WarehouseDisplayItem[];
};

export type WarehouseSection = {
  top: WarehouseTopCategory;
  subsections: WarehouseSubsection[];
  totalQty: number;
};

export function group_warehouse_reserves(
  reserves: Record<string, { 当前: number; 上限: number }>,
  options: { stockedOnly?: boolean } = { stockedOnly: true },
): WarehouseSection[] {
  const stockedOnly = options.stockedOnly !== false;
  const bucket = new Map<string, WarehouseDisplayItem>();

  for (const [rawName, slot] of Object.entries(reserves)) {
    if (stockedOnly && slot.当前 <= 0) continue;
    const name = normalize_warehouse_item_name(rawName);
    const meta = warehouse_slot_meta(name);
    const existing = bucket.get(name);
    if (existing) {
      existing.当前 += slot.当前;
      existing.上限 = Math.max(existing.上限, slot.上限);
    } else {
      bucket.set(name, {
        name,
        当前: slot.当前,
        上限: slot.上限,
        grade: material_grade_for(name),
        top: meta.top,
        sub: meta.sub,
      });
    }
  }

  const sections: WarehouseSection[] = [];
  for (const top of WAREHOUSE_TOP_CATEGORIES) {
    const subs = WAREHOUSE_CATALOG[top];
    const subsections: WarehouseSubsection[] = [];
    for (const sub of Object.keys(subs)) {
      const items = [...bucket.values()]
        .filter(item => item.top === top && item.sub === sub)
        .sort((a, b) => a.name.localeCompare(b.name, 'zh-CN'));
      if (items.length) {
        subsections.push({ sub, items });
      }
    }
    const misc = [...bucket.values()].filter(
      item => item.top === top && !subsections.some(s => s.sub === item.sub),
    );
    if (misc.length) {
      subsections.push({
        sub: '其他',
        items: misc.sort((a, b) => a.name.localeCompare(b.name, 'zh-CN')),
      });
    }
    if (subsections.length) {
      sections.push({
        top,
        subsections,
        totalQty: subsections.reduce((s, sec) => s + sec.items.reduce((a, i) => a + i.当前, 0), 0),
      });
    }
  }

  return sections;
}

