/**
 * 面板指令执行器（重构步骤 3）
 *
 * 原则：面板只把操作写成 [指令] 进输入框；指令进入聊天记录后由这里执行。
 * 每条指令都必须幂等（管线一次加载会跑 1~3 遍），靠「已处理楼层水位」去重。
 */

import type { Schema } from '../schema'
import { consume_materials } from '../balance/economy'

const MARK = '世界'

function already_done(stat: Schema, key: string, message_id: number): boolean {
  const w = stat[MARK] as unknown as { 已处理面板指令?: Record<string, number> }
  const map = w.已处理面板指令 ?? {}
  return (map[key] ?? -1) >= message_id
}

function mark_done(stat: Schema, key: string, message_id: number): void {
  const w = stat[MARK] as unknown as { 已处理面板指令?: Record<string, number> }
  if (!w.已处理面板指令) w.已处理面板指令 = {}
  w.已处理面板指令[key] = message_id
}

type ExecResult = { changed: boolean; fail?: string }


/** 把指令里的物资名落到实际仓库键（容忍前后缀差异） */
function resolve_key(warehouse: Record<string, unknown>, raw: string): string | null {
  const want = String(raw ?? '').trim()
  if (!want) return null
  const keys = Object.keys(warehouse ?? {})
  if (keys.includes(want)) return want
  const candidates = keys.filter(k => k.includes(want) || want.includes(k))
  if (candidates.length === 0) return null
  // 取库存最多的那个，避免误扣冷门同名物
  candidates.sort((a, b) => Number((warehouse[b] as { 当前?: number })?.当前 ?? 0) - Number((warehouse[a] as { 当前?: number })?.当前 ?? 0))
  return candidates[0]
}


// [加固栅栏] / [修复围栏] 两个已删除系统（围栏来自废弃设计）的执行函数已移除


/** [投喂] 物资×N（扣料 + 饱食度/好感） */
function exec_feed(stat: Schema, name: string, text: string): ExecResult {
  const m = text.match(/\[投喂\][^\n]{0,40}?([^×x*\n]{2,12}?)\s*[×x*]\s*(\d+)/)
  if (!m) return { changed: false }
  const [, rawItem, nRaw] = m
  // 生成端文本是「[投喂] 物资：高蛋白棒×1」，捕获组会把「物资：」一起吃进来 → 剥掉前缀
  const item = rawItem.replace(/^.*?物资\s*[:：]\s*/, '').trim()
  const camp = stat.营地 as unknown as { 仓库储备: Record<string, unknown> }
  const key = resolve_key(camp.仓库储备 as never, item)
  console.info('[面板指令] 投喂解析', { item, key })
  if (!key) return { changed: false, fail: `投喂失败：仓库里没有「${item}」` }
  const r = consume_materials(camp.仓库储备 as never, { [key]: { 需求: Math.max(1, Number(nRaw)) } })
  if (!r.成功) return { changed: false, fail: `投喂失败：${item} 不足` }
  const npc = (stat.具名NPC as Record<string, Record<string, unknown>>)[name]
  if (!npc) return { changed: true }
  npc.饱食度 = Math.min(100, Number(npc.饱食度 ?? 0) + 20)
  npc.好感度 = Math.min(100, Number(npc.好感度 ?? 0) + 1)
  npc.心情 = '满足'
  return { changed: true }
}

/** [与X互动] 动作（按好感门槛预写 delta） */
function exec_interact(stat: Schema, name: string): ExecResult {
  const npc = (stat.具名NPC as Record<string, Record<string, unknown>>)[name]
  if (!npc) return { changed: false }
  const favor = Number(npc.好感度 ?? 0)
  const ok = favor >= 41
  const delta = ok ? 2 : 0
  npc.好感度 = Math.min(100, Number(npc.好感度 ?? 0) + delta)
  npc.心情 = ok ? '开心' : '戒备'
  return { changed: true, fail: ok ? undefined : `${name} 还不太愿意（好感 ${favor} 未达 41）` }
}


/** [规划新设施] 名称 · … · 材料：名×N、名×N · 工时 …（扣料 + 按功能写完工效果） */
function exec_plan_facility(stat: Schema, text: string): ExecResult {
  const head = text.match(/\[规划新设施\]\s*([^·\n]{1,20})/)
  const name = (head?.[1] ?? '').trim()
  if (!name) return { changed: false }

  const matBlock = text.match(/材料：([^·\n]{0,200})/)
  const demand: Record<string, { 需求: number }> = {}
  if (matBlock) {
    for (const piece of matBlock[1].split(/[、,，]/)) {
      // 生成端 formatMaterials 输出的是「名 数量」，世界书契约是「名×N」，两者都要认
      const m =
        piece.trim().match(/^(.{1,10}?)\s*[×x*]\s*(\d+)/) ??
        piece.trim().match(/^(.{1,10}?)\s+(\d+)$/)
      if (m) demand[m[1].trim()] = { 需求: Math.max(1, Number(m[2])) }
    }
  }

  if (Object.keys(demand).length === 0 && matBlock && matBlock[1].trim()) {
    return { changed: false, fail: `规划失败：材料字段无法解析（${matBlock[1].trim()}）` }
  }

  const camp = stat.营地 as unknown as {
    仓库储备: Record<string, unknown>
    当前建筑?: Record<string, Record<string, unknown>>
  }
  if (Object.keys(demand).length > 0) {
    const r = consume_materials(camp.仓库储备 as never, demand)
    if (!r.成功) {
      const short = Object.entries(r.缺口).map(([k, v]) => `${k} 缺 ${v}`).join('、')
      return { changed: false, fail: `规划失败：${short}` }
    }
  }

  const building = camp.当前建筑?.[name]
  if (building) {
    const scale = /大型/.test(text) ? 2 : /中型/.test(text) ? 1.4 : 1
    const blob = `${name}${String(building.功能 ?? '')}${String(building.描述 ?? '')}`
    const effect = { 防御值: 0, 栖居: 0 }
    if (/防御|墙|栏|栅栏|壁垒|塔/.test(blob)) effect.防御值 = Math.round(15 * scale)
    if (/栖居|住|棚|屋|帐篷|窝/.test(blob)) effect.栖居 = Math.round(10 * scale)
    building.完工效果 = effect
  }
  return { changed: true }
}

/** [工作队列·添加] 名称（类型）材料：… 工时：N小时 · 数量：N · 指派：X · 协同N人 */
function exec_work_add(stat: Schema, text: string): ExecResult {
  const head = text.match(/\[工作队列·添加\]\s*([^（）(\n]{1,24})(?:[（(]([^）)\n]{1,6})[）)])?/)
  const name = (head?.[1] ?? '').trim()
  if (!name) return { changed: false }
  const typeRaw = (head?.[2] ?? '生产').trim()
  const type = (['研发', '学习', '建造', '生产'] as const).find(x => typeRaw.includes(x)) ?? '生产'

  const hoursM = text.match(/工时：\s*([\d.]+)\s*小时/)
  const countM = text.match(/数量：\s*(\d+)/)
  const ownerM = text.match(/指派：\s*([^·\n]{1,12})/)
  const coopM = text.match(/协同\s*(\d+)\s*人/)

  const queue = (stat as unknown as { 工作队列: Record<string, Record<string, unknown>> }).工作队列
  if (queue[name]?.已扣料 === true) return { changed: false } // 已扣过料，幂等
  // 同名近似项也跳过（实机见过「公平分食制」与「公平分食制度」并存，进度各算各的）
  const similar = Object.keys(queue).find(
    k => k !== name && (k.includes(name) || name.includes(k)) && queue[k]?.已扣料 === true,
  )
  if (similar) return { changed: false }

  // 扣料：材料在开工时一次性扣除（此前完全不扣 → 原料无限）
  const matBlock = text.match(/材料：([^·\n]{0,200})/)
  const demand: Record<string, { 需求: number }> = {}
  if (matBlock) {
    for (const piece of matBlock[1].split(/[、,，]/)) {
      const seg = piece.trim()
      if (!seg || /无|部族会议/.test(seg)) continue
      const m = seg.match(/^(.{1,10}?)\s*[×x*]\s*(\d+)/) ?? seg.match(/^(.{1,10}?)\s+(\d+)$/)
      if (m) demand[m[1].trim()] = { 需求: Math.max(1, Number(m[2])) }
    }
  }
  if (Object.keys(demand).length > 0) {
    const camp = stat.营地 as unknown as { 仓库储备: Record<string, unknown> }
    const r = consume_materials(camp.仓库储备 as never, demand)
    if (!r.成功) {
      const short = Object.entries(r.缺口).map(([k, v]) => `${k} 缺 ${v}`).join('、')
      return { changed: false, fail: `开工失败：${short}` }
    }
    if (queue[name]) {
      // UI 路径会先建队列项；这里补扣成功后就地打标记
      queue[name].已扣料 = true
      return { changed: true }
    }
  }

  const assignees = ownerM ? ownerM[1].split(/[、,，]/).map(s => s.trim()).filter(Boolean) : []
  queue[name] = {
    类型: type,
    进度: 0,
    状态: assignees.length > 0 ? '进行中' : '待指派',
    具名指派: assignees,
    协同兽耳娘数: coopM ? Number(coopM[1]) : 0,
    效率加成: 0,
    负责人: ownerM ? ownerM[1].trim() : '',
    所需工时: hoursM ? Number(hoursM[1]) : 1,
    生产数量: countM ? Number(countM[1]) : 1,
    优先级: 5,
    已扣料: true,
  }
  return { changed: true }
}

/**
 * 自己扫用户楼层，收集「指令文本 + 所在楼层 id」。
 * 关键：水位必须按**用户楼层 id** 记，否则用 assistant 楼层号记录时，
 * 下轮 assistant 楼层变大 → 同一条旧指令被反复执行（重复扣料）。
 */
function collect_user_command_texts(max_message_id?: number): Array<{ text: string; id: number }> {
  if (typeof getChatMessages !== 'function') return []
  const range = typeof max_message_id === 'number' ? `0-${max_message_id}` : '0-{{lastMessageId}}'
  const out: Array<{ text: string; id: number }> = []
  for (const m of getChatMessages(range)) {
    if (m.role !== 'user') continue
    const text = String(m.message ?? '')
    if (/\[(添柴|投喂|与[^\]\n]{1,12}互动|规划新设施|工作队列·添加)\]/.test(text)) {
      out.push({ text, id: Number(m.message_id ?? 0) })
    }
  }
  return out
}

/**
 * 执行一条用户楼层里的面板指令（幂等，按 message_id 记水位）。
 * 返回失败原因供 toast 使用（当前只在 console 打印）。
 */
export function apply_panel_commands(stat: Schema, messageText: string, message_id: number): boolean {
  // 指令的权威来源是**用户楼层**；messageText（AI 正文）只在用户楼层为空时兜底
  const sources = collect_user_command_texts(message_id)
  if (sources.length === 0 && messageText) sources.push({ text: messageText, id: message_id })
  let any = false
  for (const item of sources) {
    // 水位按「该指令所在用户楼层」记，而不是当前 assistant 楼层
    if (apply_one_command_text(stat, item.text, item.id)) any = true
  }
  return any
}

function apply_one_command_text(stat: Schema, messageText: string, message_id: number): boolean {
  const texts: Array<{ key: string; run: () => ExecResult }> = []

  const ALL_INTERACT = [...messageText.matchAll(/\[与([^\]\n]{1,12})互动\]/g)]
  const feedIdx = messageText.indexOf('[投喂]')
  const actions = ['抱抱', '梳毛', '摸肚皮', '请求繁衍']

  if (feedIdx >= 0) {
    // 投喂归属：取 [投喂] 之前**最近**的一个 [与X互动]，避免喂错人（实机踩过：投喂琥珀写成林果）
    const nearest = ALL_INTERACT.filter(m => m.index !== undefined && m.index < feedIdx).at(-1)
    const feedName = nearest?.[1] ?? ALL_INTERACT.at(-1)?.[1]
    if (feedName) texts.push({ key: `feed:${feedName}`, run: () => exec_feed(stat, feedName, messageText) })
  }

  // 互动动作：每个 [与X互动] 动作 独立执行
  for (const m of ALL_INTERACT) {
    const name = m[1]
    const after = messageText.slice((m.index ?? 0) + m[0].length, (m.index ?? 0) + m[0].length + 24)
    const action = actions.find(a => after.includes(a))
    if (!action) continue
    if (feedIdx >= 0 && m.index !== undefined && m.index < feedIdx) continue // 这条是投喂前缀，已在上面处理
    texts.push({ key: `interact:${name}`, run: () => exec_interact(stat, name) })
  }
  if (/\[工作队列·添加\]/.test(messageText)) {
    // 按出现位置切片，逐段解析：此前循环里每次都传整段 messageText，
    // head 正则永远命中第一条 → 同楼多条只有第一条生效。
    const slices = messageText.split(/(?=\[工作队列·添加\])/).filter(s => s.includes('[工作队列·添加]'))
    slices.forEach((seg, i) => {
      texts.push({ key: `work_add:${i}`, run: () => exec_work_add(stat, seg) })
    })
  }
  if (/\[规划新设施\]/.test(messageText)) texts.push({ key: 'plan_facility', run: () => exec_plan_facility(stat, messageText) })

  let changed = false
  for (const { key, run } of texts) {
    if (already_done(stat, key, message_id)) continue
    const r = run()
    mark_done(stat, key, message_id)
    if (r.changed) changed = true
    if (r.fail) console.warn('[面板指令]', r.fail)
  }
  return changed
}
