import { add_slot_with_overflow } from '../../../balance/warehouse'
import _ from 'lodash';
import type { Schema } from '../../../schema';
import { unlockOneTimeWorkProject } from './workProjectStatus';
import { WORK_PROJECT_CATALOG } from '../constants/workProjectCatalog';

/**
 * 工时满即完工：直接从队列移除并归档日志，**不再**创建「交付清点」中间事务。
 * 建造 → 建筑已建成；研发 → 进度 100；生产 → 按目录的 outputs 批量入库（工具/装备入物品栏）；
 * 学习 → 按目录的 skill 提升目标 NPC 技能。
 */
export function complete_work_item(data: Schema, name: string, work: Schema['工作队列'][string]): void {
  const participants = [...work.具名指派];
  const project = WORK_PROJECT_CATALOG.find(p => p.name === name);

  // 建造项：直接落成，不再等模型写卡
  if (work.类型 === '建造') {
    const buildings = data.营地.当前建筑 as Record<string, { 建筑阶段?: string; 等级?: number }>
    // 升级项：队列名形如「削尖木桩护栏·升级至Lv2」
    const upgrade = name.match(/^(.+?)·升级至Lv(\d+)$/)
    if (upgrade) {
      const [, target, lvText] = upgrade
      const b = buildings[target]
      if (b) {
        b.等级 = Math.min(3, Math.max(1, Number(lvText) || 2))
        b.建筑阶段 = '已建成'
      } else {
        console.warn('[工作队列] 升级完工但找不到建筑:', target)
        return
      }
    }
    const names = Object.keys(buildings)
    // 优先全等；其次「建筑名完整出现在队列项名里」；不做反向包含（会把「大木屋」错配到「木屋」）
    // 审计 F3-09：原来是「第一个 included 的名字」，短名会误配长名
    // （队列「加固兽皮窝棚」会命中建筑「窝棚」）。改为取最长匹配。
    const contained = names
      .filter(k => k.length >= 2 && name.includes(k))
      .sort((a, b) => b.length - a.length)
    const key = names.find(k => k === name) ?? contained[0]
    if (key && buildings[key]) {
      buildings[key].建筑阶段 = '已建成'
    } else {
      // 找不到对应建筑：保留队列项，等模型补写建筑后再判定，避免「永久失败且无入口」
      console.warn('[工作队列] 建造完工但找不到对应建筑，保留队列项:', name)
      return
    }
  }
  // 研发项：直接置完成
  if (work.类型 === '研发' && data.世界.当前研发 && data.世界.当前研发 === name) {
    data.世界.研发进度 = 100;
  }

  // 生产项：按目录的 outputs 批量入库（没有 outputs 就发同名 1 件）
  if (work.类型 === '生产') {
    const outputs = project?.outputs ?? [{ name, count: 1 }];
    for (const out of outputs) {
      // 审计 F3-01（P0）：生产数量会同时放大工时与材料（见 WorkQueuePanel 的
      // scaleWorkHours / scaleMaterialString），完工人库必须同倍产出，否则玩家付 N 倍只得 1 份
      const batch = Math.max(1, Number(work.生产数量 ?? 1) || 1);
      const count = Math.max(1, Math.round(out.count)) * batch;
      if (project?.toInventory) {
        // 物品栏在【营地】层，条目结构 { 数量, 描述 }
        const camp = data.营地 as unknown as {
          物品栏?: Record<string, { 数量: number; 描述: string }>;
        };
        camp.物品栏 = camp.物品栏 ?? {};
        const slot = camp.物品栏[out.name] ?? { 数量: 0, 描述: '' };
        slot.数量 = Number(slot.数量 ?? 0) + count;
        camp.物品栏[out.name] = slot;
      } else {
        // 技术债清理：原来直接 `slot.当前 += count`，不钳上限也不转临时仓；
        // 统一走 add_slot_with_overflow（入账 + 钳上限 + 溢出转临时仓）
        add_slot_with_overflow(data as never, out.name, count);
      }
    }
  }

  // 学习项：提升目标 NPC 的技能（一次最多 +12）
  if (work.类型 === '学习' && project?.skill) {
    const gain = Math.min(12, Math.max(1, Math.round((work.进度 ?? 100) / 100 * 12)));
    for (const member of participants) {
      const npc = data.具名NPC[member] as unknown as { 技能?: Record<string, number> } | undefined;
      if (!npc?.技能) continue;
      npc.技能[project.skill] = Math.min(100, Number(npc.技能[project.skill] ?? 0) + gain);
    }
  }

  // 归档日志（标题用项目名，不再带「交付清点」前缀）
  const qty = work.生产数量 && work.生产数量 > 1 ? `×${work.生产数量}` : '';
  data.部族日志[`${data.世界.兽历}_工作_${name}`] = {
    日期: data.世界.兽历,
    类型: '工作',
    关联键: name,
    说明: `${work.类型}「${name}」${qty}已完工`,
    归档摘要: `${work.类型}完工：${name}`,
    具名参与: participants,
  } as never;

  unlockOneTimeWorkProject(data, name, work.类型);

  delete data.工作队列[name];
  console.info('[工作队列] 已完工并归档:', name);
}

function advance_work_item(
  data: Schema,
  name: string,
  work: Schema['工作队列'][string],
  hours: number,
): void {
  if (work.状态 !== '进行中' || work.具名指派.length === 0) {
    return;
  }

  const required = Math.max(0.1, work.所需工时 || 1);
  const efficiency = 1 + work.效率加成 / 100;
  const base = data.营地.无名族人基准效率 / 100;
  const effective_hours = hours * efficiency * base;
  const delta = (effective_hours / required) * 100;

  if (delta <= 0) {
    return;
  }

  work.进度 = _.clamp(work.进度 + delta, 0, 100);
  if (work.进度 >= 100) {
    complete_work_item(data, name, work);
  }
}

/** 推进工作队列进度（由 worldTimeTick 传入已结算的 hours） */
export function sync_work_queue_hours(data: Schema, hours: number): boolean {
  if (hours <= 0) {
    return false;
  }

  let changed = false;
  for (const name of Object.keys(data.工作队列)) {
    const work = data.工作队列[name];
    if (!work) {
      continue;
    }
    const before = work.进度;
    advance_work_item(data, name, work, hours);
    const after = data.工作队列[name];
    if (!after || after.进度 !== before) {
      changed = true;
    }
  }
  return changed;
}

/** AI 直接 patch 进度至 100 时，补走交付清点流程（与时间 tick 完工逻辑一致） */
export function reconcile_completed_work_queue(data: Schema): boolean {
  let changed = false;
  for (const name of [...Object.keys(data.工作队列)]) {
    const work = data.工作队列[name];
    if (!work || work.进度 < 100) {
      continue;
    }
    complete_work_item(data, name, work);
    changed = true;
  }
  return changed;
}
