import type { Schema } from '../schema';
import { record_squad_history } from '../balance/squadArchive';

type Stat = Schema;

const pending_disbands = new Set<string>();
/** UI 新建后、输入栏尚未写入时仍视为已授权 */
const pending_squad_creates = new Set<string>();

const USER_INPUT_RE = /<本轮用户输入>([\s\S]*?)<\/本轮用户输入>/i;
const SQUAD_USER_COMMAND_RE =
  /\[(新建编队|解散编队|编队调整|外出狩猎|外出采集|出发探索)\]/;
const DISBAND_RE = /\[解散编队\]\s*([^\n\[\]]+)/g;
/**
 * 队伍名 / 队长名允许的字符：**不含中英文标点**。
 * 实机踩过：原来用 `(\S+)` 抓队长，`[新建编队] 采集队，队长：朔春。` 会把句号也吃进去，
 * 队长变成「朔春。」→ 查不到具名 NPC → 整条指令被静默跳过，编队永远不会被创建。
 */
const NAME_CHARS = '[^\\s，,。．.、；;：:！!？?\\[\\]「」（）()\\n]+';
const CREATE_RE = new RegExp(`\\[新建编队\\]\\s*(${NAME_CHARS})(?:[，,]\\s*队长[：:]\\s*(${NAME_CHARS}))?`, 'g');
const ADD_MEMBER_RE = new RegExp(`\\[编队调整\\]\\s*将(${NAME_CHARS})编入「([^」]+)」`, 'g');
const REMOVE_MEMBER_RE = new RegExp(`\\[编队调整\\]\\s*将(${NAME_CHARS})移出「([^」]+)」`, 'g');

export type SquadCreateCommand = { name: string; leader: string | null };

/** 从一段文本里解析 `[新建编队] 队名，队长：队长名`（末尾标点不影响） */
export function parse_squad_create_commands(text: string): SquadCreateCommand[] {
  const out: SquadCreateCommand[] = [];
  if (!text) return out;
  CREATE_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = CREATE_RE.exec(text)) !== null) {
    const name = (m[1] ?? '').trim();
    const leader = (m[2] ?? '').trim();
    if (name) out.push({ name, leader: leader || null });
  }
  return out;
}

/**
 * UI（广阔大地）派队时写进输入栏的指令：
 *   `[外出采集] 队伍「采集队」前往「湖畔营地」，成员：朔春，计划时长 8 小时…`
 * 实机踩过：原来"出发"只认模型写的 `<npc_panel>`（朔春.当前任务），模型不写就永远待命，
 * 玩家点了「确认外出采集」也像卡住。现在这条指令本身就算机械依据。
 */
const DISPATCH_RE =
  /\[(外出采集|外出狩猎|出发探索|采集|狩猎|探索|外出探索)\][^\n]{0,80}?队伍[「"]([^」"\n]+)[」"](?:[^\n]{0,40}?前往[「"]([^」"\n]+)[」"])?/g;

/** 别名归一：世界书/EJS 允许裸写 [探索]/[采集]/[狩猎]（审查 P1-4） */
const DISPATCH_ALIAS: Record<string, keyof typeof DISPATCH_TARGET> = {
  探索: '出发探索',
  采集: '外出采集',
  狩猎: '外出狩猎',
  外出探索: '出发探索',
};

const DISPATCH_TARGET = {
  外出采集: { 状态: '采集中', 任务: '外出采集' },
  外出狩猎: { 状态: '狩猎中', 任务: '外出狩猎' },
  出发探索: { 状态: '探索中', 任务: '外出探索' },
} as const;

export type SquadDispatchCommand = { name: string; kind: keyof typeof DISPATCH_TARGET; region: string | null };

/** 解析派队指令（队名 + 行动 + 目标区域） */
export function parse_squad_dispatch_commands(text: string): SquadDispatchCommand[] {
  const out: SquadDispatchCommand[] = [];
  if (!text) return out;
  DISPATCH_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = DISPATCH_RE.exec(text)) !== null) {
    const kind = m[1] as keyof typeof DISPATCH_TARGET;
    const name = (m[2] ?? '').trim();
    const region = (m[3] ?? '').trim();
    if (!name || !(kind in DISPATCH_TARGET)) continue;
    out.push({ name, kind, region: region || null });
  }
  return out;
}

/** 把玩家派队指令落成"编队已出发"（状态 + 出发于 + 成员任务），不再等模型写面板 */
export function apply_user_squad_dispatch(stat: Stat): boolean {
  // 派队楼层水位：同一条派队指令只执行一次，避免归营后被历史指令重派（审查 P1-1）
  const __latestDispatch = latest_dispatch_floor()
  const __dispatched = Number((stat.世界 as unknown as { 已处理派队楼层?: number }).已处理派队楼层 ?? -1)
  if (__latestDispatch < 0 || __dispatched >= __latestDispatch) return false

  let changed = false;
  for (const text of extractUserInputs()) {
    for (const { name, kind, region } of parse_squad_dispatch_commands(text)) {
      const squad = stat.探索编队[name];
      if (!squad || squad.状态 !== '待命') continue;
      const target = DISPATCH_TARGET[(DISPATCH_ALIAS[kind] ?? kind) as keyof typeof DISPATCH_TARGET];
      if (!target) continue;
      squad.状态 = target.状态;
      if (region) squad.目标区域 = region;
      squad.出发于 = {
        生存天数: stat.世界.生存天数,
        时间: stat.世界.时间,
        兽历: stat.世界.兽历,
      };
      squad.已耗工时 = 0;
      squad.已开始计时 = false;
      for (const member of squad.具名成员) {
        const npc = stat.具名NPC[member];
        if (!npc) continue;
        npc.当前任务 = target.任务;
      }
      changed = true;
      console.info('[探索编队] 已按玩家指令出发:', name, target.状态);
      // 出发时顺手记一条历史（归队后不再留占位编队，玩家从"历史编队"一键复用）
      record_squad_history(stat, squad, `${stat.世界.兽历} ${stat.世界.时间}`);
    }
  }
  // 无论本轮是否真的改了状态，都要推进水位：
  // UI 点「出发」会先把 状态 改成 采集中，管线再扫到这条指令时会被「非待命」跳过，
  // 若此时不写水位，等队伍归营转回待命后，同一条历史指令会再次命中并重派。
  (stat.世界 as unknown as { 已处理派队楼层?: number }).已处理派队楼层 = __latestDispatch;
  return changed;
}

/** 读取酒馆聊天输入栏（含父页），供未发送指令识别 */
export function read_chat_input_bar_text(): string {
  const selectors = ['#send_textarea', '#send_textarea_holder textarea'];
  for (const selector of selectors) {
    const el = $(selector);
    if (el.length) {
      return String(el.val() ?? '').trim();
    }
  }
  try {
    const parent$ = (window.parent as Window & { $?: JQueryStatic }).$;
    if (parent$) {
      for (const selector of selectors) {
        const el = parent$(selector);
        if (el.length) {
          return String(el.val() ?? '').trim();
        }
      }
    }
  } catch {
    /* 跨域时忽略 */
  }
  return '';
}

/** UI 解散后、消息尚未发送时仍视为已解散 */
export function remember_disbanded_squad(name: string): void {
  const trimmed = name.trim();
  if (trimmed) {
    pending_disbands.add(trimmed);
    pending_squad_creates.delete(trimmed);
  }
}

/** UI 新建后、输入栏尚未写入时仍视为已授权 */
export function remember_pending_squad_create(name: string): void {
  const trimmed = name.trim();
  if (trimmed) {
    pending_squad_creates.add(trimmed);
    pending_disbands.delete(trimmed);
  }
}


/** 最新一条派队指令所在楼层（没有则 -1） */
function latest_dispatch_floor(): number {
  if (typeof getChatMessages !== 'function') return -1
  let max = -1
  for (const m of getChatMessages('0-{{lastMessageId}}')) {
    if (m.role !== 'user') continue
    DISPATCH_RE.lastIndex = 0
    if (DISPATCH_RE.test(m.message)) {
      DISPATCH_RE.lastIndex = 0
      if (m.message_id > max) max = m.message_id
    }
  }
  return max
}

function extractUserMessages(): string[] {
  if (typeof getChatMessages !== 'function') {
    return [];
  }
  return getChatMessages('0-{{lastMessageId}}')
    .filter(m => m.role === 'user')
    .flatMap(m => {
      const hit = USER_INPUT_RE.exec(m.message);
      USER_INPUT_RE.lastIndex = 0;
      if (hit?.[1]) {
        return [hit[1].trim()];
      }
      if (SQUAD_USER_COMMAND_RE.test(m.message)) {
        return [m.message];
      }
      return [];
    });
}

/** 已发送用户楼 + 输入栏待发送指令 */
function extractUserInputs(): string[] {
  const texts = extractUserMessages();
  const input_bar = read_chat_input_bar_text();
  if (input_bar && SQUAD_USER_COMMAND_RE.test(input_bar)) {
    texts.push(input_bar);
  }
  return texts;
}

function parse_created_squad_names_from_text(text: string): string[] {
  return parse_squad_create_commands(text).map(c => c.name);
}

/** 输入栏待发送 + UI pending 新建的编队名（已发送楼层会清掉 pending） */
export function collect_pending_authorized_squad_names(): Set<string> {
  const names = new Set<string>(pending_squad_creates);

  const input_bar = read_chat_input_bar_text();
  if (input_bar) {
    for (const name of parse_created_squad_names_from_text(input_bar)) {
      names.add(name);
    }
  }

  for (const text of extractUserMessages()) {
    for (const name of parse_created_squad_names_from_text(text)) {
      pending_squad_creates.delete(name);
    }
  }

  for (const name of get_disbanded_squad_names()) {
    names.delete(name);
    pending_squad_creates.delete(name);
  }
  return names;
}

export function has_unsent_squad_create_commands(): boolean {
  if (pending_squad_creates.size > 0) {
    return true;
  }
  const input_bar = read_chat_input_bar_text();
  return Boolean(input_bar && /\[新建编队\]/.test(input_bar));
}

/** 从聊天记录收集玩家显式解散的编队名 */
export function get_disbanded_squad_names(): Set<string> {
  const names = new Set<string>(pending_disbands);
  for (const text of extractUserInputs()) {
    DISBAND_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = DISBAND_RE.exec(text)) !== null) {
      const name = m[1].trim();
      if (name) {
        names.add(name);
        pending_disbands.delete(name);
      }
    }
  }
  return names;
}

type SquadRosterEvent = { squad: string; member: string; op: 'add' | 'remove' };

/** 按时间顺序回放编队调整，同一成员在同一编队内以最后一次操作为准 */
function collect_squad_roster_events(): SquadRosterEvent[] {
  const events: SquadRosterEvent[] = [];
  for (const text of extractUserInputs()) {
    ADD_MEMBER_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = ADD_MEMBER_RE.exec(text)) !== null) {
      const member = m[1].trim();
      const squad = m[2].trim();
      if (member && squad) {
        events.push({ squad, member, op: 'add' });
      }
    }
    REMOVE_MEMBER_RE.lastIndex = 0;
    while ((m = REMOVE_MEMBER_RE.exec(text)) !== null) {
      const member = m[1].trim();
      const squad = m[2].trim();
      if (member && squad) {
        events.push({ squad, member, op: 'remove' });
      }
    }
  }
  return events;
}

function resolve_explicit_squad_rosters(stat: Stat): Map<string, string[]> {
  const rosters = new Map<string, Set<string>>();

  for (const text of extractUserInputs()) {
    CREATE_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = CREATE_RE.exec(text)) !== null) {
      const name = m[1].trim();
      const leader = m[2]?.trim();
      if (!name || !leader || !stat.具名NPC[leader] || get_disbanded_squad_names().has(name)) {
        continue;
      }
      rosters.set(name, new Set([leader]));
    }
  }

  for (const { squad, member, op } of collect_squad_roster_events()) {
    if (!stat.具名NPC[member] || get_disbanded_squad_names().has(squad)) {
      continue;
    }
    const set = rosters.get(squad) ?? new Set<string>();
    if (op === 'add') {
      set.add(member);
    } else {
      set.delete(member);
    }
    rosters.set(squad, set);
  }

  const resolved = new Map<string, string[]>();
  for (const [name, members] of rosters) {
    resolved.set(name, [...members].filter(m => stat.具名NPC[m]));
  }
  return resolved;
}

function apply_explicit_idle_rosters(stat: Stat): boolean {
  const rosters = resolve_explicit_squad_rosters(stat);
  if (rosters.size === 0) {
    return false;
  }
  let changed = false;
  for (const [name, members] of rosters) {
    const squad = stat.探索编队[name];
    if (!squad || squad.状态 !== '待命') {
      continue;
    }
    if (!_.isEqual([...squad.具名成员].sort(), [...members].sort())) {
      squad.具名成员 = members;
      changed = true;
      console.info('[探索编队] 已按玩家最终指令同步待命 roster:', name, members);
    }
  }
  return changed;
}

/** 按 UI / 输入栏指令同步编队：解散优先，再补新建，最后以最终 roster 覆盖待命编队 */
export function apply_user_squad_commands(stat: Stat): boolean {
  let changed = false;

  for (const name of get_disbanded_squad_names()) {
    if (stat.探索编队[name]) {
      delete stat.探索编队[name];
      changed = true;
      console.info('[探索编队] 已按玩家指令移除:', name);
    }
  }

  const disbanded = get_disbanded_squad_names();
  const disbanded_persisted = new Set(stat.编队档案?.已解散 ?? []);
  for (const text of extractUserInputs()) {
    for (const { name, leader } of parse_squad_create_commands(text)) {
      if (disbanded.has(name) || disbanded_persisted.has(name)) {
        continue;
      }
      if (stat.探索编队[name]) {
        continue;
      }
      if (!leader || !stat.具名NPC[leader]) {
        console.warn('[探索编队] 指令里的队长找不到，跳过:', name, leader);
        continue;
      }
      stat.探索编队[name] = {
        状态: '待命',
        具名成员: [leader],
        无名队员数: 0,
        计划时长: 8,
        目标区域: '',
        已耗工时: 0,
        出行背包: {},
      };
      changed = true;
      console.info('[探索编队] 已按玩家指令创建:', name, leader);
    }
  }

  if (apply_explicit_idle_rosters(stat)) {
    changed = true;
  }

  return changed;
}
