/**
 * NPC 入营审批
 *
 * 世界书要求：AI 不得私自把 NPC 塞进【具名NPC】——营地里不能"聊着聊着多一个人"。
 * 规则：
 *   · 首次运行（已确认入营为空）→ 把当前【具名NPC】全部记为已确认（开局成员）
 *   · 之后任何新出现的【具名NPC】若不在已确认名单里 → 移入【未收入兽耳娘】等待玩家接纳
 *   · 玩家点「接纳入营」→ 移回【具名NPC】并写入已确认名单
 */
import type { Schema } from '../schema'
import { CORE_NPC_SKILLS } from '../constants/coreNpcSkills'

export type QuarantineResult = { moved: string[]; seeded: string[] }


/** 从聊天记录里收集所有 [邀请X入营] 指令 —— 以聊天记录为准，删楼即撤销 */
export function collect_invited_from_chat(maxMessageId?: number): string[] {
  try {
    if (typeof getChatMessages !== 'function') return []
    const range = typeof maxMessageId === 'number' && maxMessageId >= 0 ? `0-${maxMessageId}` : '0-{{lastMessageId}}'
    const names = new Set<string>()
    for (const msg of getChatMessages(range)) {
      const text = String(msg.message ?? '')
      const re = /\[邀请([^\]\n]{1,12})入营\]/g
      let hit: RegExpExecArray | null
      while ((hit = re.exec(text))) {
        const name = hit[1].trim()
        if (name) names.add(name)
      }
    }
    return [...names]
  } catch {
    return []
  }
}


/** 从聊天记录收集 [驱逐族人] X 指令 —— 删楼即撤销 */
export function collect_expelled_from_chat(): string[] {
  try {
    if (typeof getChatMessages !== 'function') return []
    const names = new Set<string>()
    for (const msg of getChatMessages('0-{{lastMessageId}}')) {
      const text = String(msg.message ?? '')
      const re = /\[驱逐族人\]\s*([^\]\n，,。]{1,12})/g
      let hit: RegExpExecArray | null
      while ((hit = re.exec(text))) {
        const name = hit[1].trim()
        if (name) names.add(name)
      }
    }
    return [...names]
  } catch {
    return []
  }
}

/** 把未经确认的具名NPC移到【未收入兽耳娘】 */
export function quarantine_unapproved_npcs(stat: Schema): QuarantineResult {
  const camp = stat.营地 as unknown as { 已确认入营?: string[] }
  const approved = new Set([...(camp.已确认入营 ?? []), ...collect_invited_from_chat()])
  const npcs = stat.具名NPC as Record<string, unknown>
  const names = Object.keys(npcs ?? {})

  // 首次运行：只批准「已知开局核心成员」（CORE_NPC_SKILLS 名单），
  // 绝不把 AI 当轮私自 insert 的陌生人一起洗霜华（审查 P1-6）
  if (approved.size === 0 && names.length > 0) {
    const core = new Set(Object.keys(CORE_NPC_SKILLS))
    const seeded = names.filter(n => core.has(n))
    if (seeded.length > 0) {
      camp.已确认入营 = seeded
      return { moved: [], seeded }
    }
    // 名单里没有任何已知核心成员 → 不播种，全部按未确认处理
  }

  const moved: string[] = []
  for (const name of names) {
    if (approved.has(name)) continue
    const unrec = stat.未收入兽耳娘 as Record<string, Record<string, unknown>>
    const src = npcs[name] as Record<string, unknown>
    unrec[name] = {
      种族: src.种族,
      档位: src.档位,
      行动履历: src.行动履历,
      好感度: src.好感度,
      心情: src.心情,
      状态: '在营地外等待回应',
      当前位置: '营地外围',
      当前想法: String(src.当前想法 ?? '这些人愿不愿意收留我。'),
      技能: src.技能,
    }
    delete npcs[name]
    moved.push(name)
    console.info('[入营审批] 未经玩家确认，移入未收入:', name)
  }
  return { moved, seeded: [] }
}

/** 只批准入营名单（不动数据）——「邀请入营」用：先批准，模型写进来的 NPC 才不会被拦回未收入 */
export function approve_npc_admission(stat: Schema, name: string): boolean {
  const camp = stat.营地 as unknown as { 已确认入营?: string[] }
  const list = camp.已确认入营 ?? []
  if (list.includes(name)) return false
  camp.已确认入营 = [...list, name]
  return true
}


/** 应用驱逐指令（回放式）：把被驱逐者从具名NPC与未收入中移除 */
export function apply_expelled_from_chat(stat: Schema): QuarantineResult {
  const expelled = collect_expelled_from_chat()
  const moved: string[] = []
  if (expelled.length === 0) return { moved, seeded: [] }
  const set = new Set(expelled)
  const npcs = stat.具名NPC as Record<string, unknown>
  for (const name of Object.keys(npcs ?? {})) {
    if (set.has(name)) {
      delete npcs[name]
      moved.push(name)
    }
  }
  const unrec = stat.未收入兽耳娘 as Record<string, unknown>
  for (const name of Object.keys(unrec ?? {})) {
    if (set.has(name)) {
      delete unrec[name]
      moved.push(name)
    }
  }
  if (moved.length) console.info('[驱逐] 已移除:', moved.join(','))
  return { moved, seeded: [] }
}

/** 玩家确认接纳（供 UI 调用） */
export function admit_npc(stat: Schema, name: string): boolean {
  const unrec = stat.未收入兽耳娘 as Record<string, Record<string, unknown>>
  const src = unrec?.[name]
  if (!src) return false
  const npcs = stat.具名NPC as Record<string, unknown>
  npcs[name] = {
    种族: src.种族 ?? '',
    职务: '',
    档位: src.档位 ?? '生疏',
    行动履历: src.行动履历,
    孕期: '未孕',
    受孕日: 0,
    好感度: src.好感度 ?? 20,
    体力: 60,
    心情: src.心情 ?? '平静',
    状态: '正常',
    当前位置: '营地',
    当前任务: '空闲',
    当前想法: src.当前想法 ?? '',
    饱食度: 30,
    种族系: '未知',
    互动状态: '无',
    对视时: { 动作: '', 表情: '', 心里话: '' },
    注视心声: '',
    技能: src.技能,
  }
  delete unrec[name]
  const camp = stat.营地 as unknown as { 已确认入营?: string[] }
  camp.已确认入营 = Array.from(new Set([...(camp.已确认入营 ?? []), name]))
  return true
}
