import { ensure_opening_status_placeholder } from '../../util/openingStatus';
import {
  run_stat_sync_after_generation,
  run_stat_sync_after_swipe,
  run_stat_sync_startup,
} from '../../util/statSyncOrchestrator';

$(() => {
  errorCatched(async () => {
    await waitGlobalInitialized('Mvu');

    eventOn(tavern_events.GENERATION_ENDED, (message_id: number) => {
      void (async () => {
        await run_stat_sync_after_generation(message_id);
        await ensure_opening_status_placeholder(message_id);
      })();
      // 兜底重试：生成刚结束时 MVU 有时还没写好 stat_data / 消息还没进 chat，
      // 第一次同步会静默跳过（实机表现为"时间/指标这一轮没动"）。
      // 管线本身幂等（水印 + 回放），重跑安全，所以 2.5s / 7s 各补一次。
      for (const delay of [2500, 7000]) {
        setTimeout(() => {
          void run_stat_sync_after_generation(message_id);
        }, delay);
      }
    });

    eventOn(tavern_events.MESSAGE_SWIPED, (message_id: number) => {
      void run_stat_sync_after_swipe(message_id);
    });

    // 删层：跳过一次同步，避免把本地残留状态写回上一楼层（审查 P2-2b）
    let skip_next_sync = false;
    eventOn(tavern_events.MESSAGE_DELETED, () => {
      skip_next_sync = true;
      console.info('[数据同步] 检测到删层，跳过下一轮同步');
      setTimeout(() => {
        skip_next_sync = false;
      }, 6000);
    });
    (globalThis as unknown as { __zx_should_skip_sync?: () => boolean }).__zx_should_skip_sync = () => {
      if (!skip_next_sync) return false;
      skip_next_sync = false;
      return true;
    };

    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
      // 这条脚本是**全局脚本**（不挂在某个楼层上），getCurrentMessageId() 会直接抛
      // "不要对全局脚本 iframe 调用 getMessageId!"（实机踩过）。拿不到就退到最新 assistant 楼层。
      let id: number | null = null;
      try {
        const current = getCurrentMessageId();
        if (typeof current === 'number' && current >= 0) {
          id = current;
        }
      } catch {
        id = null;
      }
      if (id === null) {
        try {
          const latest = getChatMessages(-1, { role: 'assistant' })[0];
          id = typeof latest?.message_id === 'number' ? latest.message_id : null;
        } catch {
          id = null;
        }
      }
      if (id !== null) {
        void ensure_opening_status_placeholder(id);
      }
    });

    const boot = () => void run_stat_sync_startup();
    void (async () => {
      await ensure_opening_status_placeholder();
      await boot();
    })();
    setTimeout(() => void boot(), 1500);
    setTimeout(() => void boot(), 4000);

    console.info('[坠星数据同步] 已加载');
  })();
});
