/**
 * 人口一致性（P5 前的临时闸口）
 *
 * D1 的写权矩阵里 `营地.人口` / `营地.族人构成` 是 U 级（只有出生/死亡/招募能改），
 * 但霜华名单还没落地。实机里模型一句"人口变成 30 人了"就把 14 改成 30、族人构成也顺手改了。
 *
 * 这里只做一个**能自证的不变量**：人口 = Σ族人构成。
 * 任一被单独改坏时，以「族人构成」为准把人口拉回来（并清掉非正整数/负数条目）。
 * 注意：如果模型把两个一起改（并保持自洽），这个闸口拦不住 —— 那需要真正的 resolver（P3）。
 */
import type { Schema } from '../schema'

type Camp = Schema['营地']

export function composition_total(camp: Camp): number {
  let total = 0
  for (const count of Object.values(camp.族人构成 ?? {})) {
    const n = Number(count)
    if (Number.isFinite(n) && n > 0) total += Math.floor(n)
  }
  return Math.floor(total)
}

/** @returns 是否发生了修正 */
export function align_population(camp: Camp): boolean {
  if (!camp || !camp.族人构成) return false
  let changed = false

  for (const [race, count] of Object.entries(camp.族人构成)) {
    const n = Number(count)
    const fixed = Number.isFinite(n) && n > 0 ? Math.floor(n) : 0
    if (fixed === 0) {
      delete camp.族人构成[race]
      changed = true
    } else if (fixed !== count) {
      camp.族人构成[race] = fixed
      changed = true
    }
  }

  const total = composition_total(camp)
  const population = Number(camp.人口 ?? 0)
  if (total > 0 && population !== total) {
    camp.人口 = total
    changed = true
  }
  return changed
}
