/**
 * 编队档案：历史编队 + 预设编队。
 *
 * 设计决定（驾驶员 2026-10-19）：**归队后不再死留一个待命编队占位**。
 * 原来"归队后保留原编队待命"是为了省一次重编，但一个从没出发的编队也会常驻，
 * 还会和"归来清点/待命"的判定打架。改成：出发时自动记一条历史，玩家在面板里一键复用。
 */
import type { Schema } from '../schema'

type Stat = Schema
type Squad = Schema['探索编队'][string]
type Template = Schema['编队档案']['历史'][number]

export const HISTORY_LIMIT = 8

/** 从编队拍一条模板 */
export function squad_to_template(squad: Squad, 记录于 = ''): Template {
  const first = squad.具名成员?.[0] ?? ''
  return {
    名称: first ? `${first}队` : '',
    具名成员: [...(squad.具名成员 ?? [])],
    无名队员数: Math.max(0, Math.floor(Number(squad.无名队员数) || 0)),
    计划时长: Math.min(8, Math.max(2, Math.floor(Number(squad.计划时长) || 8))),
    目标区域: String(squad.目标区域 ?? ''),
    记录于,
  }
}

/** 两条模板是否"同一种编队"（成员 + 区域 + 时长 + 同行人数一致） */
function same_config(a: Template, b: Template): boolean {
  return (
    a.计划时长 === b.计划时长 &&
    a.目标区域 === b.目标区域 &&
    a.无名队员数 === b.无名队员数 &&
    [...a.具名成员].sort().join(',') === [...b.具名成员].sort().join(',')
  )
}

function ensure_archive(stat: Stat): NonNullable<Stat['编队档案']> {
  if (!stat.编队档案) {
    stat.编队档案 = { 历史: [], 预设: [], 已解散: [], 已授权: [] }
  }
  if (!stat.编队档案.历史) stat.编队档案.历史 = []
  if (!stat.编队档案.预设) stat.编队档案.预设 = []
  if (!stat.编队档案.已解散) stat.编队档案.已解散 = []
  if (!stat.编队档案.已授权) stat.编队档案.已授权 = []
  return stat.编队档案
}

/** 记下"玩家解散了这个编队"（持久化，防止历史 [新建编队] 指令把它复活） */
export function mark_squad_disbanded(stat: Stat, 名称: string): boolean {
  const name = String(名称 ?? '').trim()
  if (!name) return false
  const archive = ensure_archive(stat)
  if (archive.已解散.includes(name)) return false
  archive.已解散.push(name)
  return true
}

/** 取消"已解散"（玩家复用同名编队时调） */
export function clear_squad_disbanded(stat: Stat, 名称: string): boolean {
  const archive = ensure_archive(stat)
  const next = archive.已解散.filter(n => n !== String(名称 ?? '').trim())
  if (next.length === archive.已解散.length) return false
  archive.已解散 = next
  return true
}

/**
 * 记一条历史（去重：同配置只留最新一条；最多 HISTORY_LIMIT 条）。
 * @returns 是否发生变化
 */
export function record_squad_history(stat: Stat, squad: Squad, 记录于 = ''): boolean {
  const template = squad_to_template(squad, 记录于)
  if (template.具名成员.length === 0) return false
  const archive = ensure_archive(stat)
  const list = archive.历史
  const rest = list.filter((item: Template) => !same_config(item, template))
  const next = [template, ...rest].slice(0, HISTORY_LIMIT)
  const changed = JSON.stringify(next) !== JSON.stringify(list)
  archive.历史 = next
  return changed
}

/** 存为预设（同名或同配置则覆盖） */
export function save_squad_preset(stat: Stat, squad: Squad, 记录于 = ''): boolean {
  const template = squad_to_template(squad, 记录于)
  if (template.具名成员.length === 0) return false
  const archive = ensure_archive(stat)
  const list = archive.预设
  const idx = list.findIndex((item: Template) => item.名称 === template.名称 || same_config(item, template))
  if (idx >= 0) {
    const changed = JSON.stringify(list[idx]) !== JSON.stringify(template)
    list[idx] = template
    return changed
  }
  list.push(template)
  return true
}

export function remove_squad_preset(stat: Stat, 名称: string): boolean {
  const archive = ensure_archive(stat)
  const next = archive.预设.filter((item: Template) => item.名称 !== 名称)
  if (next.length === archive.预设.length) return false
  archive.预设 = next
  return true
}

/**
 * 按模板建一个待命编队（成员必须是现存具名 NPC；队名已占用则跳过）。
 * @returns 是否发生变化
 */
export function apply_squad_template(stat: Stat, 名称: string, template: Template): boolean {
  const name = String(名称 || template.名称 || '').trim()
  if (!name) return false
  const members = (template.具名成员 ?? []).filter((m: string) => Boolean(stat.具名NPC?.[m]))
  if (members.length === 0) return false
  if (stat.探索编队[name]) return false
  // 复用同名编队 = 撤销"已解散"标记，否则历史指令又会被挡住
  clear_squad_disbanded(stat, name)
  // 记一条持久授权：面板一键建队没有对应的用户楼层，purge 会把它当 AI 乱建清掉
  const archive = ensure_archive(stat)
  archive.已授权 = [...archive.已授权.filter(n => n !== name), name].slice(-20)
  stat.探索编队[name] = {
    状态: '待命',
    具名成员: members,
    无名队员数: Math.max(0, Math.floor(Number(template.无名队员数) || 0)),
    计划时长: Math.min(8, Math.max(2, Math.floor(Number(template.计划时长) || 8))),
    目标区域: String(template.目标区域 ?? ''),
    已耗工时: 0,
    出行背包: {},
  }
  return true
}
